INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "match-pairs", "title": "Matching Items", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''match_pairs'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "hints": ["Look closely: the red sock goes with the red sock, the apple with the fruit basket, and the pencils with the pencil case.", "Not sure? Try the red sock first: it should go with the other red sock."], "title": "Matching Items", "payload": {"left": [{"id": "l1", "text_md": "**Red sock**"}, {"id": "l2", "text_md": "**Apple**"}, {"id": "l3", "text_md": "**Pencils**"}], "right": [{"id": "r1", "text_md": "Red sock"}, {"id": "r2", "text_md": "Fruit basket"}, {"id": "r3", "text_md": "Pencil case"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Hi! Zara is tidying her room. Remember last time you learned to group similar objects. Now, Zara has red socks, an apple, and a group of pencils. Help her match each item on the left with its correct place on the right. Drag or select the correct connection. If you make a mistake, I''ll give you a special hint.", "difficulty": 1, "explanation_md": "Great job! Zara matched each item with its place: the red sock with the red sock, the apple with the fruit basket, and the pencils with the pencil case. Everything is in order!", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/9e19adcd5376b8c6408056d047bbc46683ff164b74a7f09b14d90783784f62a6.mp3", "hash": "1ee71301fc7e64b0924c3dc67ca77cd719bd52baaaebaaaf43366c6b433a6449", "bytes": 100224, "voice": "Jennifer", "file_id": "lesson-audio/9e19adcd5376b8c6408056d047bbc46683ff164b74a7f09b14d90783784f62a6.mp3", "duration_ms": 16640}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/000ca241297ec32b20eb6c0ea645e2916c487d05d0b6c422da045577c7e7c6c9.mp3", "hash": "2e7aeaa64380b090f282c7a044d79e4d547f1fa98c01819eeb498c7b1ea788c3", "bytes": 55584, "voice": "Jennifer", "file_id": "lesson-audio/000ca241297ec32b20eb6c0ea645e2916c487d05d0b6c422da045577c7e7c6c9.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "budget-fit", "title": "El carrito de compras de Rho", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio budget_fit de forma aislada", "Confirmar que cada tipo de la familia money se genera y renderiza correctamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Suma los precios de los artículos que elijas y asegúrate de que no pasen de 100 MXN."], "title": "El carrito de compras de Rho", "payload": {"items": [{"id": "item-toy", "icon": "toy", "need": false, "label": "Juguete pequeño", "price": 80}, {"id": "item-snack", "icon": "snack", "need": false, "label": "Golosina", "price": 15}, {"id": "item-book", "icon": "book", "need": false, "label": "Libro de cuentos", "price": 25}, {"id": "item-pencil", "icon": "pencil", "need": true, "label": "Lápiz", "price": 5}], "budget": 100, "currency": "MXN", "must_buy_needs": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho quiere armar un carrito de compras sin pasarse de su presupuesto de **100 MXN**. Ayúdale a elegir los artículos que sumen **100 MXN** o menos.", "difficulty": 1, "explanation_md": "¡Muy bien! Rho pudo comprar todo lo que necesitaba sin pasarse de los 100 MXN. ¡Buen trabajo!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/46f042ee2f7eb36968be23c06bf2cb999349155002cfd0e77b0fb73e43156c33.mp3", "hash": "5e7bde426911c7a1af418e29ff2f5822cb2e98668e21812f1837ba218429b56a", "bytes": 58464, "voice": "Li", "file_id": "lesson-audio/46f042ee2f7eb36968be23c06bf2cb999349155002cfd0e77b0fb73e43156c33.mp3", "duration_ms": 9680}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/4752b2a45285ad63eb9f933951d238402e675103f27a6ff4d48cad635dd04125.mp3", "hash": "abf823af57a9ae1d4a958f33fb8b7f4401a2c45bb7c8a1d152d3512f52031367", "bytes": 44064, "voice": "Li", "file_id": "lesson-audio/4752b2a45285ad63eb9f933951d238402e675103f27a6ff4d48cad635dd04125.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "concept-reveal", "title": "Revelação de conceitos com Zara", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício concept_reveal de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Vire os cartões", "payload": {"cards": [{"icon": "book", "back_md": "Uma **história** é o que acontece em um conto: por exemplo, quando um cachorro se perde e sua dona o procura. Tem um começo, um problema e um fim.", "front_md": "O que é uma **história**?"}, {"icon": "person", "back_md": "Um **personagem** é quem vive a história: como a menina e o cachorro do conto. Pode ser uma pessoa, um animal ou um ser mágico.", "front_md": "O que é um **personagem**?"}, {"icon": "theater", "back_md": "Uma **cena** é um lugar e momento onde as coisas acontecem: como o parque onde o cachorro se perdeu. Cada cena é como uma foto da história.", "front_md": "O que é uma **cena**?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara preparou cartões com conceitos que você já viu. Vire cada um para lembrar o que aprendeu com Dina e Zara na história da semana passada. Como vimos na lição anterior com Dina procurando seu cachorro, esses conceitos vão te ajudar a entender melhor essa história.", "difficulty": 1, "explanation_md": "Cada cartão te ajuda a lembrar partes importantes de uma história. Por exemplo, na história ''O cachorro perdido'', a **história** é o que aconteceu (o cachorro se perdeu e o procuraram), o **personagem** é o cachorro e a menina, e a **cena** é o parque onde tudo ocorreu. Assim montamos uma história!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/15779b660fb0524832c8d6688c485d24cf82b4ab44a55a5d6e2699d9bd1339e8.mp3", "hash": "f13932b999bf2602e81b1eb3d6a16892a3576c21a598513c4d0d54d9d8e8096e", "bytes": 89568, "voice": "Ryan", "file_id": "lesson-audio/15779b660fb0524832c8d6688c485d24cf82b4ab44a55a5d6e2699d9bd1339e8.mp3", "duration_ms": 14880}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/28bceabe6bddb8d872f0c4a42358e832454cf6b193f2727ff42ff22d17aed6a9.mp3", "hash": "48879d90ec249650d40d1169dbf3a13f1f3e5b096aedf650e7759497d601c582", "bytes": 53136, "voice": "Ryan", "file_id": "lesson-audio/28bceabe6bddb8d872f0c4a42358e832454cf6b193f2727ff42ff22d17aed6a9.mp3", "duration_ms": 8800}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/701f0075da2a9b401089e341723f3ff300ccd7e1683fbd2c2a2d399924a6a7c6.mp3", "hash": "77a5db18372827a754c3211974d528ff07e5b24811053de81f47e01128a99ed5", "bytes": 46368, "voice": "Ryan", "file_id": "lesson-audio/701f0075da2a9b401089e341723f3ff300ccd7e1683fbd2c2a2d399924a6a7c6.mp3", "duration_ms": 7680}, "s1-concept-reveal.card.2.back": {"url": "http://localhost:4006/files/lesson-audio/18665532e86d9a2e5d8d3b7ccee40186d29d09c0eaf3d44b5e9708c38ec2a3db.mp3", "hash": "08272aacb731d3ceea4f48cb7d6c9229f901fd888d6143b6b20728f2e3dd695d", "bytes": 52128, "voice": "Ryan", "file_id": "lesson-audio/18665532e86d9a2e5d8d3b7ccee40186d29d09c0eaf3d44b5e9708c38ec2a3db.mp3", "duration_ms": 8640}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/0312b95347071bd8031ba9db11ef35522e3f484dce933c1e7f70e72a17ef0dc7.mp3", "hash": "dec09f521849561971968e662b94433b8150e83d4dfb0610000a133a2d647e50", "bytes": 111744, "voice": "Ryan", "file_id": "lesson-audio/0312b95347071bd8031ba9db11ef35522e3f484dce933c1e7f70e72a17ef0dc7.mp3", "duration_ms": 18560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "Ahorrar para lo que quiero", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar la diferencia entre un deseo y una necesidad", "Explicar por qué es importante ahorrar para cumplir metas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Recuerda que ahorrar es guardar dinero poco a poco para una meta.", "Divide el costo total entre lo que ahorras cada semana."], "title": "Ahorrar para lo que quiero", "payload": {"ideas": [{"icon": "savings", "title": "Ahorrar", "body_md": "Guardar dinero para usarlo después en algo importante."}, {"icon": "goal", "title": "Meta", "body_md": "Algo que quieres lograr, como comprar un juguete o una bicicleta."}, {"icon": "choice", "title": "Necesidad vs. Deseo", "body_md": "Las necesidades son cosas que debes tener (comida, ropa). Los deseos son cosas que te gustaría tener (juguetes, golosinas)."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quiere comprar una bicicleta nueva que cuesta 500 pesos. Cada semana ahorra 50 pesos de su mesada. ¿Cuántas semanas necesita ahorrar para comprar la bicicleta?", "difficulty": 1, "explanation_md": "Dina necesita ahorrar durante 10 semanas: 500 ÷ 50 = 10. Ahorrar te ayuda a conseguir lo que quieres sin pedir prestado.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/21100a838d55b90c5348b61fb48d93932db6c1a9d10265a37a3a175898bce17a.mp3", "hash": "219ada7461ea1edd9e2924861566cbe2cc173f384ef7ed93b31decf942348027", "bytes": 17136, "voice": "Li", "file_id": "lesson-audio/21100a838d55b90c5348b61fb48d93932db6c1a9d10265a37a3a175898bce17a.mp3", "duration_ms": 2800}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/08dafb1cdae00f81fe856352487faaf2f89cd433318f0a89867d25bead49cdad.mp3", "hash": "f607bbbf7fa19d6561ee78df8f7d86ba69b77047a3c2d5ffa4e7401d86f96f72", "bytes": 21888, "voice": "Li", "file_id": "lesson-audio/08dafb1cdae00f81fe856352487faaf2f89cd433318f0a89867d25bead49cdad.mp3", "duration_ms": 3600}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/798e7e1d877338ead36f35c4234c3015876f01d5ee2e7c90c301dc7d8715b78a.mp3", "hash": "8cf27cfd0d4125c05a699d2bbe65a4f501d3f143ce8b903041d56dac0b804ea1", "bytes": 48816, "voice": "Li", "file_id": "lesson-audio/798e7e1d877338ead36f35c4234c3015876f01d5ee2e7c90c301dc7d8715b78a.mp3", "duration_ms": 8080}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/1f2d10d6737a9e2f873efd593fa0f551dce174fafff161c0c310d4ed71b6d8a9.mp3", "hash": "c0ea0224ae9f64529660161254eb1e6ddab75b3b26b42afcee52082fa11a80b6", "bytes": 66528, "voice": "Li", "file_id": "lesson-audio/1f2d10d6737a9e2f873efd593fa0f551dce174fafff161c0c310d4ed71b6d8a9.mp3", "duration_ms": 11040}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/9f457270a94795a46876915a43655d582a0c2c83df9f67382e0adb25b5014ca0.mp3", "hash": "f9f709bbacb5a47b7d2d60b3469727f0732f7015be84328b00743ecbcaabcdbf", "bytes": 51264, "voice": "Li", "file_id": "lesson-audio/9f457270a94795a46876915a43655d582a0c2c83df9f67382e0adb25b5014ca0.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "Saving for what I want", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the difference between a want and a need", "Explain why it is important to save to reach goals"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Remember that saving is putting money aside little by little for a goal.", "Divide the total cost by what you save each week."], "title": "Saving for what I want", "payload": {"ideas": [{"icon": "savings", "title": "Saving", "body_md": "Putting money aside to use later for something important."}, {"icon": "goal", "title": "Goal", "body_md": "Something you want to achieve, like buying a toy or a bicycle."}, {"icon": "choice", "title": "Need vs. Want", "body_md": "Needs are things you must have (food, clothes). Wants are things you would like to have (toys, treats)."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina wants to buy a new bicycle that costs 500 pesos. She saves 50 pesos from her allowance each week. How many weeks does she need to save to buy the bicycle?", "difficulty": 1, "explanation_md": "Dina needs to save for 10 weeks: 500 ÷ 50 = 10. Saving helps you get what you want without borrowing.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/a30bd9d2f77c591e3af1564a8d5e06a3b271c20c9acb94f0a9d872607793dd83.mp3", "hash": "4650262272286aaaee4697c506fd8a7e1164f45443216c609af3c33e78c01979", "bytes": 15696, "voice": "Jennifer", "file_id": "lesson-audio/a30bd9d2f77c591e3af1564a8d5e06a3b271c20c9acb94f0a9d872607793dd83.mp3", "duration_ms": 2560}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/bf4da5b7bb3aed6a26689c0f8a05ae3608066ce27ee4892835a62766567fa3c2.mp3", "hash": "21af269194fd8528269170631360639ae2f4aad37c7f6965b0b33e517c3527dd", "bytes": 25344, "voice": "Jennifer", "file_id": "lesson-audio/bf4da5b7bb3aed6a26689c0f8a05ae3608066ce27ee4892835a62766567fa3c2.mp3", "duration_ms": 4160}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/2f6220bd6d1e27f3304364a17db323d8367d17f37ba022e0f3701831e87e9f46.mp3", "hash": "79dd84320a2d02f2370d39d4fbea4060323596da6de4d9943d5235148d3e2e55", "bytes": 50688, "voice": "Jennifer", "file_id": "lesson-audio/2f6220bd6d1e27f3304364a17db323d8367d17f37ba022e0f3701831e87e9f46.mp3", "duration_ms": 8400}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/ddb4010aaee88a13ad04956eab8ea9c51dc74c9df30ae622bdbe0bdbdd2c56aa.mp3", "hash": "d3b36068bdf3b541c85b914ec44ed2a80c3b99336f239d15aaf93509984d78fb", "bytes": 60336, "voice": "Jennifer", "file_id": "lesson-audio/ddb4010aaee88a13ad04956eab8ea9c51dc74c9df30ae622bdbe0bdbdd2c56aa.mp3", "duration_ms": 10000}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/450e0ec9369580e1722ac4a585cbe5c16ecb859360b5eaa72196c148242e32bf.mp3", "hash": "587430e4a0c1bd42a9b2f4490b09c73c3c99e145542a3782bddc08f34b301222", "bytes": 44928, "voice": "Jennifer", "file_id": "lesson-audio/450e0ec9369580e1722ac4a585cbe5c16ecb859360b5eaa72196c148242e32bf.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "order-steps", "title": "Ordenando passos com Rho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''order_steps'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Pense no que deve ser feito primeiro: cortar o limão ou espremê-lo?", "Depois de espremer, o que vem a seguir?"], "title": "Ordene os passos", "payload": {"items": [{"id": "step1", "text_md": "Cortar o limão ao meio"}, {"id": "step2", "text_md": "Espremer o suco do limão"}, {"id": "step3", "text_md": "Adicionar água e açúcar ao suco"}, {"id": "step4", "text_md": "Mexer bem a mistura"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Sou Rho. Lembra que ontem com Dina você aprendeu a seguir instruções. Hoje preciso da sua ajuda para ordenar os passos para preparar uma limonada. Arraste os passos para a ordem correta.", "difficulty": 1, "explanation_md": "A ordem correta é: primeiro cortar o limão ao meio, depois espremer o suco, em seguida adicionar água e açúcar, e finalmente mexer.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/6c7f219f0dc16c2ef2594384399f54ccbf83e827e8af6f0066ade4e9c0a21058.mp3", "hash": "acf5d488beabc95a762f21804428ea122bded68e04923da3eca0d4675c4e02c0", "bytes": 72864, "voice": "Ryan", "file_id": "lesson-audio/6c7f219f0dc16c2ef2594384399f54ccbf83e827e8af6f0066ade4e9c0a21058.mp3", "duration_ms": 12080}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/88f5c47b3e3b802e8a446a7d5a6b18df5403576233b3e999d9cc0064600ec413.mp3", "hash": "05275374b80e4d6d5708f857a83ccfd46842c375280f0e90da8da236eff2959a", "bytes": 61776, "voice": "Ryan", "file_id": "lesson-audio/88f5c47b3e3b802e8a446a7d5a6b18df5403576233b3e999d9cc0064600ec413.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "budget-fit", "title": "O carrinho de compras da Rho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício budget_fit de forma isolada", "Confirmar que cada tipo da família money é gerado e renderizado corretamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Some os preços dos itens que você escolher e certifique-se de que não passem de 100 MXN."], "title": "O carrinho de compras da Rho", "payload": {"items": [{"id": "item-toy", "icon": "toy", "need": false, "label": "Brinquedo pequeno", "price": 80}, {"id": "item-snack", "icon": "snack", "need": false, "label": "Guloseima", "price": 15}, {"id": "item-book", "icon": "book", "need": false, "label": "Livro de histórias", "price": 25}, {"id": "item-pencil", "icon": "pencil", "need": true, "label": "Lápis", "price": 5}], "budget": 100, "currency": "MXN", "must_buy_needs": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho quer montar um carrinho de compras sem ultrapassar seu orçamento de **100 MXN**. Ajude-a a escolher os itens que somem **100 MXN** ou menos.", "difficulty": 1, "explanation_md": "Muito bem! Rho conseguiu comprar tudo o que precisava sem ultrapassar os 100 MXN. Bom trabalho!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/f83df0309904ef8142807168056c263d9c31b7061b88a2ada1880f20c0c99cf5.mp3", "hash": "0ee979ae96c089a17209375a2082791e1ddadc86017a7d5d0834a93d8c26898d", "bytes": 61776, "voice": "Ryan", "file_id": "lesson-audio/f83df0309904ef8142807168056c263d9c31b7061b88a2ada1880f20c0c99cf5.mp3", "duration_ms": 10240}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/666f449964dc838d885e295cda73f4acd1cd405cd95af2bb8540d86960bbea51.mp3", "hash": "4e449b36db142bc9d02309463308ad1edf908ec3b746926ea4651f1b56543ce1", "bytes": 45504, "voice": "Ryan", "file_id": "lesson-audio/666f449964dc838d885e295cda73f4acd1cd405cd95af2bb8540d86960bbea51.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Repaso con Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar los conceptos de la lección anterior con un ejemplo concreto."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": ["Piensa en el ejemplo de las monedas que viste antes."], "title": "Repaso con Dina", "payload": {"recap_md": "Has aprendido sobre números y ejemplos con monedas. ¡Sigue así!", "mood_prompt_md": "¿Cómo te sientes con este repaso?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! Soy Dina. ¿Recuerdas cuando la semana pasada ahorré 5 monedas? Hoy vamos a repasar lo que aprendiste. Primero, dime: ¿cuántas monedas ahorré?", "difficulty": 1, "explanation_md": "¡Muy bien! Ahorré 5 monedas. Eso es un número. Ahora recuerda: los números nos ayudan a contar cosas.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/83a2b3a5d87b110180866f6d91dbec3730eb0bb0126a68d707f43aa9eab00cf5.mp3", "hash": "3437f70b1dfee564b0f8d6eb340dd0cc7ecb898e11dda71f74a0c84e7811e2bf", "bytes": 22464, "voice": "Li", "file_id": "lesson-audio/83a2b3a5d87b110180866f6d91dbec3730eb0bb0126a68d707f43aa9eab00cf5.mp3", "duration_ms": 3680}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/dbfdebe9e1e824894d1bdd409979e2bad99b570d105b82bd1338c9dce5b78432.mp3", "hash": "613e106f92955d36a2d95ea21da59033adcc834eb1a1731691d1c10fd0ad0055", "bytes": 52128, "voice": "Li", "file_id": "lesson-audio/dbfdebe9e1e824894d1bdd409979e2bad99b570d105b82bd1338c9dce5b78432.mp3", "duration_ms": 8640}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/7c5a95cee82abf3870fa24e66f7d7c858ea010e725415852a298893e5bd9353e.mp3", "hash": "f20b38c86246660fc5c82e1dc0bb6c8747e8dafec9d360ca4194443b670508dc", "bytes": 59904, "voice": "Li", "file_id": "lesson-audio/7c5a95cee82abf3870fa24e66f7d7c858ea010e725415852a298893e5bd9353e.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Revisão com Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar os conceitos da lição anterior com um exemplo concreto."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": ["Pense no exemplo das moedas que você viu antes."], "title": "Revisão com Dina", "payload": {"recap_md": "Você aprendeu sobre números e exemplos com moedas. Continue assim!", "mood_prompt_md": "Como você se sente com esta revisão?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Sou a Dina. Lembra quando na semana passada eu economizei 5 moedas? Hoje vamos revisar o que você aprendeu. Primeiro, me diga: quantas moedas eu economizei?", "difficulty": 1, "explanation_md": "Muito bem! Eu economizei 5 moedas. Isso é um número. Agora lembre: os números nos ajudam a contar coisas.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/38d23e58aa5f7538e814b7a50a7a2046b22a384373176e6f10b3a4bb089d7dc7.mp3", "hash": "ee47c06688b96355d978b605a9b2b60808c4b26ba6efc39de1008707152ca9c3", "bytes": 24768, "voice": "Ryan", "file_id": "lesson-audio/38d23e58aa5f7538e814b7a50a7a2046b22a384373176e6f10b3a4bb089d7dc7.mp3", "duration_ms": 4080}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/0342ccced2ff1e6517e6be63a2a3dbd93a6450a53fadc7106c5985d2c67de645.mp3", "hash": "647d4f4d23ab6df7220c17eb7586f3bad010ba9cc060c0e9ef76d15b5b81871d", "bytes": 78048, "voice": "Ryan", "file_id": "lesson-audio/0342ccced2ff1e6517e6be63a2a3dbd93a6450a53fadc7106c5985d2c67de645.mp3", "duration_ms": 12960}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c4d7b2738cdade687ce02b64071eec458542428494093b48fd889ba6c97839d.mp3", "hash": "a27e34acd40b411cd4f707bdd52a20d79aae40d47634d0c53b28fd6baa93ae44", "bytes": 56016, "voice": "Ryan", "file_id": "lesson-audio/2c4d7b2738cdade687ce02b64071eec458542428494093b48fd889ba6c97839d.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "quiz-mcq", "title": "La decisión de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar la decisión de gastar o ahorrar dinero en una situación concreta."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 0, "type": "quiz_mcq", "hints": ["Piensa: si Liruf quiere ahorrar, ¿gastar o guardar el dinero?"], "title": "La decisión de Liruf", "payload": {"options": [{"id": "a", "text_md": "Comprar la manzana", "rationale_md": "Gastar reduce sus ahorros, no es la mejor opción para ahorrar."}, {"id": "b", "text_md": "Guardar el dinero", "rationale_md": "Correcto. Guardar el dinero aumenta sus ahorros."}, {"id": "c", "text_md": "Regalar el dinero", "rationale_md": "Regalar también reduce sus ahorros."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendimos antes con Dina y su alcancía, ahorrar es guardar dinero para el futuro. Liruf ha ahorrado 10 pesos en su alcancía. Puede comprar una manzana por 5 pesos o guardar el dinero. ¿Qué debe hacer Liruf para seguir ahorrando?", "difficulty": 1, "explanation_md": "¡Muy bien! Si Liruf quiere ahorrar, lo mejor es guardar el dinero. Gastar reduce sus ahorros.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/e68b620f5c85977d1d96638fcd67a033c62b42dad268afcb940acb7b6f809638.mp3", "hash": "f8e36f61d15e25f887856f17bde26da665eef8e51c9ae7b0b8a0a39cc19b7d69", "bytes": 93024, "voice": "Li", "file_id": "lesson-audio/e68b620f5c85977d1d96638fcd67a033c62b42dad268afcb940acb7b6f809638.mp3", "duration_ms": 15440}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/26692717d9c06492d5a87d169c267f1f03f84a0953105887bb5859680b1a3dc7.mp3", "hash": "607bbb05aac3b478727cb7b26bea9d18b5c1ff44af1fe4798c6b64fdaf0a67b2", "bytes": 34848, "voice": "Li", "file_id": "lesson-audio/26692717d9c06492d5a87d169c267f1f03f84a0953105887bb5859680b1a3dc7.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "piggy-split", "title": "Práctica: Piggy Split", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia money se genera y renderiza correctamente.", "Verificar el ejercicio ''piggy_split'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["Recuerda que los frascos deben sumar el total de 80 MXN.", "Puedes usar monedas de 1, 2, 5, 10 y 20 MXN para formar las cantidades."], "title": "Repartiendo en frascos", "payload": {"jars": [{"id": "jar-golosinas", "icon": "candy", "label": "Golosinas", "hint_md": "Precio de referencia de una golosina: 15 MXN."}, {"id": "jar-juguetes", "icon": "toy", "label": "Juguetes", "hint_md": "Precio de referencia de un juguete pequeño: 80 MXN."}], "step": 1, "unit": "MXN", "income": 80}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! En el ejercicio anterior verificaste ''make_change''. Ahora vamos a practicar ''piggy_split''. Zara ganó **80 MXN** por ayudar en la tienda. Quiere repartir ese dinero en sus frascos de ahorro: uno para *golosinas* y otro para *juguetes*. ¿Puedes ayudarla a dividir los 80 MXN correctamente?", "difficulty": 1, "explanation_md": "Zara dividió 80 MXN en dos frascos: 15 MXN para golosinas y 65 MXN para juguetes. ¡Así puede ahorrar para lo que más quiere!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-juguetes": {"max": 65, "min": 65}, "jar-golosinas": {"max": 15, "min": 15}}, "rationale_md": "Zara quiere ahorrar 15 MXN para golosinas y el resto (65 MXN) para juguetes. 15 + 65 = 80 MXN."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/fcf22068fbe0cee73695f075178cccc72299a7964f4739df1edd62b408a4622a.mp3", "hash": "5fc3621144bc2de00aceafdd4243e2fe1b3965b8295e218492b540f1690f5d40", "bytes": 115056, "voice": "Li", "file_id": "lesson-audio/fcf22068fbe0cee73695f075178cccc72299a7964f4739df1edd62b408a4622a.mp3", "duration_ms": 19120}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/28fabd9e0eee33021da71201308e44a7171cd9490dcf3e50ccaab89078ced1d5.mp3", "hash": "a4450b494b8697fdcd1080a7366163f19d135f2413432b5149a3b6203ac98132", "bytes": 62208, "voice": "Li", "file_id": "lesson-audio/28fabd9e0eee33021da71201308e44a7171cd9490dcf3e50ccaab89078ced1d5.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "quiz-mcq", "title": "A decisão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Praticar a decisão de gastar ou poupar dinheiro em uma situação concreta."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 0, "type": "quiz_mcq", "hints": ["Pense: se Liruf quer poupar, gastar ou guardar o dinheiro?"], "title": "A decisão de Liruf", "payload": {"options": [{"id": "a", "text_md": "Comprar a maçã", "rationale_md": "Gastar reduz suas economias, não é a melhor opção para poupar."}, {"id": "b", "text_md": "Guardar o dinheiro", "rationale_md": "Correto. Guardar o dinheiro aumenta suas economias."}, {"id": "c", "text_md": "Dar o dinheiro", "rationale_md": "Dar também reduz suas economias."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendemos antes com Dina e seu cofrinho, poupar é guardar dinheiro para o futuro. Liruf poupou 10 reais em seu cofrinho. Ele pode comprar uma maçã por 5 reais ou guardar o dinheiro. O que Liruf deve fazer para continuar poupando?", "difficulty": 1, "explanation_md": "Muito bem! Se Liruf quer poupar, o melhor é guardar o dinheiro. Gastar reduz suas economias.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/9b5fb523cf0d73a64f3eb7eb9caf78406e5aeefcd5ba0095df1ce9253052398b.mp3", "hash": "c9afa8ea599828ba2c7d2dcf476c328054eb0912db643049158e41897f0c974c", "bytes": 94464, "voice": "Ryan", "file_id": "lesson-audio/9b5fb523cf0d73a64f3eb7eb9caf78406e5aeefcd5ba0095df1ce9253052398b.mp3", "duration_ms": 15680}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/9dd15d2d2bd5c6c796cbf96a075a1076e7bfbf9d1c7866218a0677a0e3b22e32.mp3", "hash": "9be8064aa7dd462a4dcd29cdc5f5a294e86e870c1ceed58c7177ea47a3bea3e9", "bytes": 42624, "voice": "Ryan", "file_id": "lesson-audio/9dd15d2d2bd5c6c796cbf96a075a1076e7bfbf9d1c7866218a0677a0e3b22e32.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "true-false", "title": "Verificar el ejercicio ''true_false'' de forma aislada", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que el tipo true_false se genera y renderiza correctamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Piensa si Rho tiene suficiente dinero para comprar el helado.", "Compara el dinero que tiene con el precio."], "title": "Verdadero o falso: ¿Rho puede comprar un helado?", "payload": {"statement_md": "Rho puede comprar un helado de 8 monedas si tiene 10 monedas.", "justifications": [{"id": "j1", "text_md": "Porque 10 monedas son más que 8 monedas, así que le alcanza."}, {"id": "j2", "text_md": "Porque 10 monedas son menos que 8 monedas, así que no le alcanza."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho tiene 10 monedas y quiere comprar un helado que cuesta 8 monedas. ¿Esto es verdadero o falso? Ayúdale a elegir la respuesta correcta y la justificación adecuada.", "difficulty": 1, "explanation_md": "La afirmación es verdadera: Rho tiene 10 monedas y el helado cuesta 8, así que sí puede comprarlo. La justificación correcta explica que tiene suficiente dinero.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f2256d3bde44db39d403480268b06567a910db88a48be9298331e0f361aab78.mp3", "hash": "2eb56e11062090a75c997b047770f75b2dacfe85b0f99de4cc94af9f20fe0c6d", "bytes": 58464, "voice": "Li", "file_id": "lesson-audio/8f2256d3bde44db39d403480268b06567a910db88a48be9298331e0f361aab78.mp3", "duration_ms": 9680}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/d26a51bc18870ead6d86478560373c8046aaf24f30b8a5ce0a37d88434969e3d.mp3", "hash": "3cd391997a4aa13250c24bf7b8034c7b67d23b8fbf5ea6e6eabfbe7166444058", "bytes": 58464, "voice": "Li", "file_id": "lesson-audio/d26a51bc18870ead6d86478560373c8046aaf24f30b8a5ce0a37d88434969e3d.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "true-false", "title": "Verify the ''true_false'' exercise in isolation", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that the true_false type generates and renders correctly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Think about whether Rho has enough money to buy the ice cream.", "Compare the money he has with the price."], "title": "True or false: Can Rho buy an ice cream?", "payload": {"statement_md": "Rho can buy an ice cream that costs 8 coins if he has 10 coins.", "justifications": [{"id": "j1", "text_md": "Because 10 coins are more than 8 coins, so he has enough."}, {"id": "j2", "text_md": "Because 10 coins are less than 8 coins, so he doesn''t have enough."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho has 10 coins and wants to buy an ice cream that costs 8 coins. Is this true or false? Help him choose the correct answer and the right justification.", "difficulty": 1, "explanation_md": "The statement is true: Rho has 10 coins and the ice cream costs 8, so he can buy it. The correct justification explains that he has enough money.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/ed4cdf3ba7ac632e4bb67323895ddecf643a2d118218658bb52a3491a108fbcf.mp3", "hash": "53a676e89291ccc2d5e90bd514d7ae8ff01cd426ffd9faeb513c0ce4ea265e92", "bytes": 64224, "voice": "Jennifer", "file_id": "lesson-audio/ed4cdf3ba7ac632e4bb67323895ddecf643a2d118218658bb52a3491a108fbcf.mp3", "duration_ms": 10640}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/6e5e663bb8b20e1fc738bf26a8089d3f5bfd67e77666c1dca7ce7516f5f73fac.mp3", "hash": "55bea38e216cf0f63d30f40b5287613383a65ba74a86e51c55ab4714727da65b", "bytes": 67968, "voice": "Jennifer", "file_id": "lesson-audio/6e5e663bb8b20e1fc738bf26a8089d3f5bfd67e77666c1dca7ce7516f5f73fac.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "piggy-split", "title": "Practice: Piggy Split", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each type of family money is generated and rendered correctly.", "Verify the ''piggy_split'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["Remember that the jars must add up to the total of 80 MXN.", "You can use coins of 1, 2, 5, 10, and 20 MXN to make the amounts."], "title": "Splitting into jars", "payload": {"jars": [{"id": "jar-golosinas", "icon": "candy", "label": "Treats", "hint_md": "Reference price of a treat: 15 MXN."}, {"id": "jar-juguetes", "icon": "toy", "label": "Toys", "hint_md": "Reference price of a small toy: 80 MXN."}], "step": 1, "unit": "MXN", "income": 80}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! In the previous exercise you checked ''make_change''. Now let''s practice ''piggy_split''. Zara earned **80 MXN** for helping at the store. She wants to split that money into her savings jars: one for *treats* and another for *toys*. Can you help her divide the 80 MXN correctly?", "difficulty": 1, "explanation_md": "Zara split 80 MXN into two jars: 15 MXN for treats and 65 MXN for toys. That way she can save for what she wants most!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-juguetes": {"max": 65, "min": 65}, "jar-golosinas": {"max": 15, "min": 15}}, "rationale_md": "Zara quiere ahorrar 15 MXN para golosinas y el resto (65 MXN) para juguetes. 15 + 65 = 80 MXN."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/9916b58bf3a50b5ed1defa7b81031afc560877bdf1636db27dc270201e0b9d0a.mp3", "hash": "b23257db8b9ca6096fcbba23ec673fe42f330e37adc4ffa0806705a424be4ef7", "bytes": 103968, "voice": "Jennifer", "file_id": "lesson-audio/9916b58bf3a50b5ed1defa7b81031afc560877bdf1636db27dc270201e0b9d0a.mp3", "duration_ms": 17280}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a02d7d7d0bab96433e0b7cc94d9f222cdccaaca38e23280520f2d25b205519b.mp3", "hash": "9ded8ba15b6a2613b7ca270b11265afe3aa59ea8ce36171ad7e3c61ab754a48f", "bytes": 53136, "voice": "Jennifer", "file_id": "lesson-audio/0a02d7d7d0bab96433e0b7cc94d9f222cdccaaca38e23280520f2d25b205519b.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', E'{"meta": {"cast": ["dina", "zara"], "slug": "group-sets", "title": "Grouping items with Zara", "locale": "en-US", "subject": "mixed", "objectives": ["Check the group_sets exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 5, "type": "group_sets", "hints": ["Look carefully at the labels for each zone.", "Think about which group each item belongs to."], "title": "Grouping items with Zara", "payload": {"items": [{"id": "item1", "text_md": "Apple"}, {"id": "item2", "text_md": "Banana"}, {"id": "item3", "text_md": "Orange"}, {"id": "item4", "text_md": "Carrot"}, {"id": "item5", "text_md": "Broccoli"}], "set_a": "Zone A (Fruits)", "set_b": "Zone B (Vegetables)"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Remember last time you grouped toys by color and size? Today Dina and Zara are grouping food! Zara has separated some items into two zones: Zone A (fruits) and Zone B (vegetables). Help Zara decide which zone each item goes in. Drag each item to the correct zone.\\n\\nFor example, the apple is a fruit, so it goes in Zone A. Think: is the banana a fruit or a vegetable? What about the carrot? You can do it!", "difficulty": 1, "explanation_md": "Great job! Zara placed 3 items in Zone A (fruits) and 2 in Zone B (vegetables). The apple, banana, and orange are fruits, so they go in A. The carrot and broccoli are vegetables, so they go in B. Excellent work!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/8c2459aafcedb4aa2f4bf5b0d09e5abae27e1a7b3e9f526768b82c03b65b3912.mp3", "hash": "e3a1cf3c635acae359ade00b9a19d7f6def77eb1bf607b50637a17caec1ae5e0", "bytes": 165456, "voice": "Jennifer", "file_id": "lesson-audio/8c2459aafcedb4aa2f4bf5b0d09e5abae27e1a7b3e9f526768b82c03b65b3912.mp3", "duration_ms": 27520}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/f10d2d6c1f5d0163058bdccbcef895b69814ed6c2bf6c44016a1cd2dec5d0371.mp3", "hash": "1383f957e019968e01357444213899dc1b78c2915a1e5f55abf32036b97a7b6f", "bytes": 95328, "voice": "Jennifer", "file_id": "lesson-audio/f10d2d6c1f5d0163058bdccbcef895b69814ed6c2bf6c44016a1cd2dec5d0371.mp3", "duration_ms": 15840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "odd-one-out", "title": "El elemento fuera de lugar", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''odd_one_out'' de forma aislada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Piensa en qué tienen en común tres de los objetos.", "El intruso es el que no comparte la misma categoría."], "title": "Encuentra el intruso", "payload": {"items": [{"id": "item1", "text_md": "Manzana"}, {"id": "item2", "text_md": "Plátano"}, {"id": "item3", "text_md": "Lápiz"}, {"id": "item4", "text_md": "Naranja"}], "reasons": [{"id": "reason1", "text_md": "Es el único que no es una fruta."}, {"id": "reason2", "text_md": "Es el único que es amarillo."}, {"id": "reason3", "text_md": "Es el único que se puede escribir."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina ha estado practicando con el ejercicio ''odd_one_out''. Recuerda que en la lección anterior aprendiste a agrupar objetos por categorías. Ahora, mira estos cuatro objetos y encuentra el que no pertenece al grupo. ¿Cuál es el intruso?", "difficulty": 1, "explanation_md": "El lápiz es el intruso porque los otros tres son frutas, mientras que el lápiz es un objeto de escritura.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item3", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/81baa676bb410e39778a6a47fb6850cd825ecae2bcc2fc3420220001e8346498.mp3", "hash": "6f8cc100ea61358cac6f93acbc8c16793e2527484fcb8fdfacd4b8bc2030691d", "bytes": 82944, "voice": "Li", "file_id": "lesson-audio/81baa676bb410e39778a6a47fb6850cd825ecae2bcc2fc3420220001e8346498.mp3", "duration_ms": 13760}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/849bed619fe45edacb2056055594d728423fccd7162ae7ce482160a8c52d3e43.mp3", "hash": "163361bb9416b1e0b4dca0c5004df762e7cfb6a6857a556f459f690ac994c048", "bytes": 38304, "voice": "Li", "file_id": "lesson-audio/849bed619fe45edacb2056055594d728423fccd7162ae7ce482160a8c52d3e43.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "odd-one-out", "title": "The odd one out", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''odd_one_out'' exercise in isolation"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Think about what three of the objects have in common.", "The odd one out is the one that does not share the same category."], "title": "Find the odd one out", "payload": {"items": [{"id": "item1", "text_md": "Apple"}, {"id": "item2", "text_md": "Banana"}, {"id": "item3", "text_md": "Pencil"}, {"id": "item4", "text_md": "Orange"}], "reasons": [{"id": "reason1", "text_md": "It is the only one that is not a fruit."}, {"id": "reason2", "text_md": "It is the only one that is yellow."}, {"id": "reason3", "text_md": "It is the only one you can write with."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina has been practicing with the ''odd_one_out'' exercise. Remember that in the previous lesson you learned to group objects by categories. Now, look at these four objects and find the one that does not belong to the group. Which is the odd one out?", "difficulty": 1, "explanation_md": "The pencil is the odd one out because the other three are fruits, while the pencil is a writing object.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item3", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/af0f571eb8bfda6fb356ca5873ab71896131f20d5f8af9505d595f8961352848.mp3", "hash": "f811355be0216906ef89dd86dd665d784521dc2961dab8cda90dfaca8acb0ec9", "bytes": 82368, "voice": "Jennifer", "file_id": "lesson-audio/af0f571eb8bfda6fb356ca5873ab71896131f20d5f8af9505d595f8961352848.mp3", "duration_ms": 13680}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/8a5fc689e054904048acdff4116b0e7e20e456b798d9597443d622a5e35b0c90.mp3", "hash": "ce923d87e15ae84d2ae3a2c817c9756b08be5b67adc4d77be6fb9010853bdbbb", "bytes": 31968, "voice": "Jennifer", "file_id": "lesson-audio/8a5fc689e054904048acdff4116b0e7e20e456b798d9597443d622a5e35b0c90.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "odd-one-out", "title": "O elemento fora do lugar", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''odd_one_out'' de forma isolada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Pense no que três dos objetos têm em comum.", "O intruso é aquele que não compartilha a mesma categoria."], "title": "Encontre o intruso", "payload": {"items": [{"id": "item1", "text_md": "Maçã"}, {"id": "item2", "text_md": "Banana"}, {"id": "item3", "text_md": "Lápis"}, {"id": "item4", "text_md": "Laranja"}], "reasons": [{"id": "reason1", "text_md": "É o único que não é uma fruta."}, {"id": "reason2", "text_md": "É o único que é amarelo."}, {"id": "reason3", "text_md": "É o único com que se pode escrever."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina tem praticado com o exercício ''odd_one_out''. Lembre-se de que na lição anterior você aprendeu a agrupar objetos por categorias. Agora, olhe para estes quatro objetos e encontre aquele que não pertence ao grupo. Qual é o intruso?", "difficulty": 1, "explanation_md": "O lápis é o intruso porque os outros três são frutas, enquanto o lápis é um objeto de escrita.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item3", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/4d74a122d05ede7831018badabc8a7ba14c30314dcdcc0e62d3d607d58ebc96e.mp3", "hash": "4688685dc8b8df81d5f0a6c5787d1b7a3a0633b681f92111b3f8f23f8843ed2b", "bytes": 113184, "voice": "Ryan", "file_id": "lesson-audio/4d74a122d05ede7831018badabc8a7ba14c30314dcdcc0e62d3d607d58ebc96e.mp3", "duration_ms": 18800}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/132cbb3e2505ab2d2c6d43f0a5ced8fc8bcee0d365eaac6300647366a3028ec3.mp3", "hash": "2ab6affb6792fcbfe501c354d970ceddc9e21181b5b83e07a8f3bab6a9fa0f96", "bytes": 35856, "voice": "Ryan", "file_id": "lesson-audio/132cbb3e2505ab2d2c6d43f0a5ced8fc8bcee0d365eaac6300647366a3028ec3.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', E'{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Hechos y Opiniones con Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''fact_opinion'' de forma aislada.", "Distinguir entre hechos y opiniones en frases cotidianas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 5, "type": "fact_opinion", "hints": ["Un hecho se puede verificar con datos o evidencia. Por ejemplo: ''El agua hierve a 100°C''.", "Una opinión expresa un sentimiento o preferencia, como ''La pizza es la mejor comida''."], "title": "Hechos y Opiniones", "payload": {"statements": [{"id": "s1-st1", "text_md": "El sol sale por el este."}, {"id": "s1-st2", "text_md": "La música clásica es la más bonita."}, {"id": "s1-st3", "text_md": "El año tiene 365 días."}, {"id": "s1-st4", "text_md": "El chocolate es delicioso."}, {"id": "s1-st5", "text_md": "El agua está compuesta por hidrógeno y oxígeno."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Recuerdas ayer cuando hablamos sobre la verdad? Hoy Dina está ayudando a su maestro a organizar un debate en el salón. Necesita separar las afirmaciones que son hechos comprobables de las que son opiniones personales. Primero, observa estos ejemplos de la vida real: ''El agua hierve a 100°C'' es un hecho; ''El helado de chocolate es el mejor'' es una opinión. Ahora, ayuda a Dina a identificar cuáles de las siguientes frases son **hechos** (cosas que se pueden comprobar) y cuáles son **opiniones** (creencias personales).\\n\\nLee cada frase y selecciona las que son **hechos**.", "difficulty": 1, "explanation_md": "¡Muy bien! Dina separó 3 hechos de 2 opiniones. Recuerda: los hechos se basan en evidencia, las opiniones en sentimientos.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1-st1", "s1-st3", "s1-st5"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/1bce7504f6a1308a1bcfea2aeac0a5c5eda0c30d520f3059c31d6b1b2aae5805.mp3", "hash": "2faae5560545b2e269195a7d97a32ed14c7395fd17d55abbe178daff92daca92", "bytes": 207648, "voice": "Li", "file_id": "lesson-audio/1bce7504f6a1308a1bcfea2aeac0a5c5eda0c30d520f3059c31d6b1b2aae5805.mp3", "duration_ms": 34560}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/59314d57d2e4bf7ceb0e0035a0fffe4082838f20dea9d961598a783720100dbf.mp3", "hash": "9fcfd3109ca47056443e31c277901eb6cabbc6cd2224bec88f9a734117a24603", "bytes": 47808, "voice": "Li", "file_id": "lesson-audio/59314d57d2e4bf7ceb0e0035a0fffe4082838f20dea9d961598a783720100dbf.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "savings-goal", "title": "Meta de ahorro: el juguete de Zara", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cuántas semanas se necesita ahorrar para alcanzar una meta de ahorro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 5, "type": "savings_goal", "hints": ["Divide el costo total entre el ahorro semanal."], "title": "El juguete de Zara", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [8]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara quiere comprar un juguete que cuesta **80 MXN**. Ya tiene 0 MXN ahorrados. Planea ahorrar cada semana una cantidad fija. ¿Cuántas semanas le tomará si ahorra **8 MXN** por semana?", "difficulty": 1, "explanation_md": "Zara necesita 10 semanas porque 80 ÷ 8 = 10.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"8": 10}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/39a7f1e620589b1ba5870a5faf87d182673d553147810724d2fd9183b33a59a6.mp3", "hash": "d125f87c3c76b7b8988f64f036d445323bd2126e1b9b38c6c2a0f549dc902b82", "bytes": 111168, "voice": "Li", "file_id": "lesson-audio/39a7f1e620589b1ba5870a5faf87d182673d553147810724d2fd9183b33a59a6.mp3", "duration_ms": 18480}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/afc7eabfdeccdc7c91a8be11622fb24b8a9362e4f0ff67e299c6bd69dae15feb.mp3", "hash": "10dc35c77aa622d3307a122df90a2fc9f2b8a0a6d707455be89b7900433717ea", "bytes": 25344, "voice": "Li", "file_id": "lesson-audio/afc7eabfdeccdc7c91a8be11622fb24b8a9362e4f0ff67e299c6bd69dae15feb.mp3", "duration_ms": 4160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Practice: Choose the correct image", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''picture_choice'' exercise in isolation (includes image generation)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Hint: Look for the coin or bill that is worth 5 pesos."], "title": "Choose the correct image", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correct. This is the 5-peso coin that Zara needs."}, {"id": "opt2", "icon": "apple", "label": "Apple", "image_url": "https://example.com/apple.png", "rationale_md": "The apple is what Zara wants to buy, but it is not the price."}, {"id": "opt3", "icon": "banana", "label": "Banana", "image_url": "https://example.com/banana.png", "rationale_md": "The banana is another fruit, not the price of the apple."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! Last time you helped Dina count coins. Now Zara wants to buy an apple. **Look at the images** and choose the one that shows how much the apple costs.\\n\\n**Which of these images shows 5 pesos?**", "difficulty": 1, "explanation_md": "Great job! The image with the 5-peso coin is correct. The other options show an apple and a banana.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9d844b264165627cfb0b2a7ebf71ad06d437eb87ee81cd4778a29bb41774ef6.mp3", "hash": "7d57ec12be431311522df9251eb7408a4289ff91a869621ed5d2cdb40550ae6d", "bytes": 74304, "voice": "Jennifer", "file_id": "lesson-audio/c9d844b264165627cfb0b2a7ebf71ad06d437eb87ee81cd4778a29bb41774ef6.mp3", "duration_ms": 12320}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/1f46c2b1295f047691f4e2a463487975ee5dd35266c93060b73765f6f84c1b0f.mp3", "hash": "56068e2eaf0ecaca7b8eb04317caccaedef7c1ab32d37e49c4e1cbd9e4b59bfd", "bytes": 51264, "voice": "Jennifer", "file_id": "lesson-audio/1f46c2b1295f047691f4e2a463487975ee5dd35266c93060b73765f6f84c1b0f.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "speed-tap", "title": "Speed Tap: ¡Toca rápido!", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio speed_tap de forma aislada (flujo cronometrado)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["Observa bien los elementos antes de empezar.", "Concéntrate en los que tienen forma de estrella."], "title": "Speed Tap: ¡Toca rápido!", "payload": {"items": [{"id": "item1", "text_md": "⭐ Estrella"}, {"id": "item2", "text_md": "🔵 Círculo"}, {"id": "item3", "text_md": "⭐ Estrella"}, {"id": "item4", "text_md": "🔺 Triángulo"}, {"id": "item5", "text_md": "⭐ Estrella"}, {"id": "item6", "text_md": "🔴 Cuadrado"}], "seconds": 10, "instruction_md": "Toca todos los elementos con forma de estrella lo más rápido que puedas. Recuerda: las estrellas son ingresos importantes."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "En la lección anterior, aprendiste que las estrellas representan ingresos en nuestro juego de finanzas. Hoy, Zara necesita tu ayuda para recolectar estrellas antes de que se acabe el tiempo. ¡Ella está muy emocionada porque cada estrella significa más dinero para su proyecto! Pero tiene que ser rápida, porque solo hay 10 segundos. ¿Estás listo para ayudarla?", "difficulty": 1, "explanation_md": "¡Bien hecho! Has ayudado a Zara a tocar los elementos correctos a tiempo. Cada estrella que tocaste es un ingreso para su proyecto. ¡Sigue así!", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["item1", "item3", "item5"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/c103fe0f10653fed2c1c0628f898e7a8786264e30e5f5f081e0ff81c87527793.mp3", "hash": "2efd488483c8734a155e9d2a453521715e40941f7e4ce936bd6f08e75a712aa3", "bytes": 129888, "voice": "Li", "file_id": "lesson-audio/c103fe0f10653fed2c1c0628f898e7a8786264e30e5f5f081e0ff81c87527793.mp3", "duration_ms": 21600}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/f4b0d19cf05d6354bbcae1020e2cfa1a1116c5846309d935c0bf0dc407ad0df9.mp3", "hash": "ddfde6c595f739557340d2ea2f5266e63dbd34da27929859b3a3262555ed9148", "bytes": 53568, "voice": "Li", "file_id": "lesson-audio/f4b0d19cf05d6354bbcae1020e2cfa1a1116c5846309d935c0bf0dc407ad0df9.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "savings-goal", "title": "Meta de economia: o brinquedo da Zara", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular quantas semanas são necessárias para economizar e atingir uma meta de economia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 5, "type": "savings_goal", "hints": ["Divida o custo total pela economia semanal."], "title": "O brinquedo da Zara", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [8]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara quer comprar um brinquedo que custa **80 MXN**. Ela já tem 0 MXN economizados. Planeja economizar uma quantia fixa a cada semana. Quantas semanas levará se economizar **8 MXN** por semana?", "difficulty": 1, "explanation_md": "Zara precisa de 10 semanas porque 80 ÷ 8 = 10.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"8": 10}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/0eab688798121fd2a349170e1880c78b8cacfba6746a95ee35dcce2a2cb67042.mp3", "hash": "bf91f57f59cb5ecec269cc6858c7ddc412b26ab5509f2ab4b20417cd9aa9d135", "bytes": 95328, "voice": "Ryan", "file_id": "lesson-audio/0eab688798121fd2a349170e1880c78b8cacfba6746a95ee35dcce2a2cb67042.mp3", "duration_ms": 15840}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/07b2ee08ad14de35c712d8030011af23b5795f4a63c9ea2ca2bd9797b80bf1c5.mp3", "hash": "0ad46cf7c77c1a50bc74235bdaab54b4bbab81fa0c609932191455ecd742c16c", "bytes": 36288, "voice": "Ryan", "file_id": "lesson-audio/07b2ee08ad14de35c712d8030011af23b5795f4a63c9ea2ca2bd9797b80bf1c5.mp3", "duration_ms": 6000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "A peek at interest", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''interest_peek'' exercise in isolation (prediction flow)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["The first month, he earns 10% of 80, which is 8 MXN. So after one month he has 88 MXN.", "The second month, he again earns 10% of the initial 80 MXN, which is another 8 MXN."], "title": "Predict Liruf''s savings", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf saved **80 MXN** in his piggy bank. Each month, his money grows by **10%** (simple interest). How much will he have after **2 months**?", "difficulty": 1, "explanation_md": "Correct! Liruf will have **96 MXN** after 2 months. Each month he earns 8 MXN (10% of 80), so in total he earns 16 MXN. His money grows!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/0d8a1da94af5fee26b5386d74c0a0788e65965a90cd08c99d5ed09c10572e3be.mp3", "hash": "dfd504a2dc2e64dbd99a7b6f31a979ec56d4727e70e00b4eea09ab17ed12d6a7", "bytes": 55584, "voice": "Jennifer", "file_id": "lesson-audio/0d8a1da94af5fee26b5386d74c0a0788e65965a90cd08c99d5ed09c10572e3be.mp3", "duration_ms": 9200}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/f6b6cafe7e8040fe1ad4e0ba400f65dafc722f413a323ce1f08ee7fe4a819d70.mp3", "hash": "276b34bab7ee0fa1d0d60031f3f840f63374cf91ca57d3153af61b94d0d4621b", "bytes": 92448, "voice": "Jennifer", "file_id": "lesson-audio/f6b6cafe7e8040fe1ad4e0ba400f65dafc722f413a323ce1f08ee7fe4a819d70.mp3", "duration_ms": 15360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "speed-tap", "title": "Speed Tap: Toque rápido!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício speed_tap de forma isolada (fluxo cronometrado)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["Observe bem os elementos antes de começar.", "Concentre-se nos que têm formato de estrela."], "title": "Speed Tap: Toque rápido!", "payload": {"items": [{"id": "item1", "text_md": "⭐ Estrela"}, {"id": "item2", "text_md": "🔵 Círculo"}, {"id": "item3", "text_md": "⭐ Estrela"}, {"id": "item4", "text_md": "🔺 Triângulo"}, {"id": "item5", "text_md": "⭐ Estrela"}, {"id": "item6", "text_md": "🔴 Quadrado"}], "seconds": 10, "instruction_md": "Toque todos os elementos com formato de estrela o mais rápido que puder. Lembre-se: as estrelas são receitas importantes."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Na lição anterior, você aprendeu que as estrelas representam receitas no nosso jogo de finanças. Hoje, a Zara precisa da sua ajuda para coletar estrelas antes que o tempo acabe. Ela está muito animada porque cada estrela significa mais dinheiro para o projeto dela! Mas ela tem que ser rápida, porque só tem 10 segundos. Você está pronto para ajudá-la?", "difficulty": 1, "explanation_md": "Muito bem! Você ajudou a Zara a tocar os elementos certos a tempo. Cada estrela que você tocou é uma receita para o projeto dela. Continue assim!", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["item1", "item3", "item5"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/aa6604bcb8989a12900ba895820e94daf2aea885cf8b3dafa53119d360ce6797.mp3", "hash": "ee7f89ae275bf496afdea32d3eaef16b927cce4133c2c4cfd0c3ec75e60e8717", "bytes": 130464, "voice": "Ryan", "file_id": "lesson-audio/aa6604bcb8989a12900ba895820e94daf2aea885cf8b3dafa53119d360ce6797.mp3", "duration_ms": 21680}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/379e338682031c1df2ea72dabf2acbea4cb00fe17dace5831b10684e4e9ccb01.mp3", "hash": "237ae946822479d6ec697efd471e25dba45c991308f40553d875e23cd036add5", "bytes": 56016, "voice": "Ryan", "file_id": "lesson-audio/379e338682031c1df2ea72dabf2acbea4cb00fe17dace5831b10684e4e9ccb01.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "type-answer", "title": "Contar monedas con Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar que Liruf tiene 42 pesos contando monedas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 0, "type": "type_answer", "hints": ["Cuenta las monedas de Liruf: tiene 40 pesos y luego 2 más.", "El número está entre 40 y 44."], "title": "Ayuda a Liruf a contar su dinero", "payload": {"max_chars": 10, "placeholder": "Escribe el número aquí"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Recuerdas cuando ayer contamos monedas con Dina? Hoy ayudamos a Liruf a verificar su dinero. Liruf necesita 42 pesos para comprar semillas. Escribe el número 42 en el recuadro para mostrar cuánto tiene.", "difficulty": 1, "explanation_md": "¡Correcto! Liruf tiene 42 pesos, justo lo que necesita para las semillas. Así verificamos que su dinero está completo.", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["42"], "keywords": ["42"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d4872b277bea8f3f3d3fa77dbbe0c92c4d9987507ce2317c5c81d8a9eab446f.mp3", "hash": "8f06930ff87bbbd7cc46d53ece09b21ce29bca5b9b8067b64a71bf8d92f67357", "bytes": 81936, "voice": "Li", "file_id": "lesson-audio/6d4872b277bea8f3f3d3fa77dbbe0c92c4d9987507ce2317c5c81d8a9eab446f.mp3", "duration_ms": 13600}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/e889467596c06e3855e1cf269064569a3aac682edadcf2e7fc2085193806b085.mp3", "hash": "39a2f37d6029406327483116bff640f8df8139bddf69008a2f413e29f55ff91a", "bytes": 49824, "voice": "Li", "file_id": "lesson-audio/e889467596c06e3855e1cf269064569a3aac682edadcf2e7fc2085193806b085.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "type-answer", "title": "Counting Coins with Liruf", "locale": "en-US", "subject": "mixed", "objectives": ["Check that Liruf has 42 pesos by counting coins."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 0, "type": "type_answer", "hints": ["Count Liruf''s coins: he has 40 pesos and then 2 more.", "The number is between 40 and 44."], "title": "Help Liruf count his money", "payload": {"max_chars": 10, "placeholder": "Write the number here"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember when we counted coins with Dina yesterday? Today we help Liruf check his money. Liruf needs 42 pesos to buy seeds. Write the number 42 in the box to show how much he has.", "difficulty": 1, "explanation_md": "Correct! Liruf has 42 pesos, just what he needs for the seeds. So we check that his money is complete.", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["42"], "keywords": ["42"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/c8e4596d716b63ef8bc9fc10bbe610aaddb0a750557fb9e6f9530ab5fb60ce94.mp3", "hash": "85db11e71401620a1f15429a3c051759c7ba18d51e1858ad5061b4dcd5face1d", "bytes": 70416, "voice": "Jennifer", "file_id": "lesson-audio/c8e4596d716b63ef8bc9fc10bbe610aaddb0a750557fb9e6f9530ab5fb60ce94.mp3", "duration_ms": 11680}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/a322466a0fa9086f1475bc7ee278cc4fa99190eed5232ce0d7563c103990bc07.mp3", "hash": "9ba5485dbd34aa5e5076d640601eab7b1addb31bc3db21e1b2688e907f0273cd", "bytes": 42048, "voice": "Jennifer", "file_id": "lesson-audio/a322466a0fa9086f1475bc7ee278cc4fa99190eed5232ce0d7563c103990bc07.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "type-answer", "title": "Contar moedas com Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar que Liruf tem 42 pesos contando moedas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 0, "type": "type_answer", "hints": ["Conte as moedas de Liruf: ele tem 40 pesos e depois mais 2.", "O número está entre 40 e 44."], "title": "Ajude Liruf a contar seu dinheiro", "payload": {"max_chars": 10, "placeholder": "Escreva o número aqui"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra quando ontem contamos moedas com Dina? Hoje ajudamos Liruf a verificar seu dinheiro. Liruf precisa de 42 pesos para comprar sementes. Escreva o número 42 no quadrado para mostrar quanto ele tem.", "difficulty": 1, "explanation_md": "Correto! Liruf tem 42 pesos, exatamente o que precisa para as sementes. Assim verificamos que seu dinheiro está completo.", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["42"], "keywords": ["42"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/92f81b6e8873157595f2f5c4362fdd8320bd8bd1903b1cc1601b4f9b73249cfa.mp3", "hash": "e15c7b75bb60c713fee371c7290032d656fddd9ce7d984365f69812ddc3b14d0", "bytes": 72288, "voice": "Ryan", "file_id": "lesson-audio/92f81b6e8873157595f2f5c4362fdd8320bd8bd1903b1cc1601b4f9b73249cfa.mp3", "duration_ms": 12000}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/55ac053da579b1dbea98f253f4ff6b937007942f060cef3690f2e1c4e8a39644.mp3", "hash": "1ace19e2820619cf87dcedfffb7955e5608a8e72df29521e9718f9778cdc0fbc", "bytes": 48816, "voice": "Ryan", "file_id": "lesson-audio/55ac053da579b1dbea98f253f4ff6b937007942f060cef3690f2e1c4e8a39644.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "Um olhar sobre os juros", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''interest_peek'' de forma isolada (fluxo de previsão)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["No primeiro mês, ele ganha 10% de 80, que são 8 MXN. Então, depois de um mês, ele tem 88 MXN.", "No segundo mês, ele ganha novamente 10% dos 80 MXN iniciais, que são outros 8 MXN."], "title": "Preveja a economia de Liruf", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf guardou **80 MXN** no seu cofrinho. A cada mês, seu dinheiro cresce **10%** (juros simples). Quanto ele terá depois de **2 meses**?", "difficulty": 1, "explanation_md": "Correto! Liruf terá **96 MXN** depois de 2 meses. A cada mês ele ganha 8 MXN (10% de 80), então no total ganha 16 MXN. O dinheiro dele está crescendo!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/158bb1448305b69cc0f2f46ce7d952f84098b1b24003422bf4435f8b68fb75e0.mp3", "hash": "e7d25c44ef2cbed73fcdcebd0a0ee9c5033a89b5474908ffe05ca3406522baae", "bytes": 63648, "voice": "Ryan", "file_id": "lesson-audio/158bb1448305b69cc0f2f46ce7d952f84098b1b24003422bf4435f8b68fb75e0.mp3", "duration_ms": 10560}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/cbb5dc2696b2ed70f91bf0780513e262944cde89593346796b5267fe2783e868.mp3", "hash": "811db03887d0940eaf146ea5e658363ec8617ce75a8f581829aa63609d1c987e", "bytes": 86256, "voice": "Ryan", "file_id": "lesson-audio/cbb5dc2696b2ed70f91bf0780513e262944cde89593346796b5267fe2783e868.mp3", "duration_ms": 14320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "estimate-slider", "title": "Check estimation slider", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that the estimation slider type is generated and rendered correctly.", "Test the estimation slider exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Drag the slider to the right until it''s near the number 50.", "You can release the slider when you see the number is close to 50."], "title": "Adjust the bar", "payload": {"max": 100, "min": 0, "step": 1, "unit": "monedas", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember when Dina counted her coins last time? Now she''s going to estimate how many she has in her piggy bank without counting them one by one. Think: if you gathered 10 coins in your hand, how many would 5 piles like that be? Dina saved all week and wants to know if she has around 50 coins. Move the bar to indicate your estimate. The correct answer is 50 coins. Adjust the slider as close to 50 as possible.", "difficulty": 1, "explanation_md": "Well done! The bar lets you choose a value by moving the slider. In this case, the correct answer was 50. If your estimate was within the success range, congratulations!", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 50, "full_credit_delta": 5, "zero_credit_delta": 20}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/2238d9cfdce6af5fd71863262973caaebf0ec3f4983a7b1c1b17e625e2757063.mp3", "hash": "e67717b193f5e6d65d2da602b8a5583fd9e20de1d4df09e3bc6c2bbebfbc563c", "bytes": 137088, "voice": "Jennifer", "file_id": "lesson-audio/2238d9cfdce6af5fd71863262973caaebf0ec3f4983a7b1c1b17e625e2757063.mp3", "duration_ms": 22800}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/027135b52205fb4a5250ce89bb9750cb54ffcce5759206e9f69eeff766c250a1.mp3", "hash": "691ec020940073a40db65218e373b2d7bbf9b5d4abd2bf28c618544efb3efafc", "bytes": 71424, "voice": "Jennifer", "file_id": "lesson-audio/027135b52205fb4a5250ce89bb9750cb54ffcce5759206e9f69eeff766c250a1.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "estimate-slider", "title": "Verificar controle deslizante de estimativa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que o controle deslizante de estimativa é gerado e renderizado corretamente.", "Verificar o exercício de controle deslizante de estimativa de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Arraste o controle deslizante para a direita até perto do número 50.", "Você pode soltar o controle quando ver que o número se aproxima de 50."], "title": "Ajuste a barra", "payload": {"max": 100, "min": 0, "step": 1, "unit": "monedas", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra quando a Dina contou as moedas dela da última vez? Agora ela vai estimar quantas tem no cofrinho sem contar uma por uma. Pense: se você juntou 10 moedas na mão, quantas seriam 5 montinhos assim? A Dina economizou a semana toda e quer saber se tem perto de 50 moedas. Mova a barra para indicar sua estimativa. A resposta correta é 50 moedas. Ajuste o controle deslizante o mais próximo possível de 50.", "difficulty": 1, "explanation_md": "Muito bem! A barra permite escolher um valor movendo o controle. Neste caso, a resposta correta era 50. Se sua estimativa ficou dentro da faixa de acerto, parabéns!", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 50, "full_credit_delta": 5, "zero_credit_delta": 20}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/f67efc16c89eb4f81adaaabf14376f343303bbc508900a67c50b2a6bd43cfda5.mp3", "hash": "8a9b436eaf8a1c43631c390703d1c5f753592d5c3e05574295e79d36a86401b5", "bytes": 201024, "voice": "Ryan", "file_id": "lesson-audio/f67efc16c89eb4f81adaaabf14376f343303bbc508900a67c50b2a6bd43cfda5.mp3", "duration_ms": 33440}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/d7af7b1ef7b6537d471219aa5a344f66f28c6af13bd35c888fa2b7978aaed3e8.mp3", "hash": "e9da7217e0d4b262cbda2ccec2044bb9f8e1c1e0b76b4ceddbbd5c824b4f1ee0", "bytes": 62208, "voice": "Ryan", "file_id": "lesson-audio/d7af7b1ef7b6537d471219aa5a344f66f28c6af13bd35c888fa2b7978aaed3e8.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "memory-flip", "title": "Memory Flip: Encontrando Parejas", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''memory_flip'' de forma aislada (flujo de memoria)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Recuerda que en la lección anterior viste cómo agrupar objetos iguales. ¿Puedes agrupar estos conceptos con sus ejemplos como agrupaste manzanas y peras?"], "title": "Memory Flip: Encontrando Parejas", "payload": {"pairs": [{"a_md": "Orden", "b_md": "Tener las cosas en su lugar, como las manzanas en una canasta y las peras en otra."}, {"a_md": "Pareja", "b_md": "Dos cosas que van juntas, como un calcetín izquierdo y uno derecho."}, {"a_md": "Grupo", "b_md": "Varias cosas que son iguales, como tres pelotas rojas."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina ayuda a sus amigos a organizar sus juguetes. Ella tiene 4 cartas: dos con manzanas y dos con peras. ¿Puedes voltear las cartas para emparejar cada concepto con su ejemplo? Por ejemplo, la carta ''Orden'' ya está emparejada con ''Tener las cosas en su lugar, como las manzanas en una canasta y las peras en otra.''", "difficulty": 1, "explanation_md": "En este ejercicio, practicas cómo emparejar conceptos con sus definiciones, igual que en el juego de memoria. Por ejemplo, ''Orden'' significa tener las cosas en su lugar, como cuando Dina pone sus manzanas en una canasta y las peras en otra.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/572f2ef0ebcb7f70bf514907cea6f4722e1941215509439bc74796540874b433.mp3", "hash": "e21cf5e59da36b588719e7e517421f7c4afd607af72a0850676751bcb88a1bec", "bytes": 122688, "voice": "Li", "file_id": "lesson-audio/572f2ef0ebcb7f70bf514907cea6f4722e1941215509439bc74796540874b433.mp3", "duration_ms": 20400}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/ea06761300ace392aa34e4237b535b36c71456310d6899727aab33a77d161ca3.mp3", "hash": "5eefa4673fe0f407bfe52a4ef5e08f51dfa6baf22541e96c8e93713e3ec09393", "bytes": 80064, "voice": "Li", "file_id": "lesson-audio/ea06761300ace392aa34e4237b535b36c71456310d6899727aab33a77d161ca3.mp3", "duration_ms": 13280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "O caminho do robô", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''robot_path'' de forma isolada (fluxo de simulação)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 0, "type": "robot_path", "hints": ["Lembre-se de que o robô só pode avançar para frente se não houver parede."], "title": "Programe o robô", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward"], "max_commands": 5}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Como aprendemos ontem com a Zara e os passos do robô, hoje a Zara está ajudando seu robô amigo a encontrar um tesouro em uma grade 3x3. O robô começa na primeira célula no canto inferior esquerdo, olhando para cima. O tesouro está na última célula no canto superior direito. Não há paredes. Qual instrução ele deve executar primeiro?", "difficulty": 1, "explanation_md": "Muito bem! A Zara escolheu ''forward'' para começar. O robô avança uma célula para cima.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/4d93af96f523a87f839cd00ee1eff7042e83b02de9d25d1c70b511228e9e8439.mp3", "hash": "c8e5e46ba7ce2c2da2dd5c3b8d60393fe11b5c873ebc6859a16eeabc6214b20a", "bytes": 138528, "voice": "Ryan", "file_id": "lesson-audio/4d93af96f523a87f839cd00ee1eff7042e83b02de9d25d1c70b511228e9e8439.mp3", "duration_ms": 23040}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/f5cc7e2b961e792248b8eb8ff0378e54f47253ed95f90ff60747a96e78e91463.mp3", "hash": "d5a215aaed46d78b8e4751203f404d6611d4c0ae60ccf5a359359ff337813546", "bytes": 46944, "voice": "Ryan", "file_id": "lesson-audio/f5cc7e2b961e792248b8eb8ff0378e54f47253ed95f90ff60747a96e78e91463.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "combo-narrativa-choice", "title": "Dina''s Sequence", "locale": "en-US", "subject": "mixed", "objectives": ["Verify that a narrative followed by a multiple-choice question flows in sequence."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-historia", "xp": 0, "type": "story_scene", "hints": [], "title": "Dina''s Story", "payload": {"art": {"icon": "coin", "tint": "primary"}, "action": "idle", "body_md": "Dina found a 10 MXN coin in her pocket. She decided to save it in her piggy bank to buy a book. The next day, her friend Liruf gave her another 5 MXN coin. Now Dina has 15 MXN in her piggy bank.", "emotion": "neutral", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina will tell you a short story. Then, you will answer a question about it.", "difficulty": 1, "explanation_md": "Dina used a 10 MXN coin to start her savings.", "audio_segment_id": "s1-historia.prompt"}, {"id": "s2-pregunta", "xp": 10, "type": "quiz_mcq", "hints": ["Remember that Dina first found 10 MXN and then received 5 MXN."], "title": "How much did Dina save?", "payload": {"options": [{"id": "a", "text_md": "10 MXN", "rationale_md": "That''s only the first coin, but Dina also received another 5 MXN coin."}, {"id": "b", "text_md": "15 MXN", "rationale_md": "Correct! 10 MXN + 5 MXN = 15 MXN."}, {"id": "c", "text_md": "5 MXN", "rationale_md": "That''s only the second coin, but Dina also found a 10 MXN coin."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "How much money did Dina save in total after receiving both coins?", "difficulty": 1, "explanation_md": "Dina saved 15 MXN: 10 MXN + 5 MXN = 15 MXN.", "audio_segment_id": "s2-pregunta.prompt"}], "schema_version": 1}', '{"s2-pregunta": {"correct_option_id": "b"}}', '{"units": {"s1-historia.body": {"url": "http://localhost:4006/files/lesson-audio/b3d93fefcd739e7fb20541ccab073a1b3ce5fd38eb1c49846f0041750320e6dd.mp3", "hash": "b4322882a726c0e1a84f93e9137f8d4dd73c27d3d59fcb978cf7a64c905e7147", "bytes": 86256, "voice": "Jennifer", "file_id": "lesson-audio/b3d93fefcd739e7fb20541ccab073a1b3ce5fd38eb1c49846f0041750320e6dd.mp3", "duration_ms": 14320}, "s1-historia.prompt": {"url": "http://localhost:4006/files/lesson-audio/cfd02a7fc21f648c44c442235ea0376720e62e3e7c9d70e675fa2986e6db33b2.mp3", "hash": "4672cbfff677a83a1de7da8b27c084d92631ff98cb022be68feba4f5704d8d82", "bytes": 20448, "voice": "Jennifer", "file_id": "lesson-audio/cfd02a7fc21f648c44c442235ea0376720e62e3e7c9d70e675fa2986e6db33b2.mp3", "duration_ms": 3360}, "s2-pregunta.prompt": {"url": "http://localhost:4006/files/lesson-audio/2cdeab109866ff615f6a3cada3a87dafac2eb41063b2ceb0236f575910e78720.mp3", "hash": "4594a9808176ea644d5f2f7454470ac16118be83e387a169840c1a4a4a130a6b", "bytes": 21888, "voice": "Jennifer", "file_id": "lesson-audio/2cdeab109866ff615f6a3cada3a87dafac2eb41063b2ceb0236f575910e78720.mp3", "duration_ms": 3600}, "s1-historia.explanation": {"url": "http://localhost:4006/files/lesson-audio/c2d0de5a9667d2b094453f66bddcbee7eed3c485c21a1ae56cedac27fece7e01.mp3", "hash": "54c54ed379a6347a6ff482fac83082786093f2cac31762bad2f279236a3ce258", "bytes": 29088, "voice": "Jennifer", "file_id": "lesson-audio/c2d0de5a9667d2b094453f66bddcbee7eed3c485c21a1ae56cedac27fece7e01.mp3", "duration_ms": 4800}, "s2-pregunta.explanation": {"url": "http://localhost:4006/files/lesson-audio/68e71cab2b89f1146f20c04b0a2a0e8f29a605a1f4816b1278e74fa18eb1f0c4.mp3", "hash": "8cb250590fe8ded0f1f58107e75006f4197064d7d98c8defd3ca6e38b13cf34b", "bytes": 57888, "voice": "Jennifer", "file_id": "lesson-audio/68e71cab2b89f1146f20c04b0a2a0e8f29a605a1f4816b1278e74fa18eb1f0c4.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "memory-flip", "title": "Memory Flip: Encontrando Pares", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''memory_flip'' de forma isolada (fluxo de memória)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Lembre-se de que na lição anterior você viu como agrupar objetos iguais. Você consegue agrupar esses conceitos com seus exemplos como agrupou maçãs e peras?"], "title": "Memory Flip: Encontrando Pares", "payload": {"pairs": [{"a_md": "Ordem", "b_md": "Ter as coisas em seus lugares, como as maçãs em uma cesta e as peras em outra."}, {"a_md": "Par", "b_md": "Duas coisas que andam juntas, como uma meia esquerda e uma direita."}, {"a_md": "Grupo", "b_md": "Várias coisas que são iguais, como três bolas vermelhas."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina ajuda seus amigos a organizar seus brinquedos. Ela tem 4 cartas: duas com maçãs e duas com peras. Você consegue virar as cartas para emparelhar cada conceito com seu exemplo? Por exemplo, a carta ''Ordem'' já está emparelhada com ''Ter as coisas em seus lugares, como as maçãs em uma cesta e as peras em outra.''", "difficulty": 1, "explanation_md": "Neste exercício, você pratica como emparelhar conceitos com suas definições, igual no jogo da memória. Por exemplo, ''Ordem'' significa ter as coisas em seus lugares, como quando Dina coloca suas maçãs em uma cesta e as peras em outra.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/ddbc334af0e6b72f729a74ab1018aa1a30612292e5851dbd0730b56bf92b7208.mp3", "hash": "bce383731790e529b87168a247c878da58ef8f1c293a8cc620787b9da90b5c2f", "bytes": 126576, "voice": "Ryan", "file_id": "lesson-audio/ddbc334af0e6b72f729a74ab1018aa1a30612292e5851dbd0730b56bf92b7208.mp3", "duration_ms": 21040}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf2ef716bed159022a53368bc9e4bdd7cc145a6cca9637362348068a78d78e98.mp3", "hash": "49849ff2669ac434ab6eb401f20bb0fb585dd54c4cdc100f411f6395dc5d4625", "bytes": 100224, "voice": "Ryan", "file_id": "lesson-audio/bf2ef716bed159022a53368bc9e4bdd7cc145a6cca9637362348068a78d78e98.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "order-steps", "title": "Ordenando pasos con Rho", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''order_steps'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Piensa qué debe hacerse primero: ¿cortar el limón o exprimirlo?", "Después de exprimir, ¿qué sigue?"], "title": "Ordena los pasos", "payload": {"items": [{"id": "step1", "text_md": "Cortar el limón por la mitad"}, {"id": "step2", "text_md": "Exprimir el jugo del limón"}, {"id": "step3", "text_md": "Agregar agua y azúcar al jugo"}, {"id": "step4", "text_md": "Revolver bien la mezcla"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! Soy Rho. Recuerda que ayer con Dina aprendiste a seguir instrucciones. Hoy necesito tu ayuda para ordenar los pasos para preparar una limonada. Arrastra los pasos al orden correcto.", "difficulty": 1, "explanation_md": "El orden correcto es: primero cortar el limón por la mitad, luego exprimir el jugo, después agregar agua y azúcar, y finalmente revolver.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/c1033d1092cfc5bfe671b77e5978e3cd7adff95d1000f81264a10ed7deff1d0c.mp3", "hash": "6ce044db87823c621e68158282b481588dd3236e776005050005948e27b66290", "bytes": 72288, "voice": "Li", "file_id": "lesson-audio/c1033d1092cfc5bfe671b77e5978e3cd7adff95d1000f81264a10ed7deff1d0c.mp3", "duration_ms": 12000}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/37d3dff46a2ff62d45b9d9bd6544b933f23e0c8cb15a395f9d80548d917cf3e4.mp3", "hash": "86df0667c6a409405b80f283f73328600f52ab97ab10b3d257a21de643bd22c1", "bytes": 59328, "voice": "Li", "file_id": "lesson-audio/37d3dff46a2ff62d45b9d9bd6544b933f23e0c8cb15a395f9d80548d917cf3e4.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "order-steps", "title": "Ordering steps with Rho", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''order_steps'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Think about what should be done first: cut the lemon or squeeze it?", "After squeezing, what comes next?"], "title": "Order the steps", "payload": {"items": [{"id": "step1", "text_md": "Cut the lemon in half"}, {"id": "step2", "text_md": "Squeeze the lemon juice"}, {"id": "step3", "text_md": "Add water and sugar to the juice"}, {"id": "step4", "text_md": "Stir the mixture well"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! I''m Rho. Remember yesterday with Dina you learned to follow instructions. Today I need your help to order the steps to make lemonade. Drag the steps into the correct order.", "difficulty": 1, "explanation_md": "The correct order is: first cut the lemon in half, then squeeze the juice, then add water and sugar, and finally stir.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/ab096c5f97e0d99c57aeceeab09c43c245885ec16850474be07f9bdeae3fe4d7.mp3", "hash": "6d124d1e3c6e9a2df6de70879154241cc5719adf515dc2c81e0b89e2144d15dc", "bytes": 56016, "voice": "Jennifer", "file_id": "lesson-audio/ab096c5f97e0d99c57aeceeab09c43c245885ec16850474be07f9bdeae3fe4d7.mp3", "duration_ms": 9280}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/71f6278f40f91a756481356c848dc42cfe107b9cd9ddc14a1da2c2f94594fe68.mp3", "hash": "dee845fadb58e79a735b34ebfa75d3c990a7520ea9eb6d40a07e3fcfeb307834", "bytes": 37296, "voice": "Jennifer", "file_id": "lesson-audio/71f6278f40f91a756481356c848dc42cfe107b9cd9ddc14a1da2c2f94594fe68.mp3", "duration_ms": 6160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Sort with Liruf: Organized Baskets", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''sort_buckets'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Look at each basket''s label to know what goes inside.", "If you''re not sure, think about what each object is used for."], "title": "Sort with Liruf", "payload": {"items": [{"id": "i1", "text_md": "Ball"}, {"id": "i2", "text_md": "T-shirt"}, {"id": "i3", "text_md": "Storybook"}, {"id": "i4", "text_md": "Shoes"}, {"id": "i5", "text_md": "Doll"}, {"id": "i6", "text_md": "Encyclopedia"}], "buckets": [{"id": "b1", "label": "Toys"}, {"id": "b2", "label": "Clothes"}, {"id": "b3", "label": "Books"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! Yesterday we learned to group things by color; today, Liruf wants to group them by type.\\n\\nLiruf is cleaning his room before the party and found a bunch of objects. He wants to put each one in the correct basket. Help him sort them.\\n\\n**Instructions:** Drag each object to the basket that matches its type.\\n\\n**Example:** Look, the ball is a toy, so it goes in the toy basket.", "difficulty": 1, "explanation_md": "Great job! Sorting objects helps us keep everything organized. Liruf is very happy with your help.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"i1": "b1", "i2": "b2", "i3": "b3", "i4": "b2", "i5": "b1", "i6": "b3"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/d56c3d2cb891baf30610b7b3e4cefa3d66bd7aa9597209b5cb16cfdaa24ee1c0.mp3", "hash": "35a5133aeeb015210869bd00794222a6cab7d9c9c0c731769a58fca9bf0f56aa", "bytes": 124128, "voice": "Jennifer", "file_id": "lesson-audio/d56c3d2cb891baf30610b7b3e4cefa3d66bd7aa9597209b5cb16cfdaa24ee1c0.mp3", "duration_ms": 20640}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/ad33a8afc036d8edd75d39b8c0d40b4a52ac0c8f94051a356ed2f0c3e82594a2.mp3", "hash": "b20b5358935a44bd8ffd28df8de570b216b6d295c2ee952845d1e7355f7448e0", "bytes": 35424, "voice": "Jennifer", "file_id": "lesson-audio/ad33a8afc036d8edd75d39b8c0d40b4a52ac0c8f94051a356ed2f0c3e82594a2.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classifique com Liruf: Cestas organizadas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''sort_buckets'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Observe a etiqueta de cada cesta para saber o que vai dentro.", "Se não tiver certeza, pense no uso de cada objeto."], "title": "Classifique com Liruf", "payload": {"items": [{"id": "i1", "text_md": "Bola"}, {"id": "i2", "text_md": "Camiseta"}, {"id": "i3", "text_md": "Conto"}, {"id": "i4", "text_md": "Sapatos"}, {"id": "i5", "text_md": "Boneca"}, {"id": "i6", "text_md": "Enciclopédia"}], "buckets": [{"id": "b1", "label": "Brinquedos"}, {"id": "b2", "label": "Roupas"}, {"id": "b3", "label": "Livros"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Ontem aprendemos a agrupar coisas por cor; hoje, Liruf quer agrupá-las por tipo.\\n\\nLiruf está limpando seu quarto antes da festa e encontrou um monte de objetos. Ele quer colocar cada um na cesta correta. Ajude-o a classificá-los.\\n\\n**Instruções:** Arraste cada objeto para a cesta que corresponde ao seu tipo.\\n\\n**Exemplo:** Veja, a bola é um brinquedo, então vai na cesta de brinquedos.", "difficulty": 1, "explanation_md": "Bom trabalho! Classificar objetos nos ajuda a manter tudo em ordem. Liruf está muito feliz com sua ajuda.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"i1": "b1", "i2": "b2", "i3": "b3", "i4": "b2", "i5": "b1", "i6": "b3"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/17645b8d67ce77b84ec69c708cfc45b04dfc10775e097957eb7869baf79fc860.mp3", "hash": "0c6a1a395ab41e897f70fbc43fc81232369706da303c97fc23ff568995c2fc86", "bytes": 152496, "voice": "Ryan", "file_id": "lesson-audio/17645b8d67ce77b84ec69c708cfc45b04dfc10775e097957eb7869baf79fc860.mp3", "duration_ms": 25360}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/367e75e58b301cd71fd580dc367c4cee8275e7818308cdeffbd18e7b256285da.mp3", "hash": "f1afd5f192fabd97ecf2e2f9fdcfd1dd1380e9c4d1d8df47b33183a46ddbd39f", "bytes": 41184, "voice": "Ryan", "file_id": "lesson-audio/367e75e58b301cd71fd580dc367c4cee8275e7818308cdeffbd18e7b256285da.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "rank-choices", "title": "Verificar el ejercicio rank_choices", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia arrange se genera y renderiza correctamente.", "Verificar el ejercicio rank_choices de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 0, "type": "rank_choices", "hints": ["Piensa en el precio de cada artículo: un dulce cuesta 5 pesos, un libro cuesta 50 pesos, y una bicicleta cuesta 500 pesos.", "El orden de menor a mayor precio es: dulce (5 pesos), libro (50 pesos), bicicleta (500 pesos)."], "title": "Ordena las opciones", "payload": {"items": [{"id": "item-dulce", "text_md": "dulce"}, {"id": "item-libro", "text_md": "libro"}, {"id": "item-bicicleta", "text_md": "bicicleta"}], "criterion_md": "del más barato al más caro"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda cómo ordenamos cosas por tamaño la vez pasada? Ahora lo haremos por precio. Zara ahorró 20 pesos y quiere elegir sabiamente. Ayúdala a ordenar los artículos **del más barato al más caro**. Arrastra cada opción al lugar correcto. Los precios son: dulce: $5, libro: $50, bicicleta: $500.", "difficulty": 1, "explanation_md": "El orden correcto es: dulce (5 pesos, más barato), libro (50 pesos, precio medio), bicicleta (500 pesos, más caro). ¡Bien hecho!", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["item-dulce", "item-libro", "item-bicicleta"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/59df9efade3d81cc81ce99854d87bf6d36c2d62a352e0f236b2e58f8738d2329.mp3", "hash": "e535e5890d4cc6c1faa96998d9eaf76a5318ce227235f640f656840c7564c2e2", "bytes": 152496, "voice": "Li", "file_id": "lesson-audio/59df9efade3d81cc81ce99854d87bf6d36c2d62a352e0f236b2e58f8738d2329.mp3", "duration_ms": 25360}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/d32b6fbbf084b05cbecbdc56d9ee5b2857be1cc4d2d71d0c03191b6ab2d61744.mp3", "hash": "c42bafdd1e31b927ecc1489650e8daacc8a2b0c482432c02e044f391e4d4f690", "bytes": 67536, "voice": "Li", "file_id": "lesson-audio/d32b6fbbf084b05cbecbdc56d9ee5b2857be1cc4d2d71d0c03191b6ab2d61744.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "rank-choices", "title": "Check the rank_choices exercise", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each type of the family arrange is generated and rendered correctly.", "Check the rank_choices exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 0, "type": "rank_choices", "hints": ["Think about the price of each item: a candy costs 5 pesos, a book costs 50 pesos, and a bicycle costs 500 pesos.", "The order from lowest to highest price is: candy (5 pesos), book (50 pesos), bicycle (500 pesos)."], "title": "Order the options", "payload": {"items": [{"id": "item-dulce", "text_md": "candy"}, {"id": "item-libro", "text_md": "book"}, {"id": "item-bicicleta", "text_md": "bicycle"}], "criterion_md": "from cheapest to most expensive"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember how we ordered things by size last time? Now we''ll do it by price. Zara saved 20 pesos and wants to choose wisely. Help her order the items **from cheapest to most expensive**. Drag each option to the correct place. The prices are: candy: $5, book: $50, bicycle: $500.", "difficulty": 1, "explanation_md": "The correct order is: candy (5 pesos, cheapest), book (50 pesos, medium price), bicycle (500 pesos, most expensive). Well done!", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["item-dulce", "item-libro", "item-bicicleta"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/7e4fd60583fd2c1a0a66740c6a327fc6b7c843a29c4c7bf70c61f25c2256cfd4.mp3", "hash": "06445ac871e61a7dd53a15108d30f4d5100355cdb641755b5a1fb1956de59ac7", "bytes": 101664, "voice": "Jennifer", "file_id": "lesson-audio/7e4fd60583fd2c1a0a66740c6a327fc6b7c843a29c4c7bf70c61f25c2256cfd4.mp3", "duration_ms": 16880}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/a0c1ca00a5e80369956f3fb92eb2abc1dbf253669984bf94a42673835b649d93.mp3", "hash": "11398e85c3a522ce6ea0195869cddad8b64f994f4dc3943afd1ff2b8efa2bf49", "bytes": 61344, "voice": "Jennifer", "file_id": "lesson-audio/a0c1ca00a5e80369956f3fb92eb2abc1dbf253669984bf94a42673835b649d93.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-line", "title": "Ayuda a Dina a medir ingredientes", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar el número 5 en una recta numérica del 0 al 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["Recuerda que los números aumentan de izquierda a derecha.", "El número 5 está exactamente a la mitad entre 0 y 10."], "title": "Ubica el número en la recta", "payload": {"max": 10, "min": 0, "ticks": 11, "labels": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina está horneando un pastel y necesita 5 cucharadas de azúcar. Ya tiene una taza con marcas del 0 al 10. Primero, imagina que la taza tiene una línea recta con números del 0 al 10, como una regla. ¿Dónde está el 5? Coloca el dedo en el 5 en la recta numérica de abajo.", "difficulty": 1, "explanation_md": "¡Excelente! El número 5 se encuentra justo en el centro de la recta, entre 0 y 10. Así Dina sabe cuánta azúcar necesita.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 5, "full_credit_delta": 0.5, "zero_credit_delta": 2}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/927fe952ec7633003f05b0219fef59f166f7c386281d64a25623af9e55acceb4.mp3", "hash": "01d20544ce5edeccaa9e4c86b9735c825fd94e79e5fe1e074eef0de67b176398", "bytes": 99648, "voice": "Li", "file_id": "lesson-audio/927fe952ec7633003f05b0219fef59f166f7c386281d64a25623af9e55acceb4.mp3", "duration_ms": 16560}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/563761e9e369057c0605fa94bdd00658255857f786faca642405bc6a1192d279.mp3", "hash": "62adf289c584c9df28bd2b99c3cf862558b3f082bec54b0b6f7ba753ae270bc0", "bytes": 46368, "voice": "Li", "file_id": "lesson-audio/563761e9e369057c0605fa94bdd00658255857f786faca642405bc6a1192d279.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-line", "title": "Help Dina measure ingredients", "locale": "en-US", "subject": "mixed", "objectives": ["Locate the number 5 on a number line from 0 to 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["Remember that numbers increase from left to right.", "The number 5 is exactly halfway between 0 and 10."], "title": "Place the number on the line", "payload": {"max": 10, "min": 0, "ticks": 11, "labels": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina is baking a cake and needs 5 tablespoons of sugar. She already has a cup with marks from 0 to 10. First, imagine the cup has a straight line with numbers from 0 to 10, like a ruler. Where is 5? Place your finger on 5 on the number line below.", "difficulty": 1, "explanation_md": "Excellent! The number 5 is right in the center of the line, between 0 and 10. Now Dina knows how much sugar she needs.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 5, "full_credit_delta": 0.5, "zero_credit_delta": 2}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/acedb01986f8dacf7db4763387f5d0851cb2593c5b9505a044891381d5dac01f.mp3", "hash": "6399fd29bff69ef7bada5d964275425daabe9ff488b55c2e0296b85c40f111e9", "bytes": 82368, "voice": "Jennifer", "file_id": "lesson-audio/acedb01986f8dacf7db4763387f5d0851cb2593c5b9505a044891381d5dac01f.mp3", "duration_ms": 13680}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/ddcb8d4f6eaaf5caeda46140156e5fd9e53df3f2867d746e3fa46db562c6d939.mp3", "hash": "14acb92c2ac17c6ffda2ebb8bfdead568b8074362d24177788576b798d281edf", "bytes": 44928, "voice": "Jennifer", "file_id": "lesson-audio/ddcb8d4f6eaaf5caeda46140156e5fd9e53df3f2867d746e3fa46db562c6d939.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-line", "title": "Ajude a Dina a medir ingredientes", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar o número 5 em uma reta numérica de 0 a 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["Lembre-se de que os números aumentam da esquerda para a direita.", "O número 5 está exatamente no meio entre 0 e 10."], "title": "Localize o número na reta", "payload": {"max": 10, "min": 0, "ticks": 11, "labels": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina está assando um bolo e precisa de 5 colheres de açúcar. Ela já tem um copo com marcas de 0 a 10. Primeiro, imagine que o copo tem uma linha reta com números de 0 a 10, como uma régua. Onde está o 5? Coloque o dedo no 5 na reta numérica abaixo.", "difficulty": 1, "explanation_md": "Excelente! O número 5 está bem no centro da reta, entre 0 e 10. Assim Dina sabe quanto açúcar precisa.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 5, "full_credit_delta": 0.5, "zero_credit_delta": 2}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/610a169745fc168858b49a7f1f3a21c39738be298ce9329f09b093012f865ad8.mp3", "hash": "c7a56fd2b2c4da9ff15c7f7542958352b3b037793ae5fe4ac9137c7bc642b67b", "bytes": 123264, "voice": "Ryan", "file_id": "lesson-audio/610a169745fc168858b49a7f1f3a21c39738be298ce9329f09b093012f865ad8.mp3", "duration_ms": 20480}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/0bfb476f6e125021be9eb3fbf77475fb804907de1c970743f7b1f693a1c90da3.mp3", "hash": "2ffb471e2c94b4ca5514a61f470a3feda6db259ae1ccc3d1be172fae8581ceb6", "bytes": 47808, "voice": "Ryan", "file_id": "lesson-audio/0bfb476f6e125021be9eb3fbf77475fb804907de1c970743f7b1f693a1c90da3.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "coin-count", "title": "Verificar coin_count", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família money é gerado e renderizado corretamente.", "Verificar o exercício ''coin_count'' de forma isolada."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["Você pode usar moedas de 5, 2 e 1. Quantas de cada uma somam 10?"], "title": "Conte as moedas", "payload": {"target": 10, "currency": "MXN", "denominations": [1, 2, 5]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra quando ajudamos a Zara a contar as moedas dela? Hoje, o Liruf precisa da sua ajuda para pagar um brinquedo que custa **10 MXN**. Ajude-o a selecionar as moedas exatas. Só existem moedas de 1, 2 e 5 MXN.", "difficulty": 1, "explanation_md": "Para pagar 10 MXN, o Liruf pode usar duas moedas de 5 MXN, ou uma de 5 e cinco de 1, ou cinco de 2, etc. Você escolhe a combinação que preferir!", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/41e46626440af5e8d6b39b90b3632466369d46f51786cb1170cb5c1f941886d8.mp3", "hash": "2d317d9a48de9454aec19ee9833699643f26efdd810f3c38549cf2056a8001fe", "bytes": 90576, "voice": "Ryan", "file_id": "lesson-audio/41e46626440af5e8d6b39b90b3632466369d46f51786cb1170cb5c1f941886d8.mp3", "duration_ms": 15040}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/e48af974617a9d36da9b537badfc97610c77fdb5e8c181181c4c6f1b5039eb34.mp3", "hash": "b9febd4b12d6723391822153495076019c5883b00bd9539915ad8c943785eb9f", "bytes": 79056, "voice": "Ryan", "file_id": "lesson-audio/e48af974617a9d36da9b537badfc97610c77fdb5e8c181181c4c6f1b5039eb34.mp3", "duration_ms": 13120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "make-change", "title": "Check the make_change exercise", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each type in the money family is generated and renders correctly.", "Check the ''make_change'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 0, "type": "make_change", "hints": ["Remember: change is the difference between what you paid and the price."], "title": "The correct change", "payload": {"price": 80, "currency": "MXN", "paid_with": 100, "denominations": [1, 2, 5, 10, 20, 20, 50, 100, 200]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you''ve counted coins in the previous lesson, Rho will help you check the ''make_change'' exercise. Dina is buying a toy at Rho''s store. Imagine you buy a toy that costs **80 MXN** and you pay with a **100 MXN** bill. How much change should you receive?", "difficulty": 1, "explanation_md": "Change is calculated by subtracting the price from the money given: 100 - 80 = 20 MXN. You could receive, for example, a 20 MXN coin.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/e840ed17b2c5f773febebf86e3c91de49845bbf17a7fbfd461ad96a834826187.mp3", "hash": "a9497d9a33c2ecacb760bd9219a3c5dcfd8c0d1e53a5a310a180b8533b0e4c89", "bytes": 100656, "voice": "Jennifer", "file_id": "lesson-audio/e840ed17b2c5f773febebf86e3c91de49845bbf17a7fbfd461ad96a834826187.mp3", "duration_ms": 16720}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/7876ff50b96c1e724ed5be10137595cc0cab08d0e0e5f25e975c2745f8672897.mp3", "hash": "897c6a6e565b03832195d51159e2b59ec193599a84fb4e7e15d8eef4d077c72d", "bytes": 67536, "voice": "Jennifer", "file_id": "lesson-audio/7876ff50b96c1e724ed5be10137595cc0cab08d0e0e5f25e975c2745f8672897.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "make-change", "title": "Verificar o exercício make_change", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família money é gerado e renderizado corretamente.", "Verificar o exercício ''make_change'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 0, "type": "make_change", "hints": ["Lembre-se: o troco é a diferença entre o que você pagou e o preço."], "title": "O troco correto", "payload": {"price": 80, "currency": "MXN", "paid_with": 100, "denominations": [1, 2, 5, 10, 20, 20, 50, 100, 200]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já contou moedas na lição anterior, Rho vai te ajudar a verificar o exercício ''make_change''. Dina está comprando um brinquedo na loja de Rho. Imagine que você compra um brinquedo que custa **80 MXN** e paga com uma nota de **100 MXN**. Quanto troco você deve receber?", "difficulty": 1, "explanation_md": "O troco é calculado subtraindo o preço do dinheiro entregue: 100 - 80 = 20 MXN. Você pode receber, por exemplo, uma moeda de 20 MXN.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/f268775bd57d0e815c767783b31412e55181acdf6fdaba4d67e5ac5752c9924c.mp3", "hash": "dc7b791f0bc5047a039376e3c134bc536d7bf739c8f84f823a590f6ec28e0abb", "bytes": 116928, "voice": "Ryan", "file_id": "lesson-audio/f268775bd57d0e815c767783b31412e55181acdf6fdaba4d67e5ac5752c9924c.mp3", "duration_ms": 19440}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/2fdace59cfa8ecb4ee7a98f599534204371ea29f1328284d9fd644987ccd5d74.mp3", "hash": "345a06fe507baf823e1281b91025813a3cf868a2ae37f013a05bbb4022c0ee41", "bytes": 64656, "voice": "Ryan", "file_id": "lesson-audio/2fdace59cfa8ecb4ee7a98f599534204371ea29f1328284d9fd644987ccd5d74.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "coin-count", "title": "Verificar coin_count", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia money se genera y renderiza correctamente.", "Verificar el ejercicio ''coin_count'' de forma aislada."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["Puedes usar monedas de 5, 2 y 1. ¿Cuántas de cada una suman 10?"], "title": "Cuenta las monedas", "payload": {"target": 10, "currency": "MXN", "denominations": [1, 2, 5]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Recuerdas cuando ayudamos a Zara a contar sus monedas? Hoy, Liruf necesita tu ayuda para pagar un juguete que cuesta **10 MXN**. Ayúdale a seleccionar las monedas exactas. Solo hay monedas de 1, 2 y 5 MXN.", "difficulty": 1, "explanation_md": "Para pagar 10 MXN, Liruf puede usar dos monedas de 5 MXN, o una de 5 y cinco de 1, o cinco de 2, etc. ¡Tú eliges la combinación que prefieras!", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/7df555c33da937dc6e8998e4f734fb944a16c2c94af153e02f0deced026b4966.mp3", "hash": "93716a854fb934c01558fb82542e15df08ddb570f4e74a139f76db1186ef7e0e", "bytes": 80496, "voice": "Li", "file_id": "lesson-audio/7df555c33da937dc6e8998e4f734fb944a16c2c94af153e02f0deced026b4966.mp3", "duration_ms": 13360}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/d4833ea0ec6b569638f926af9bffc74fe7df6a6f4fd92a12a113a2f9a828f6b3.mp3", "hash": "7c2b1c6c787fb72be55ebfeb1d29d71c2aed9fbeb0c1d9d5e369071870814ee3", "bytes": 83808, "voice": "Li", "file_id": "lesson-audio/d4833ea0ec6b569638f926af9bffc74fe7df6a6f4fd92a12a113a2f9a828f6b3.mp3", "duration_ms": 13920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "coin-count", "title": "Check coin_count", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each type in the money family is generated and rendered correctly.", "Check the ''coin_count'' exercise in isolation."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["You can use coins of 5, 2, and 1. How many of each add up to 10?"], "title": "Count the coins", "payload": {"target": 10, "currency": "MXN", "denominations": [1, 2, 5]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember when we helped Zara count her coins? Today, Liruf needs your help to pay for a toy that costs **10 MXN**. Help him select the exact coins. There are only 1, 2, and 5 MXN coins.", "difficulty": 1, "explanation_md": "To pay 10 MXN, Liruf can use two 5 MXN coins, or one 5 and five 1s, or five 2s, etc. You choose the combination you like!", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/eb6601ba0b49cad1d9d5fe4723053e879e3858f35d26a92c9ebb89fa788c1ac6.mp3", "hash": "e32bf24735937116f2570918d9055c2d99571299ac65ec7b32c0a9592863f897", "bytes": 85824, "voice": "Jennifer", "file_id": "lesson-audio/eb6601ba0b49cad1d9d5fe4723053e879e3858f35d26a92c9ebb89fa788c1ac6.mp3", "duration_ms": 14240}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/69955afca1b570178edfb445e9d07c05d26047b13a867202216cdb628dd750ee.mp3", "hash": "b1a73ec004153d33796ccc0499f054a7585d50b68c28a725890d2b6acf0ba8dd", "bytes": 65664, "voice": "Jennifer", "file_id": "lesson-audio/69955afca1b570178edfb445e9d07c05d26047b13a867202216cdb628dd750ee.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "price-compare", "title": "Comparing prices with Liruf", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''price_compare'' exercise in isolation.", "Identify the best deal between two options."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 0, "type": "price_compare", "hints": ["Look at the price per unit. First, calculate how much each toy costs in deal A: 1 toy costs 80 MXN. Then, in deal B: 2 toys cost 150 MXN, so divide 150 by 2 to get the price per toy. Compare the two prices per toy."], "title": "Compare deals", "payload": {"offers": [{"id": "offer-a", "qty": 1, "unit": "juguete", "label": "Deal A: 1 toy", "price": 80}, {"id": "offer-b", "qty": 2, "unit": "juguetes", "label": "Deal B: 2 toys", "price": 150}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As we learned yesterday with Dina about prices, today Liruf needs help buying a toy for his friend Rho. Liruf found two deals. Which one is the best?", "difficulty": 1, "explanation_md": "Deal A gives 1 toy for 80 MXN, so the price per toy is 80 MXN. Deal B gives 2 toys for 150 MXN, so the price per toy is 150 ÷ 2 = 75 MXN. Since 75 is less than 80, deal B is the best.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "offer-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/2c88f81dcf59c1af68f0d1ba82889a6498a3b3be5640ffb48366239bb68f0501.mp3", "hash": "11dd7c59794e1903a6fc5c0526075f9a58b36819366f38a53cc94701bb975e39", "bytes": 56448, "voice": "Jennifer", "file_id": "lesson-audio/2c88f81dcf59c1af68f0d1ba82889a6498a3b3be5640ffb48366239bb68f0501.mp3", "duration_ms": 9360}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/5af25371587a240472d94ee4ccc1a85147e0a8af058909d6c87c4e5f7d8915a8.mp3", "hash": "87ce376fc31a464193a20028ab1d536991b1e5a51f0059abb77d322787766304", "bytes": 141984, "voice": "Jennifer", "file_id": "lesson-audio/5af25371587a240472d94ee4ccc1a85147e0a8af058909d6c87c4e5f7d8915a8.mp3", "duration_ms": 23600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "price-compare", "title": "Comparando preços com Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''price_compare'' de forma isolada.", "Identificar a melhor oferta entre duas opções."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 0, "type": "price_compare", "hints": ["Observe o preço por unidade. Primeiro, calcule quanto custa cada brinquedo na oferta A: 1 brinquedo custa 80 MXN. Depois, na oferta B: 2 brinquedos custam 150 MXN, então divida 150 por 2 para obter o preço por brinquedo. Compare os dois preços por brinquedo."], "title": "Comparar ofertas", "payload": {"offers": [{"id": "offer-a", "qty": 1, "unit": "juguete", "label": "Oferta A: 1 brinquedo", "price": 80}, {"id": "offer-b", "qty": 2, "unit": "juguetes", "label": "Oferta B: 2 brinquedos", "price": 150}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendemos ontem com Dina sobre preços, hoje Liruf precisa de ajuda para comprar um brinquedo para seu amigo Rho. Liruf encontrou duas ofertas. Qual é a melhor?", "difficulty": 1, "explanation_md": "A oferta A dá 1 brinquedo por 80 MXN, então o preço por brinquedo é 80 MXN. A oferta B dá 2 brinquedos por 150 MXN, então o preço por brinquedo é 150 ÷ 2 = 75 MXN. Como 75 é menor que 80, a oferta B é a melhor.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "offer-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/e49b871c81a65792b9d96426454bede8e99e59e6ddcad129f8cfb7460906d360.mp3", "hash": "4568e94c06992527816637418d85197a30ab1541e842c61c5debbc23f09d0038", "bytes": 66528, "voice": "Ryan", "file_id": "lesson-audio/e49b871c81a65792b9d96426454bede8e99e59e6ddcad129f8cfb7460906d360.mp3", "duration_ms": 11040}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/a32659ae899e84f5a0e5124117e168452749390adc68cd9d0759f6b89e326973.mp3", "hash": "82467836b84f5a0b033b23d2c55f76d7fb1191ac9903d90712e27df1daf995bf", "bytes": 140544, "voice": "Ryan", "file_id": "lesson-audio/a32659ae899e84f5a0e5124117e168452749390adc68cd9d0759f6b89e326973.mp3", "duration_ms": 23360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necesidades y Gustos con Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar artículos en necesidades o gustos.", "Entender la diferencia entre lo necesario y lo que solo nos gusta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Piensa si el artículo es necesario para vivir o solo es un gusto."], "title": "Separa necesidades de gustos", "payload": {"items": [{"id": "item1", "icon": "water", "text_md": "Agua"}, {"id": "item2", "icon": "toy", "text_md": "Juguete de 80 MXN"}, {"id": "item3", "icon": "food", "text_md": "Comida"}, {"id": "item4", "icon": "candy", "text_md": "Golosina de 15 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! La vez pasada aprendimos que el dinero se gana y se ahorra. Hoy veremos en qué gastarlo. Dina lo usará para decidir entre necesidades y gustos. Dina está ahorrando y quiere saber en qué debe gastar primero. Ayúdale a clasificar cada artículo: ¿es una necesidad o un gusto?", "difficulty": 1, "explanation_md": "Las necesidades son cosas que debemos tener para vivir, como comida y agua. Los gustos son cosas que nos hacen felices pero no son necesarias.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item1", "item3"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/a4d560852d2d62540fb9e120f1aac8e390ac64365544518e58b2435330ec95a0.mp3", "hash": "1301ad2db76a3e937e556df4e1745c7c33baf3a526c38b9e026a93e9b1bdc4b6", "bytes": 103968, "voice": "Li", "file_id": "lesson-audio/a4d560852d2d62540fb9e120f1aac8e390ac64365544518e58b2435330ec95a0.mp3", "duration_ms": 17280}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/97e00b1d8b310c76a8de5f24ef53e9eafdc5f0893e541a313a1eb3a99b210c85.mp3", "hash": "504005124a489d2f8ddfae12e9b5b3ee5233cf52e98b3a2aab47805476284a8c", "bytes": 55584, "voice": "Li", "file_id": "lesson-audio/97e00b1d8b310c76a8de5f24ef53e9eafdc5f0893e541a313a1eb3a99b210c85.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necessidades e Desejos com Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classificar itens em necessidades ou desejos.", "Entender a diferença entre o necessário e o que apenas gostamos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Pense se o item é necessário para viver ou é apenas um desejo."], "title": "Separe necessidades de desejos", "payload": {"items": [{"id": "item1", "icon": "water", "text_md": "Água"}, {"id": "item2", "icon": "toy", "text_md": "Brinquedo de 80 MXN"}, {"id": "item3", "icon": "food", "text_md": "Comida"}, {"id": "item4", "icon": "candy", "text_md": "Guloseima de 15 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Da última vez aprendemos que o dinheiro se ganha e se poupa. Hoje veremos no que gastá-lo. Dina vai usá-lo para decidir entre necessidades e desejos. Dina está poupando e quer saber no que deve gastar primeiro. Ajude-a a classificar cada item: é uma necessidade ou um desejo?", "difficulty": 1, "explanation_md": "Necessidades são coisas que devemos ter para viver, como comida e água. Desejos são coisas que nos fazem felizes, mas não são necessárias.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item1", "item3"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0ed1820b32a66ae1f6c8965d9bdc776ddc615f0e4ccbe9e5e39e97c937bbf96.mp3", "hash": "e88584c3f046aa4071a1396e2b871c9eebf4c8e39010fcdf45673b6ae3330a22", "bytes": 105408, "voice": "Ryan", "file_id": "lesson-audio/b0ed1820b32a66ae1f6c8965d9bdc776ddc615f0e4ccbe9e5e39e97c937bbf96.mp3", "duration_ms": 17520}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/dbb2b214023a14c490e3ff05d115026ebb2d22eafa075cc0fe524bdc1dcb3937.mp3", "hash": "eb333de96ec002803915dda00aa8826ce7d00d67cc4a92432aac1e4def94010e", "bytes": 62784, "voice": "Ryan", "file_id": "lesson-audio/dbb2b214023a14c490e3ff05d115026ebb2d22eafa075cc0fe524bdc1dcb3937.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "spot-error", "title": "Encuentra el error en el procedimiento", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''spot_error'' de forma aislada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Revisa cada paso con cuidado. ¿Hay algún paso que no tenga sentido?", "Piensa en el orden lógico. ¿Qué paso debería ir antes o después?"], "title": "Encuentra el paso equivocado", "payload": {"steps": [{"id": "step1", "text_md": "Paso 1: Anota los precios de los artículos: una manzana de $5 y un pan de $10."}, {"id": "step2", "text_md": "Paso 2: Multiplica las cantidades para obtener el total."}, {"id": "step3", "text_md": "Paso 3: Revisa que no falte ningún artículo."}], "context_md": "Como aprendimos ayer al sumar compras, Rho está revisando un procedimiento para calcular el total de una compra en una tiendita. Estos son los pasos que alguien escribió:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho encontró un procedimiento con un error. Ayúdale a identificar el paso que está mal.", "difficulty": 1, "explanation_md": "El paso 2 dice ''Multiplica las cantidades'' pero primero debemos sumar. El orden correcto es: sumar primero, luego multiplicar.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El paso 2 debería decir: ''Suma los precios para obtener el total''."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/8c79281898f87d630e0ca22c0476ee652282bc60b43e1a845fe225576af03579.mp3", "hash": "4b0cd8413f1f9dbbba9d6adac801cdf5d1fa9566aa45fc1af7a15e581861d710", "bytes": 29664, "voice": "Li", "file_id": "lesson-audio/8c79281898f87d630e0ca22c0476ee652282bc60b43e1a845fe225576af03579.mp3", "duration_ms": 4880}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/e8aebaf658825980352302e234259e8671a58f0aed790324b76798bec79d1d43.mp3", "hash": "ad005bffb3837ab3c581b05a6709b5955a8d6bb96bb16025ab0d0bdbd04da94a", "bytes": 59904, "voice": "Li", "file_id": "lesson-audio/e8aebaf658825980352302e234259e8671a58f0aed790324b76798bec79d1d43.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "spot-error", "title": "Find the error in the procedure", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''spot_error'' exercise in isolation"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Review each step carefully. Is there any step that doesn''t make sense?", "Think about the logical order. Which step should come before or after?"], "title": "Find the wrong step", "payload": {"steps": [{"id": "step1", "text_md": "Step 1: Write down the prices of the items: an apple for $5 and a bread for $10."}, {"id": "step2", "text_md": "Step 2: Multiply the quantities to get the total."}, {"id": "step3", "text_md": "Step 3: Check that no item is missing."}], "context_md": "As we learned yesterday when adding purchases, Rho is reviewing a procedure to calculate the total of a purchase at a small store. These are the steps someone wrote:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho found a procedure with an error. Help him identify the step that is wrong.", "difficulty": 1, "explanation_md": "Step 2 says ''Multiply the quantities'' but we need to add first. The correct order is: add first, then multiply.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El paso 2 debería decir: ''Suma los precios para obtener el total''."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e92b3c8226f222665f45de5848ac471f511909365259f7ed647df78ab501154.mp3", "hash": "5ca2169ab656e5ebde49b30e7b01a0d6e1a74c6d189b9729bd7107dada4866a4", "bytes": 26784, "voice": "Jennifer", "file_id": "lesson-audio/5e92b3c8226f222665f45de5848ac471f511909365259f7ed647df78ab501154.mp3", "duration_ms": 4400}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/068b879ae0e42340cbac5f760238ea6864634391780fb664ab7abe30ebcf84e8.mp3", "hash": "0e6d6f05ac7eed246fbbf2844f90c0ede947e00bae62a23d37325f537a68e779", "bytes": 64656, "voice": "Jennifer", "file_id": "lesson-audio/068b879ae0e42340cbac5f760238ea6864634391780fb664ab7abe30ebcf84e8.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "read-chart", "title": "Verificar el ejercicio read_chart", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que el tipo read_chart se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 0, "type": "read_chart", "hints": [], "title": "Liruf lee una gráfica", "payload": {"chart": {"kind": "bar", "unit": "limonadas", "series": [{"label": "Ventas", "points": [{"x": "Lunes", "y": 5}, {"x": "Martes", "y": 3}, {"x": "Miércoles", "y": 7}, {"x": "Jueves", "y": 4}, {"x": "Viernes", "y": 6}]}]}, "questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "5"}, {"id": "q1-b", "text_md": "7"}, {"id": "q1-c", "text_md": "3"}], "prompt_md": "¿Cuántas limonadas se vendieron el miércoles?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Lunes"}, {"id": "q2-b", "text_md": "Miércoles"}, {"id": "q2-c", "text_md": "Viernes"}], "prompt_md": "¿Qué día se vendieron más limonadas?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf está revisando una gráfica de barras que muestra las ventas de limonada en una semana. Ayúdale a responder las preguntas.", "difficulty": 1, "explanation_md": "La gráfica muestra las ventas de lunes a viernes. Para responder, busca la barra más alta o compara alturas.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "q1-b", "q2": "q2-b"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/af86acbf54ef80a23d3dad6581214336a844d16433f7667169670568c16b93eb.mp3", "hash": "598a7aab496903c527929bf6449d78c9b33b8559eebc8dca39dfc7c64b6c41cc", "bytes": 44064, "voice": "Li", "file_id": "lesson-audio/af86acbf54ef80a23d3dad6581214336a844d16433f7667169670568c16b93eb.mp3", "duration_ms": 7280}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/0793cd16d0cf77eac02dabcb60995d194e9855019ba9845128e64c464d4c9313.mp3", "hash": "390cab81d41884deb0c50380ce0f855904dc67e842d2cfa5ff9280701325e986", "bytes": 39168, "voice": "Li", "file_id": "lesson-audio/0793cd16d0cf77eac02dabcb60995d194e9855019ba9845128e64c464d4c9313.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "read-chart", "title": "Verify the read_chart exercise", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that the read_chart type is generated and renders correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 0, "type": "read_chart", "hints": [], "title": "Liruf reads a chart", "payload": {"chart": {"kind": "bar", "unit": "limonadas", "series": [{"label": "Sales", "points": [{"x": "Monday", "y": 5}, {"x": "Tuesday", "y": 3}, {"x": "Wednesday", "y": 7}, {"x": "Thursday", "y": 4}, {"x": "Friday", "y": 6}]}]}, "questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "5"}, {"id": "q1-b", "text_md": "7"}, {"id": "q1-c", "text_md": "3"}], "prompt_md": "How many lemonades were sold on Wednesday?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Monday"}, {"id": "q2-b", "text_md": "Wednesday"}, {"id": "q2-c", "text_md": "Friday"}], "prompt_md": "Which day had the most lemonade sales?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf is reviewing a bar chart showing lemonade sales for a week. Help them answer the questions.", "difficulty": 1, "explanation_md": "The chart shows sales from Monday to Friday. To answer, look for the tallest bar or compare heights.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "q1-b", "q2": "q2-b"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/e17d62a6d9867c8a7c7e1e88beff1ffd3377ac021a2a5020fb3b0093bb5d475a.mp3", "hash": "bc1c0d96a5b1d881ba272ca209919f88d56705b3f12cc29b35076d442f36ed19", "bytes": 42624, "voice": "Jennifer", "file_id": "lesson-audio/e17d62a6d9867c8a7c7e1e88beff1ffd3377ac021a2a5020fb3b0093bb5d475a.mp3", "duration_ms": 7040}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/868482c7fb55f14f012d06c93025771049c0d2323b6cf9c0a2fe17010b2b083e.mp3", "hash": "633d4150fd311a9c9b8ae32c01efdd9cebf7866a40934d81250a77fd8f7179d9", "bytes": 32544, "voice": "Jennifer", "file_id": "lesson-audio/868482c7fb55f14f012d06c93025771049c0d2323b6cf9c0a2fe17010b2b083e.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "read-chart", "title": "Verificar o exercício read_chart", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que o tipo read_chart é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 0, "type": "read_chart", "hints": [], "title": "Liruf lê um gráfico", "payload": {"chart": {"kind": "bar", "unit": "limonadas", "series": [{"label": "Vendas", "points": [{"x": "Segunda", "y": 5}, {"x": "Terça", "y": 3}, {"x": "Quarta", "y": 7}, {"x": "Quinta", "y": 4}, {"x": "Sexta", "y": 6}]}]}, "questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "5"}, {"id": "q1-b", "text_md": "7"}, {"id": "q1-c", "text_md": "3"}], "prompt_md": "Quantas limonadas foram vendidas na quarta?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Segunda"}, {"id": "q2-b", "text_md": "Quarta"}, {"id": "q2-c", "text_md": "Sexta"}], "prompt_md": "Qual dia vendeu mais limonadas?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf está revisando um gráfico de barras que mostra as vendas de limonada em uma semana. Ajude-o a responder as perguntas.", "difficulty": 1, "explanation_md": "O gráfico mostra as vendas de segunda a sexta. Para responder, procure a barra mais alta ou compare alturas.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "q1-b", "q2": "q2-b"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/5f662285a18a04fef1ebeb82b95d9a1a27c16bd7fa6ffd6eb3ca5c30ef3d20cb.mp3", "hash": "c618b4480c29a8970360b4b5e51a8809aa802fba695b1ba41cfd64e9be9ad1d6", "bytes": 45504, "voice": "Ryan", "file_id": "lesson-audio/5f662285a18a04fef1ebeb82b95d9a1a27c16bd7fa6ffd6eb3ca5c30ef3d20cb.mp3", "duration_ms": 7520}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/d616c38e89a781a3656b618fb3b966784d7ffb67404fd47896dd908157bffc30.mp3", "hash": "1059686139ec50f07495cd165dedccb671808b644664333a7651276742074e59", "bytes": 44496, "voice": "Ryan", "file_id": "lesson-audio/d616c38e89a781a3656b618fb3b966784d7ffb67404fd47896dd908157bffc30.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "Cacería de evidencia", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''evidence_hunt'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Busca palabras clave como ''porque'', ''ya que'', ''debido a'' que indican una razón."], "title": "Cacería de evidencia", "payload": {"claim_md": "**Afirmación:** El agua es esencial para la vida en la Tierra.", "sentences": [{"id": "s1a", "text_md": "El agua cubre aproximadamente el 71% de la superficie del planeta."}, {"id": "s1b", "text_md": "Todos los seres vivos necesitan agua para vivir y crecer."}, {"id": "s1c", "text_md": "El agua es un recurso renovable gracias al ciclo hidrológico."}, {"id": "s1d", "text_md": "Sin agua, las plantas no podrían realizar la fotosíntesis."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendimos ayer sobre los recursos naturales, hoy Dina y Rho investigan por qué el agua es tan importante. Rho está escéptico, pero Dina está curiosa. Ayúdalos a encontrar las pistas (oraciones) que apoyan la afirmación. Lee el texto y selecciona las oraciones que contienen evidencia. Primero, mira este ejemplo: si la afirmación es ''El sol da luz'', una evidencia sería ''Las plantas crecen gracias al sol''. ¡Ahora inténtalo!", "difficulty": 1, "explanation_md": "Las oraciones que contienen evidencia son las que dan razones o datos que apoyan la afirmación principal.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1b", "s1d"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/510476a89782f98f9d7796d00f05253f988d4ebed13fdc03e53bde83e0fe1c6c.mp3", "hash": "2a767b20dbbc19206479b1f8ba7c98072c1568e806f945df450bb367d730b39d", "bytes": 184608, "voice": "Li", "file_id": "lesson-audio/510476a89782f98f9d7796d00f05253f988d4ebed13fdc03e53bde83e0fe1c6c.mp3", "duration_ms": 30720}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c896d262d9008fb7e575bb9f738ddab0ac8d364e096efed16bb221f45011933.mp3", "hash": "172fee7bd798a116b98719285a095406ef32a76d831fd30ee297721376695bf3", "bytes": 36864, "voice": "Li", "file_id": "lesson-audio/2c896d262d9008fb7e575bb9f738ddab0ac8d364e096efed16bb221f45011933.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "Evidence Hunt", "locale": "en-US", "subject": "mixed", "objectives": ["Verify the ''evidence_hunt'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Look for keywords like ''because,'' ''since,'' ''due to'' that indicate a reason."], "title": "Evidence Hunt", "payload": {"claim_md": "**Claim:** Water is essential for life on Earth.", "sentences": [{"id": "s1a", "text_md": "Water covers approximately 71% of the planet''s surface."}, {"id": "s1b", "text_md": "All living things need water to live and grow."}, {"id": "s1c", "text_md": "Water is a renewable resource thanks to the water cycle."}, {"id": "s1d", "text_md": "Without water, plants could not perform photosynthesis."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As we learned yesterday about natural resources, today Dina and Rho investigate why water is so important. Rho is skeptical, but Dina is curious. Help them find the clues (sentences) that support the claim. Read the text and select the sentences that contain evidence. First, look at this example: if the claim is ''The sun gives light,'' evidence would be ''Plants grow thanks to the sun.'' Now try it!", "difficulty": 1, "explanation_md": "Sentences that contain evidence are those that give reasons or facts that support the main claim.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1b", "s1d"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/c4e1d4066fcd1a1b9bb6d30706d888869dd7b3bcf6f9720c2fd7bf9a91ace71a.mp3", "hash": "b3fac2e3dde79eb850a5858f336e717452f3fe588ff9a71e8df8febc4e1c9006", "bytes": 133344, "voice": "Jennifer", "file_id": "lesson-audio/c4e1d4066fcd1a1b9bb6d30706d888869dd7b3bcf6f9720c2fd7bf9a91ace71a.mp3", "duration_ms": 22160}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/a6944445f8a11f0b5b9553aaeb1f33ea4ae95787d34a3cb8f226d851d0e37741.mp3", "hash": "6d038a0db020024185eec8da542e13edf8be83f0c1686125942c1dd1585d136a", "bytes": 32544, "voice": "Jennifer", "file_id": "lesson-audio/a6944445f8a11f0b5b9553aaeb1f33ea4ae95787d34a3cb8f226d851d0e37741.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "Caça à evidência", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''evidence_hunt'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Procure palavras-chave como ''porque'', ''já que'', ''devido a'' que indicam uma razão."], "title": "Caça à evidência", "payload": {"claim_md": "**Afirmação:** A água é essencial para a vida na Terra.", "sentences": [{"id": "s1a", "text_md": "A água cobre aproximadamente 71% da superfície do planeta."}, {"id": "s1b", "text_md": "Todos os seres vivos precisam de água para viver e crescer."}, {"id": "s1c", "text_md": "A água é um recurso renovável graças ao ciclo hidrológico."}, {"id": "s1d", "text_md": "Sem água, as plantas não poderiam realizar a fotossíntese."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendemos ontem sobre os recursos naturais, hoje Dina e Rho investigam por que a água é tão importante. Rho está cético, mas Dina está curiosa. Ajude-os a encontrar as pistas (frases) que apoiam a afirmação. Leia o texto e selecione as frases que contêm evidência. Primeiro, veja este exemplo: se a afirmação é ''O sol dá luz'', uma evidência seria ''As plantas crescem graças ao sol''. Agora tente!", "difficulty": 1, "explanation_md": "As frases que contêm evidência são as que dão razões ou dados que apoiam a afirmação principal.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1b", "s1d"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/37e01d486d0ae5a88674f7c296db632842cc450cf1e2b75b21774fa1cfe69482.mp3", "hash": "33d4aff1957b8019808d88c005a6318b62545da126274085131e73f46cce03bd", "bytes": 179856, "voice": "Ryan", "file_id": "lesson-audio/37e01d486d0ae5a88674f7c296db632842cc450cf1e2b75b21774fa1cfe69482.mp3", "duration_ms": 29920}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/3b2e9d5a93495c0cbe430bb21fa4229d5353493c3547aec8f3b034296710a6cc.mp3", "hash": "05d3b788ca5c4c90c5a0082059bdc2d1b747819e59b72a1b3bf5ebbda8a539ce", "bytes": 44928, "voice": "Ryan", "file_id": "lesson-audio/3b2e9d5a93495c0cbe430bb21fa4229d5353493c3547aec8f3b034296710a6cc.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "code-order", "title": "Verificar el ejercicio code_order", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia maker se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Pista: Piensa en qué paso va primero: ¿construir, medir o programar?"], "title": "Ordena los bloques", "payload": {"blocks": [{"id": "b1", "text_md": "construir"}, {"id": "b2", "text_md": "medir"}, {"id": "b3", "text_md": "programar"}], "language_hint": "es-MX"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayer aprendiste a construir con piezas. Hoy, Rho quiere construir un robot con 5 piezas. Primero, construye el robot con las piezas. Luego, mide su altura con una regla. Finalmente, ponle baterías para programarlo. Ayuda a Rho a ordenar los bloques de código en el orden correcto: primero construir, luego medir, luego programar.", "difficulty": 1, "explanation_md": "El orden correcto es: **construir**, luego **medir**, luego **programar**. Así se asegura que el robot esté listo.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/0885178919df0a5ecb5bbd303b321e894780a12abd1b76346579b280d6681fba.mp3", "hash": "05022d790c6dcb764696817fd46bc36c3aec1fac4fb9324d28f3a9337699828d", "bytes": 131328, "voice": "Li", "file_id": "lesson-audio/0885178919df0a5ecb5bbd303b321e894780a12abd1b76346579b280d6681fba.mp3", "duration_ms": 21840}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/8581a632686b12fc018d9fd3ebb42e9f521dbd0310cb659e05d10d85931d4d24.mp3", "hash": "25ec6915c62f63ca7bb18420267e5562dedca309feed8cab55e8c9805030aa75", "bytes": 48816, "voice": "Li", "file_id": "lesson-audio/8581a632686b12fc018d9fd3ebb42e9f521dbd0310cb659e05d10d85931d4d24.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "code-order", "title": "Verify the code_order exercise", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each type of the maker family is generated and renders correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Hint: Think about which step goes first: build, measure, or program?"], "title": "Order the blocks", "payload": {"blocks": [{"id": "b1", "text_md": "build"}, {"id": "b2", "text_md": "measure"}, {"id": "b3", "text_md": "program"}], "language_hint": "en-US"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Yesterday you learned to build with pieces. Today, Rho wants to build a robot with 5 pieces. First, build the robot with the pieces. Then, measure its height with a ruler. Finally, put batteries in it to program it. Help Rho order the code blocks in the correct order: first build, then measure, then program.", "difficulty": 1, "explanation_md": "The correct order is: **build**, then **measure**, then **program**. That way you make sure the robot is ready.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/068607846a3f77b047f2240334ffcd766f5ee650e8884a37532b0b0b50b5e4cd.mp3", "hash": "72b79666a6f49d7393ce6fd18764bd44eb37ca1d36cff2b7bdd09a2248d5a26e", "bytes": 124128, "voice": "Jennifer", "file_id": "lesson-audio/068607846a3f77b047f2240334ffcd766f5ee650e8884a37532b0b0b50b5e4cd.mp3", "duration_ms": 20640}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/f20db7ba73070f1790c029e11a4cdef42f0bb491a0853d1b711be7749a0ac5c7.mp3", "hash": "18937fdcc2be0767d2ba3e649547afd8db5366b9de6a6882ea76920b52d73201", "bytes": 33984, "voice": "Jennifer", "file_id": "lesson-audio/f20db7ba73070f1790c029e11a4cdef42f0bb491a0853d1b711be7749a0ac5c7.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Equilibrando la balanza", "locale": "es-MX", "subject": "mixed", "objectives": ["Resolver problemas de equilibrio usando una balanza de platillos.", "Practicar sumas pequeñas para igualar cantidades."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Prueba con una pesa de 2 y una de 3.", "También puedes usar cinco pesas de 1."], "title": "Equilibrando la balanza", "payload": {"weights": [{"id": "w1", "label": "Pesa de 1", "value": 1}, {"id": "w2", "label": "Pesa de 2", "value": 2}, {"id": "w3", "label": "Pesa de 3", "value": 3}], "left_fixed": [{"label": "Pesa fija", "value": 5}], "unknown_label": "Pesa desconocida"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina y Liruf están jugando con una balanza de verdad. En el platillo izquierdo hay una pesa de 5. En la mesa hay pesas de 1, 2 y 3. Ayuda a Liruf a poner pesas en el platillo derecho para que la balanza quede equilibrada. ¿Qué pesas eliges?", "difficulty": 1, "explanation_md": "¡Muy bien! Para que la balanza esté equilibrada, los dos platillos deben tener el mismo peso. 5 es igual a 2+3, o también 1+1+1+1+1. ¡Lo lograste!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/d239dff1551a494931f2cf3f7e139ac136434ba4b3e6ee57d89ce8c0058fef9d.mp3", "hash": "0130a704003f39e5b8a9c0d1e0993706cf79c2ff08d95c217afa13e1c0abd0db", "bytes": 77616, "voice": "Li", "file_id": "lesson-audio/d239dff1551a494931f2cf3f7e139ac136434ba4b3e6ee57d89ce8c0058fef9d.mp3", "duration_ms": 12880}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7fa2f274efe415b07635ad68d7d0aa069af7fd4c64ec053f31c96dde61b6c96.mp3", "hash": "81224e89c4118f4591bdb635bedb76a6bab7fef2eb536aef2bb2cb511fb497e0", "bytes": 78624, "voice": "Li", "file_id": "lesson-audio/c7fa2f274efe415b07635ad68d7d0aa069af7fd4c64ec053f31c96dde61b6c96.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Equilibrando a balança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Resolver problemas de equilíbrio usando uma balança de pratos.", "Praticar somas pequenas para igualar quantidades."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Tente com um peso de 2 e um de 3.", "Você também pode usar cinco pesos de 1."], "title": "Equilibrando a balança", "payload": {"weights": [{"id": "w1", "label": "Peso de 1", "value": 1}, {"id": "w2", "label": "Peso de 2", "value": 2}, {"id": "w3", "label": "Peso de 3", "value": 3}], "left_fixed": [{"label": "Peso fixo", "value": 5}], "unknown_label": "Peso desconhecido"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina e Liruf estão brincando com uma balança de verdade. No prato esquerdo há um peso de 5. Na mesa há pesos de 1, 2 e 3. Ajude Liruf a colocar pesos no prato direito para que a balança fique equilibrada. Quais pesos você escolhe?", "difficulty": 1, "explanation_md": "Muito bem! Para que a balança fique equilibrada, os dois pratos devem ter o mesmo peso. 5 é igual a 2+3, ou também 1+1+1+1+1. Você conseguiu!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/b87a746c6bb9393e43c1c93d0d3e397f5baef22473bc46d5524faed2841c638a.mp3", "hash": "0291bb3425f5d3e1199f5026611e4f3f65384e5ae7974afa8c0ad9a0dd2be1d1", "bytes": 103968, "voice": "Ryan", "file_id": "lesson-audio/b87a746c6bb9393e43c1c93d0d3e397f5baef22473bc46d5524faed2841c638a.mp3", "duration_ms": 17280}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/ef947f649f4653f87a0d93ddf59f6e473d03c90ca2cb99a108753215d5ee5726.mp3", "hash": "fec7df44e01759fc68e7559559ec11371802f06d0ec81eb5e99e8873b75dccc2", "bytes": 78624, "voice": "Ryan", "file_id": "lesson-audio/ef947f649f4653f87a0d93ddf59f6e473d03c90ca2cb99a108753215d5ee5726.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "measure-read", "title": "Check the exercise measure_read", "locale": "en-US", "subject": "mixed", "objectives": ["Check the exercise ''measure_read'' in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 0, "type": "measure_read", "hints": ["Count the centimeters from zero to where the arrow points."], "title": "Read the measurement", "payload": {"max": 10, "min": 0, "unit": "cm", "ticks": 10, "instrument": "ruler", "pointer_value": 7}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hello! In the previous scale exercise, you learned to measure weight. Now, Rho is going to read a measurement on an instrument. Look at the ruler and tell me how many centimeters the arrow points to.", "difficulty": 1, "explanation_md": "The arrow points exactly to 7 cm. Well done! Rho is happy that you read correctly.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 7, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/b6324f629b9213e961e113d4562f3b12ce13e63b54334b60bc6796949aed4da8.mp3", "hash": "f17382d3f5d41921501b30c3e893c98ea3c05f7ba82b5f33366314ee691cb107", "bytes": 68976, "voice": "Jennifer", "file_id": "lesson-audio/b6324f629b9213e961e113d4562f3b12ce13e63b54334b60bc6796949aed4da8.mp3", "duration_ms": 11440}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/5e6a7685a4a15f25c1a6e6189815049d03a9909704c00ffaad964dd926fec2d7.mp3", "hash": "c608be88c631f357277cac000395f0c5ab2722deca5c97898c4cf9c12840778b", "bytes": 35424, "voice": "Jennifer", "file_id": "lesson-audio/5e6a7685a4a15f25c1a6e6189815049d03a9909704c00ffaad964dd926fec2d7.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Combinación de diálogo y dos preguntas", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar que el jugador avanza correctamente entre tipos distintos dentro de una misma lección"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf y su amigo", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "¡Hola Rho! ¿Sabías que en México hay monedas de 1, 2, 5, 10 y 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "¿En serio? ¡Qué interesante! Entonces puedo pagar un dulce de 8 pesos con una moneda de 10 y me dan cambio.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "¡Exacto! Y si juntas dos monedas de 5, tienes 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendiste en la lección anterior sobre monedas, hoy seguiremos practicando. Liruf está conversando con su amigo Rho sobre las monedas de México. Escucha con atención.", "difficulty": 1, "explanation_md": "Este diálogo te ayudará a recordar las monedas que hay en México.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Recuerda lo que dijo Rho sobre el dulce de 8 pesos."], "title": "¿Verdadero o falso?", "payload": {"statement_md": "Rho puede pagar un dulce de 8 pesos con una moneda de 10 pesos y recibir cambio de 2 pesos.", "justifications": [{"id": "j1", "text_md": "Sí, porque 10 - 8 = 2, y las monedas de 10 existen."}, {"id": "j2", "text_md": "No, porque no hay monedas de 10 pesos."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Según lo que dijeron Liruf y Rho, elige si la afirmación es verdadera o falsa. Antes de responder, pregúntate: ¿cuánto es 10 menos 8?", "difficulty": 1, "explanation_md": "Rho dijo que con una moneda de 10 puede pagar un dulce de 8 y recibir cambio, así que la afirmación es verdadera.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Busca la imagen que tenga dos monedas iguales que sumen 10."], "title": "Elige la combinación correcta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Dos monedas de 5 pesos", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correcto. Dos monedas de 5 suman 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "Una moneda de 10 pesos", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorrecto. Aunque vale 10, no son dos monedas de 5."}, {"id": "opt3", "icon": "coin", "label": "Cinco monedas de 2 pesos", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorrecto. Cinco monedas de 2 suman 10, pero no son dos monedas de 5."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf dijo que juntando dos monedas de 5 se tienen 10 pesos. ¿Cuál de las siguientes imágenes muestra esa combinación? Piensa: ¿cuántas monedas de 5 necesitas para tener 10?", "difficulty": 1, "explanation_md": "Dos monedas de 5 pesos suman 10 pesos, así que la imagen con dos monedas de 5 es la correcta.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/9af5cd15024e2d097c69be4c8ee059b9097b0963a5e795ef4b548731d795273b.mp3", "hash": "8195adde1ace23b24574c97fd4f0f556cb9863145f22f7e98dcc47490a5cf204", "bytes": 42048, "voice": "Li", "file_id": "lesson-audio/9af5cd15024e2d097c69be4c8ee059b9097b0963a5e795ef4b548731d795273b.mp3", "duration_ms": 6960}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/9f01ee8999de923ba7bdf9dc504f558d90842cf40d733a13fc135ac0086a8ec3.mp3", "hash": "f0c6ddb4f7392b504a5d325326cb93055e778db2d803487dcec9ae9fa9ce7d80", "bytes": 40608, "voice": "Li", "file_id": "lesson-audio/9f01ee8999de923ba7bdf9dc504f558d90842cf40d733a13fc135ac0086a8ec3.mp3", "duration_ms": 6720}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/9785676e4095ec2d0f7f7244ca23e811d529dc77f0e199b5261ab9cafbde4bb9.mp3", "hash": "7ff334b92cc7534f3320702f0b294597dee0ecea5bcbfc1d0e1d7b5868b8ee39", "bytes": 25344, "voice": "Li", "file_id": "lesson-audio/9785676e4095ec2d0f7f7244ca23e811d529dc77f0e199b5261ab9cafbde4bb9.mp3", "duration_ms": 4160}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/53a84bba46dd309c1072abdfa9afc65de4218deef180f4d902551830e3f3286a.mp3", "hash": "53174375cb74fededcfaefb01a3b0e427bddd551f58e3b29c9aa532d083efc90", "bytes": 62208, "voice": "Li", "file_id": "lesson-audio/53a84bba46dd309c1072abdfa9afc65de4218deef180f4d902551830e3f3286a.mp3", "duration_ms": 10320}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/60d7afcfcb8283689929ec08be291e4c7bf28ae5d9c98aedbdb995f3c44620bd.mp3", "hash": "e481552fc6625c9d99a9cd7af5aeba7316a51c7e5e660d3ddbc074eb1b8b346e", "bytes": 57888, "voice": "Li", "file_id": "lesson-audio/60d7afcfcb8283689929ec08be291e4c7bf28ae5d9c98aedbdb995f3c44620bd.mp3", "duration_ms": 9600}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf648d045f0615dd1057362fc58784acd136af779016b33ad46f713c3a656a30.mp3", "hash": "08d95ebbdfea0a637cf0fcf1e348a0a6341db43732ef35055b1016d17dca63e1", "bytes": 16704, "voice": "Li", "file_id": "lesson-audio/bf648d045f0615dd1057362fc58784acd136af779016b33ad46f713c3a656a30.mp3", "duration_ms": 2720}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/3b0c7e2894a02964924fe92ee1a2573b83ea4f7fb4950f9750fef1cc9a8ad5ab.mp3", "hash": "e6ba2259554ab8c2ae230f2796fafea5bf1193f584f02eb9452ca22e02ae7a9f", "bytes": 73296, "voice": "Li", "file_id": "lesson-audio/3b0c7e2894a02964924fe92ee1a2573b83ea4f7fb4950f9750fef1cc9a8ad5ab.mp3", "duration_ms": 12160}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/a7ef63d35b9fedba527bd5d02f741fc146d55f81e57cfeb3b1f7ca8198ab1720.mp3", "hash": "59a96bf3b86e7a9c140472bd92c2a96490f22ee2d2c823e2dfe26651e0a06f2a", "bytes": 42048, "voice": "Li", "file_id": "lesson-audio/a7ef63d35b9fedba527bd5d02f741fc146d55f81e57cfeb3b1f7ca8198ab1720.mp3", "duration_ms": 6960}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/c57ac16bf1d4b084df430b970ea6353fb7b42c868f012f37e52a2dd6e4f2f7cd.mp3", "hash": "7e2ed3bbb58e02e434b63e5b4929295b306f2a38d30345fcc91888597931ada8", "bytes": 39744, "voice": "Li", "file_id": "lesson-audio/c57ac16bf1d4b084df430b970ea6353fb7b42c868f012f37e52a2dd6e4f2f7cd.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Dialogue combination and two questions", "locale": "en-US", "subject": "mixed", "objectives": ["Verify that the player advances correctly between different types within the same lesson"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf and his friend", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Hi Rho! Did you know that in Mexico there are coins of 1, 2, 5, 10, and 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "Really? How interesting! So I can pay for an 8-peso candy with a 10-peso coin and get change.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exactly! And if you put two 5-peso coins together, you have 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As you learned in the previous lesson about coins, today we will keep practicing. Liruf is talking with his friend Rho about Mexican coins. Listen carefully.", "difficulty": 1, "explanation_md": "This dialogue will help you remember the coins used in Mexico.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Remember what Rho said about the 8-peso candy."], "title": "True or false?", "payload": {"statement_md": "Rho can pay for an 8-peso candy with a 10-peso coin and receive 2 pesos in change.", "justifications": [{"id": "j1", "text_md": "Yes, because 10 - 8 = 2, and 10-peso coins exist."}, {"id": "j2", "text_md": "No, because there are no 10-peso coins."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Based on what Liruf and Rho said, choose whether the statement is true or false. Before answering, ask yourself: how much is 10 minus 8?", "difficulty": 1, "explanation_md": "Rho said that with a 10-peso coin he can pay for an 8-peso candy and receive change, so the statement is true.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Look for the image that has two identical coins that add up to 10."], "title": "Choose the correct combination", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Two 5-peso coins", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correct. Two 5-peso coins add up to 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "One 10-peso coin", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorrect. Even though it''s worth 10, it''s not two 5-peso coins."}, {"id": "opt3", "icon": "coin", "label": "Five 2-peso coins", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorrect. Five 2-peso coins add up to 10, but they are not two 5-peso coins."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf said that putting two 5-peso coins together gives you 10 pesos. Which of the following images shows that combination? Think: how many 5-peso coins do you need to have 10?", "difficulty": 1, "explanation_md": "Two 5-peso coins add up to 10 pesos, so the image with two 5-peso coins is correct.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/124178738e337b67ecbf4193892b9d76edb535e45cdf7a902b9b765ad1e6a05f.mp3", "hash": "fc945bfe9a10552d769f5a0a0b93c07323f5a0f4b635f58d19fa7caa30289d3c", "bytes": 32544, "voice": "Jennifer", "file_id": "lesson-audio/124178738e337b67ecbf4193892b9d76edb535e45cdf7a902b9b765ad1e6a05f.mp3", "duration_ms": 5360}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/e3185dae210aaf254f32772667c979db248ef8a12e884cd6d01d7c94059c00a7.mp3", "hash": "a1ac146d0b8029a1407cd0db53c1557d3b93ad7e09f64b54df169d4e1f266956", "bytes": 45504, "voice": "Jennifer", "file_id": "lesson-audio/e3185dae210aaf254f32772667c979db248ef8a12e884cd6d01d7c94059c00a7.mp3", "duration_ms": 7520}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/2ca4c04394bd197923524ec9ffa1d4b0e583e8bb4677fe986ee0f72e58f9d16c.mp3", "hash": "1c8e0dbf90f67ef8e231172d332ff21c034bdc90b59be86a7b520d749487461c", "bytes": 31104, "voice": "Jennifer", "file_id": "lesson-audio/2ca4c04394bd197923524ec9ffa1d4b0e583e8bb4677fe986ee0f72e58f9d16c.mp3", "duration_ms": 5120}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/533c8a76bea343702acf510a47085ef3e9422b3c3be08f41bad4878ade08c8f9.mp3", "hash": "ca0a157574b61b3fdee49cf1f6940f6d99403839da1a1d2b763464cb078313ce", "bytes": 55584, "voice": "Jennifer", "file_id": "lesson-audio/533c8a76bea343702acf510a47085ef3e9422b3c3be08f41bad4878ade08c8f9.mp3", "duration_ms": 9200}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/ec0ce9492b99c69be739450f7ab00ccee75ac1bab9c8f83ec325aaf324952cc3.mp3", "hash": "53360b42eaca0627172164ac4bcd13630ab7b3b1cd44849439b5de6a16657b65", "bytes": 47376, "voice": "Jennifer", "file_id": "lesson-audio/ec0ce9492b99c69be739450f7ab00ccee75ac1bab9c8f83ec325aaf324952cc3.mp3", "duration_ms": 7840}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/161229b00f2a062c1dd48628d27d5dd5359c456d4234aa98f9b4c3fb5a2496dd.mp3", "hash": "c3b5aa55e6bf1ac77d5ea3cf2dcb2ed147bebe296972eebe609006d18289d738", "bytes": 15696, "voice": "Jennifer", "file_id": "lesson-audio/161229b00f2a062c1dd48628d27d5dd5359c456d4234aa98f9b4c3fb5a2496dd.mp3", "duration_ms": 2560}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/bcbc34ca9997ec2b10f96f3c952addc17894af7abc3ace8c96ac1427adf6062e.mp3", "hash": "3162674de8bf90f2686fab9f0259bf83c1d757299888f068f4d9a1eaa8d66255", "bytes": 72864, "voice": "Jennifer", "file_id": "lesson-audio/bcbc34ca9997ec2b10f96f3c952addc17894af7abc3ace8c96ac1427adf6062e.mp3", "duration_ms": 12080}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/757caaa1ddeff552099137607f6e4dd7bc545993eec4d5e3a93b53e3086b1198.mp3", "hash": "fbcdcdcbe139875fac2c6ada066d5272c15e1138607281e9aedf565f4bbb9795", "bytes": 35856, "voice": "Jennifer", "file_id": "lesson-audio/757caaa1ddeff552099137607f6e4dd7bc545993eec4d5e3a93b53e3086b1198.mp3", "duration_ms": 5920}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c3629c932766e029eb44d34e357e0343c7c44149f8bae04b14dc4231d5570a5.mp3", "hash": "06fc0fd613a531b004ee233143ae1e62cee15a29054daf0701610524f7d22226", "bytes": 38736, "voice": "Jennifer", "file_id": "lesson-audio/2c3629c932766e029eb44d34e357e0343c7c44149f8bae04b14dc4231d5570a5.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Combinação de diálogo e duas perguntas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar se o jogador avança corretamente entre tipos diferentes dentro de uma mesma lição"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf e seu amigo", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Olá Rho! Sabia que no México existem moedas de 1, 2, 5, 10 e 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "Sério? Que interessante! Então posso pagar um doce de 8 pesos com uma moeda de 10 e receber troco.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exato! E se você juntar duas moedas de 5, tem 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como você aprendeu na lição anterior sobre moedas, hoje continuaremos praticando. Liruf está conversando com seu amigo Rho sobre as moedas do México. Ouça com atenção.", "difficulty": 1, "explanation_md": "Este diálogo vai te ajudar a lembrar as moedas que existem no México.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Lembre-se do que Rho disse sobre o doce de 8 pesos."], "title": "Verdadeiro ou falso?", "payload": {"statement_md": "Rho pode pagar um doce de 8 pesos com uma moeda de 10 pesos e receber troco de 2 pesos.", "justifications": [{"id": "j1", "text_md": "Sim, porque 10 - 8 = 2, e as moedas de 10 existem."}, {"id": "j2", "text_md": "Não, porque não existem moedas de 10 pesos."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "De acordo com o que Liruf e Rho disseram, escolha se a afirmação é verdadeira ou falsa. Antes de responder, pergunte-se: quanto é 10 menos 8?", "difficulty": 1, "explanation_md": "Rho disse que com uma moeda de 10 pode pagar um doce de 8 e receber troco, então a afirmação é verdadeira.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Procure a imagem que tenha duas moedas iguais que somem 10."], "title": "Escolha a combinação correta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Duas moedas de 5 pesos", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correto. Duas moedas de 5 somam 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "Uma moeda de 10 pesos", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorreto. Embora valha 10, não são duas moedas de 5."}, {"id": "opt3", "icon": "coin", "label": "Cinco moedas de 2 pesos", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorreto. Cinco moedas de 2 somam 10, mas não são duas moedas de 5."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf disse que juntando duas moedas de 5 se tem 10 pesos. Qual das seguintes imagens mostra essa combinação? Pense: quantas moedas de 5 você precisa para ter 10?", "difficulty": 1, "explanation_md": "Duas moedas de 5 pesos somam 10 pesos, então a imagem com duas moedas de 5 é a correta.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/46b9ae54a00dcf81aec3627c8feb436c34f9bb6b7eed89b9db394a4ce9576179.mp3", "hash": "31154015022803e031e7621fd41bb95dcb58c0ff08e4c34bddffe4f201ddf949", "bytes": 36864, "voice": "Ryan", "file_id": "lesson-audio/46b9ae54a00dcf81aec3627c8feb436c34f9bb6b7eed89b9db394a4ce9576179.mp3", "duration_ms": 6080}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/eafc5e4e0439208118b3469945216eefdab8fa2b3664c8ba866b8736d4e6b3d9.mp3", "hash": "d211d96c52e8cf3bf0af4d16e8c7d0d7b5c54a5cab4c523f94a11535accd6adc", "bytes": 42048, "voice": "Ryan", "file_id": "lesson-audio/eafc5e4e0439208118b3469945216eefdab8fa2b3664c8ba866b8736d4e6b3d9.mp3", "duration_ms": 6960}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/22054f1964d39baab1b5f7c0291c4a3acb28366ff140b639c56da921a0e19118.mp3", "hash": "37c07ef6f700896b9d521edacd25a6f3a172397c35ae5322dd81c63d8faa98ee", "bytes": 30096, "voice": "Ryan", "file_id": "lesson-audio/22054f1964d39baab1b5f7c0291c4a3acb28366ff140b639c56da921a0e19118.mp3", "duration_ms": 4960}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/760b0b4b3c714d9adef182c391492c4d6181fe42f8d22e1398b64ef93afa3bf0.mp3", "hash": "0ec4164614a9133121df5f03e41971434ab98f17d7e32ca94e0952b0c405902f", "bytes": 70848, "voice": "Ryan", "file_id": "lesson-audio/760b0b4b3c714d9adef182c391492c4d6181fe42f8d22e1398b64ef93afa3bf0.mp3", "duration_ms": 11760}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/eb4ca3e7e40cec237e4a213169d91c3af064b3eff31a596e42e0c356318bbaab.mp3", "hash": "9052bc16383bc9795828b3e501ea1a224e98b597ab4f004f2b21257ec9596f98", "bytes": 68976, "voice": "Ryan", "file_id": "lesson-audio/eb4ca3e7e40cec237e4a213169d91c3af064b3eff31a596e42e0c356318bbaab.mp3", "duration_ms": 11440}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8320e5e2b8936299f0e8d6cae51dcc7d165d76a4831b376d0c20531fa9f08c8.mp3", "hash": "b2d2f894d3a6c2fd5e37df92e5130fcad461c3b9acc8be98a4b954219fd73be7", "bytes": 25344, "voice": "Ryan", "file_id": "lesson-audio/a8320e5e2b8936299f0e8d6cae51dcc7d165d76a4831b376d0c20531fa9f08c8.mp3", "duration_ms": 4160}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/f7a343864da025c4e30a65d971adc60300d37cfcb67cb6d7741aa70119d02cba.mp3", "hash": "a7d7d5539a1c43eb99fea97546c630f5275f1086a8dc859f7b348a4ee175824a", "bytes": 68544, "voice": "Ryan", "file_id": "lesson-audio/f7a343864da025c4e30a65d971adc60300d37cfcb67cb6d7741aa70119d02cba.mp3", "duration_ms": 11360}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/e9171ac1b3c8cee5740e77e8681eeab608a4a654a434fe0a6e43f357c33483fe.mp3", "hash": "2f80c13768ae1f30e260cd5f5a434a16c6ae2b8074b60f2d13e2336303e263a2", "bytes": 50688, "voice": "Ryan", "file_id": "lesson-audio/e9171ac1b3c8cee5740e77e8681eeab608a4a654a434fe0a6e43f357c33483fe.mp3", "duration_ms": 8400}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8e3ee8e14ec12aaeaa8bdef5ec23e0074345648ca2735f84d87fad62f825e47.mp3", "hash": "9d3ca6d5554227d3dc215bcf495afe28540ea917b3029a87e23acb4939195610", "bytes": 44064, "voice": "Ryan", "file_id": "lesson-audio/a8e3ee8e14ec12aaeaa8bdef5ec23e0074345648ca2735f84d87fad62f825e47.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Combo de arreglos: empareja, ordena, clasifica y ubica", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar una secuencia larga de cuatro tipos de la familia arrange."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 0, "type": "match_pairs", "hints": ["Observa el número en cada moneda."], "title": "Empareja monedas con su valor", "payload": {"left": [{"id": "left-1", "text_md": "Moneda de 1 MXN"}, {"id": "left-2", "text_md": "Moneda de 2 MXN"}, {"id": "left-3", "text_md": "Moneda de 5 MXN"}, {"id": "left-4", "text_md": "Moneda de 10 MXN"}, {"id": "left-5", "text_md": "Moneda de 20 MXN"}], "right": [{"id": "right-1", "text_md": "1 peso"}, {"id": "right-2", "text_md": "2 pesos"}, {"id": "right-3", "text_md": "5 pesos"}, {"id": "right-4", "text_md": "10 pesos"}, {"id": "right-5", "text_md": "20 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara acaba de verificar una secuencia de tres ejercicios de dinero encadenados. Recuerdas cómo en la lección pasada ordenamos monedas? Hoy haremos algo similar pero más largo. Empareja cada moneda con su valor correcto.", "difficulty": 1, "explanation_md": "La moneda de 1 MXN vale un peso, la de 2 MXN vale dos pesos, la de 5 MXN vale cinco pesos, la de 10 MXN vale diez pesos y la de 20 MXN vale veinte pesos.", "audio_segment_id": "s1-match-pairs.prompt"}, {"id": "s2-order-steps", "xp": 0, "type": "order_steps", "hints": ["Primero separa las monedas por valor."], "title": "Ordena los pasos para contar dinero", "payload": {"items": [{"id": "step-1", "text_md": "Agrupa las monedas por denominación"}, {"id": "step-2", "text_md": "Suma el valor de cada grupo"}, {"id": "step-3", "text_md": "Suma todos los grupos"}, {"id": "step-4", "text_md": "Verifica el total"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora ordena los pasos para contar correctamente un montón de monedas.", "difficulty": 1, "explanation_md": "Primero agrupa las monedas por denominación, luego suma cada grupo, después suma todos los grupos y finalmente verifica el total.", "audio_segment_id": "s2-order-steps.prompt"}, {"id": "s3-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Recuerda que 10 pesos es el límite."], "title": "Clasifica monedas en dos categorías", "payload": {"items": [{"id": "item-1", "text_md": "Moneda de 1 MXN"}, {"id": "item-2", "text_md": "Moneda de 2 MXN"}, {"id": "item-3", "text_md": "Moneda de 5 MXN"}, {"id": "item-4", "text_md": "Moneda de 10 MXN"}, {"id": "item-5", "text_md": "Moneda de 20 MXN"}], "buckets": [{"id": "bucket-menor10", "label": "Menos de 10 pesos"}, {"id": "bucket-10omas", "label": "10 pesos o más"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Clasifica cada moneda en el cubo correcto: ''Monedas de menos de 10 pesos'' o ''Monedas de 10 pesos o más''.", "difficulty": 1, "explanation_md": "Las monedas de 1, 2 y 5 pesos valen menos de 10; las de 10 y 20 pesos valen 10 o más.", "audio_segment_id": "s3-sort-buckets.prompt"}, {"id": "s4-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Piensa en qué pasó primero en la historia del dinero."], "title": "Ubica eventos en la línea del tiempo", "payload": {"events": [{"id": "event-1", "icon": "trade", "text_md": "Trueque"}, {"id": "event-2", "icon": "coin", "text_md": "Monedas de metal"}, {"id": "event-3", "icon": "bill", "text_md": "Billetes de papel"}, {"id": "event-4", "icon": "digital", "text_md": "Dinero digital"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordena estos eventos en la línea del tiempo, del más antiguo al más reciente.", "difficulty": 1, "explanation_md": "El trueque fue lo primero, luego las monedas de metal, después los billetes de papel y finalmente el dinero digital.", "audio_segment_id": "s4-timeline-order.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["left-1", "right-1"], ["left-2", "right-2"], ["left-3", "right-3"], ["left-4", "right-4"], ["left-5", "right-5"]]}, "s2-order-steps": {"order": ["step-1", "step-2", "step-3", "step-4"]}, "s3-sort-buckets": {"assignments": {"item-1": "bucket-menor10", "item-2": "bucket-menor10", "item-3": "bucket-menor10", "item-4": "bucket-10omas", "item-5": "bucket-10omas"}}, "s4-timeline-order": {"order": ["event-1", "event-2", "event-3", "event-4"]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/0f9e19e58347d0ad7eb3a147300503580be9b5f8297ea25c155174c8ab848b35.mp3", "hash": "da1ad10745195b9aefc249b4fa64f151660842bee7b29a4e8934a194e02475b5", "bytes": 79056, "voice": "Li", "file_id": "lesson-audio/0f9e19e58347d0ad7eb3a147300503580be9b5f8297ea25c155174c8ab848b35.mp3", "duration_ms": 13120}, "s2-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/7e1b963a57b9bbce72ec3cd8ca0c84764181d6f50a5fe030ceeab51a7bfa4f5e.mp3", "hash": "0812b613586c9a4e91123c029daf2985738e5b7b8431f6043533bd12e5a8b94c", "bytes": 21024, "voice": "Li", "file_id": "lesson-audio/7e1b963a57b9bbce72ec3cd8ca0c84764181d6f50a5fe030ceeab51a7bfa4f5e.mp3", "duration_ms": 3440}, "s3-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/a6c82370d904f4db2fa42432147e5705b2eb27522a0f6e54b34216c6fd85b883.mp3", "hash": "121fc6a630996979b820cade27aa2141905a2768d6a82453d8606105cbf2da95", "bytes": 37296, "voice": "Li", "file_id": "lesson-audio/a6c82370d904f4db2fa42432147e5705b2eb27522a0f6e54b34216c6fd85b883.mp3", "duration_ms": 6160}, "s4-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6240ca3d88fb8ada1553771d2095ee5f33b59b0d3825d81ded1cc80eeccb923.mp3", "hash": "98644d56d91ddf9d3023da8bd657cde623a22d720745a517912f179f21a8f55d", "bytes": 26784, "voice": "Li", "file_id": "lesson-audio/f6240ca3d88fb8ada1553771d2095ee5f33b59b0d3825d81ded1cc80eeccb923.mp3", "duration_ms": 4400}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/d022373d172f01253ad57f41be5f80775504203c3d0051346d85a4d91ca5e2eb.mp3", "hash": "eaf3c5b09b6c84f2df3e361802ac04c2761daec33de23e0fba4683daaa4ce313", "bytes": 107856, "voice": "Li", "file_id": "lesson-audio/d022373d172f01253ad57f41be5f80775504203c3d0051346d85a4d91ca5e2eb.mp3", "duration_ms": 17920}, "s2-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/15feb86692e661626a4935f708aec025fcc6bbac959f3c596eaf42333b800d9f.mp3", "hash": "b2d838cdadd3bed786d4bc0488741e65f5ae08dd309cbbbe7c36534ee9a12324", "bytes": 49824, "voice": "Li", "file_id": "lesson-audio/15feb86692e661626a4935f708aec025fcc6bbac959f3c596eaf42333b800d9f.mp3", "duration_ms": 8240}, "s3-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/e777b7727c5d1ec4fa973d63f9ac6fecf98175a39f4dfc0307031fb75f2a6453.mp3", "hash": "3c48dfecdc34bd4ab1c26714f36e757ce258980a19bbf1fdd56e6c6948d3a5ca", "bytes": 33984, "voice": "Li", "file_id": "lesson-audio/e777b7727c5d1ec4fa973d63f9ac6fecf98175a39f4dfc0307031fb75f2a6453.mp3", "duration_ms": 5600}, "s4-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/ba627c8e3a51566b38f4753149209e45d23165ef15c3b61002e9358ceae1aed7.mp3", "hash": "5e56e606cdf7798d141bceab75ae784cc17d24df01930008469a52ea97a86e3d", "bytes": 46944, "voice": "Li", "file_id": "lesson-audio/ba627c8e3a51566b38f4753149209e45d23165ef15c3b61002e9358ceae1aed7.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Arrange combo: match, sort, classify, and place", "locale": "en-US", "subject": "mixed", "objectives": ["Verify a long sequence of four types of the arrange family."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 0, "type": "match_pairs", "hints": ["Look at the number on each coin."], "title": "Match coins with their value", "payload": {"left": [{"id": "left-1", "text_md": "1 MXN coin"}, {"id": "left-2", "text_md": "2 MXN coin"}, {"id": "left-3", "text_md": "5 MXN coin"}, {"id": "left-4", "text_md": "10 MXN coin"}, {"id": "left-5", "text_md": "20 MXN coin"}], "right": [{"id": "right-1", "text_md": "1 peso"}, {"id": "right-2", "text_md": "2 pesos"}, {"id": "right-3", "text_md": "5 pesos"}, {"id": "right-4", "text_md": "10 pesos"}, {"id": "right-5", "text_md": "20 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara just verified a sequence of three linked money exercises. Remember how we sorted coins in the last lesson? Today we''ll do something similar but longer. Match each coin with its correct value.", "difficulty": 1, "explanation_md": "The 1 MXN coin is worth one peso, the 2 MXN coin is worth two pesos, the 5 MXN coin is worth five pesos, the 10 MXN coin is worth ten pesos, and the 20 MXN coin is worth twenty pesos.", "audio_segment_id": "s1-match-pairs.prompt"}, {"id": "s2-order-steps", "xp": 0, "type": "order_steps", "hints": ["First, separate the coins by value."], "title": "Order the steps to count money", "payload": {"items": [{"id": "step-1", "text_md": "Group the coins by denomination"}, {"id": "step-2", "text_md": "Add the value of each group"}, {"id": "step-3", "text_md": "Add all groups"}, {"id": "step-4", "text_md": "Verify the total"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now order the steps to correctly count a pile of coins.", "difficulty": 1, "explanation_md": "First, group the coins by denomination, then add each group, then add all groups, and finally verify the total.", "audio_segment_id": "s2-order-steps.prompt"}, {"id": "s3-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Remember that 10 pesos is the limit."], "title": "Classify coins into two categories", "payload": {"items": [{"id": "item-1", "text_md": "1 MXN coin"}, {"id": "item-2", "text_md": "2 MXN coin"}, {"id": "item-3", "text_md": "5 MXN coin"}, {"id": "item-4", "text_md": "10 MXN coin"}, {"id": "item-5", "text_md": "20 MXN coin"}], "buckets": [{"id": "bucket-menor10", "label": "Less than 10 pesos"}, {"id": "bucket-10omas", "label": "10 pesos or more"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Classify each coin into the correct bucket: ''Coins worth less than 10 pesos'' or ''Coins worth 10 pesos or more''.", "difficulty": 1, "explanation_md": "Coins of 1, 2, and 5 pesos are worth less than 10; coins of 10 and 20 pesos are worth 10 or more.", "audio_segment_id": "s3-sort-buckets.prompt"}, {"id": "s4-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Think about what happened first in the history of money."], "title": "Place events on the timeline", "payload": {"events": [{"id": "event-1", "icon": "trade", "text_md": "Barter"}, {"id": "event-2", "icon": "coin", "text_md": "Metal coins"}, {"id": "event-3", "icon": "bill", "text_md": "Paper bills"}, {"id": "event-4", "icon": "digital", "text_md": "Digital money"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Order these events on the timeline, from oldest to most recent.", "difficulty": 1, "explanation_md": "Barter was first, then metal coins, then paper bills, and finally digital money.", "audio_segment_id": "s4-timeline-order.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["left-1", "right-1"], ["left-2", "right-2"], ["left-3", "right-3"], ["left-4", "right-4"], ["left-5", "right-5"]]}, "s2-order-steps": {"order": ["step-1", "step-2", "step-3", "step-4"]}, "s3-sort-buckets": {"assignments": {"item-1": "bucket-menor10", "item-2": "bucket-menor10", "item-3": "bucket-menor10", "item-4": "bucket-10omas", "item-5": "bucket-10omas"}}, "s4-timeline-order": {"order": ["event-1", "event-2", "event-3", "event-4"]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ef52bb4b2b6fef77bb2b76a9d8d79e8ffdb0bebcf73c9503198899848599cfe.mp3", "hash": "eea0be56f7fb025efe0372d96d86a0e56ec9efffd758abb2ab2f5fc3740d0a92", "bytes": 73728, "voice": "Jennifer", "file_id": "lesson-audio/2ef52bb4b2b6fef77bb2b76a9d8d79e8ffdb0bebcf73c9503198899848599cfe.mp3", "duration_ms": 12240}, "s2-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/fcb6bfb116eb4f0efc4fbaf73c4dc73a605a3eca3897660542af3df97eeae5f2.mp3", "hash": "3247613831df8b4b5c06d7c1ca298cfc5798075671b82e08164bf6398c96b12e", "bytes": 22896, "voice": "Jennifer", "file_id": "lesson-audio/fcb6bfb116eb4f0efc4fbaf73c4dc73a605a3eca3897660542af3df97eeae5f2.mp3", "duration_ms": 3760}, "s3-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/63b9c730578cc35268e8b14a1fe412b3cec0ce7732c2fa8782a2a4bf46baddd6.mp3", "hash": "9ab2ff670f14881a0b87bac83824957592520f20fc276fb98acf1882d13b4da7", "bytes": 44928, "voice": "Jennifer", "file_id": "lesson-audio/63b9c730578cc35268e8b14a1fe412b3cec0ce7732c2fa8782a2a4bf46baddd6.mp3", "duration_ms": 7440}, "s4-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/3653393696e907b5c0c82d33d7f3834def76371d7ea8422a05b9411239d8174d.mp3", "hash": "a3c3a4b3832ce6d5c1da7062d23f276f5682b155a4b8fdcbedf4c59e173975a3", "bytes": 24336, "voice": "Jennifer", "file_id": "lesson-audio/3653393696e907b5c0c82d33d7f3834def76371d7ea8422a05b9411239d8174d.mp3", "duration_ms": 4000}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/212485a6cbe320c366912fa5018c562e0c5197d32ae77251b6ce64af00cabe69.mp3", "hash": "00b1cfdde416e790ec33bbc24198618f73d1714587346de489dd90d3e9969928", "bytes": 106848, "voice": "Jennifer", "file_id": "lesson-audio/212485a6cbe320c366912fa5018c562e0c5197d32ae77251b6ce64af00cabe69.mp3", "duration_ms": 17760}, "s2-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/ebaf5388ee14d29ded7d0ac2ae79e7985a60e98bb6aff0ff57532b38a34f69ec.mp3", "hash": "614d01b1f3fdd63c6f84417dbea7d4d0cd7618c47a393cf4090b022d494364ad", "bytes": 38304, "voice": "Jennifer", "file_id": "lesson-audio/ebaf5388ee14d29ded7d0ac2ae79e7985a60e98bb6aff0ff57532b38a34f69ec.mp3", "duration_ms": 6320}, "s3-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/402531bab37df63df66778596bd4c4e78a98836c743ababb37dab2be763e5fdd.mp3", "hash": "527803331ed7164dff6424f864e5dc87b3a9e4d078d06031ed1eb2c596259945", "bytes": 47808, "voice": "Jennifer", "file_id": "lesson-audio/402531bab37df63df66778596bd4c4e78a98836c743ababb37dab2be763e5fdd.mp3", "duration_ms": 7920}, "s4-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/f11d01c312c3bf0871c2ac754a7f614134e2966d339471cbbf56f14e94929f5f.mp3", "hash": "9e99f9b249866b3782330234022ca8db6fb2251e4fbc05e47712899d6884286e", "bytes": 28656, "voice": "Jennifer", "file_id": "lesson-audio/f11d01c312c3bf0871c2ac754a7f614134e2966d339471cbbf56f14e94929f5f.mp3", "duration_ms": 4720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Combo de arranjos: combine, ordene, classifique e localize", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar uma sequência longa de quatro tipos da família arrange."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 0, "type": "match_pairs", "hints": ["Observe o número em cada moeda."], "title": "Combine moedas com seu valor", "payload": {"left": [{"id": "left-1", "text_md": "Moeda de 1 MXN"}, {"id": "left-2", "text_md": "Moeda de 2 MXN"}, {"id": "left-3", "text_md": "Moeda de 5 MXN"}, {"id": "left-4", "text_md": "Moeda de 10 MXN"}, {"id": "left-5", "text_md": "Moeda de 20 MXN"}], "right": [{"id": "right-1", "text_md": "1 peso"}, {"id": "right-2", "text_md": "2 pesos"}, {"id": "right-3", "text_md": "5 pesos"}, {"id": "right-4", "text_md": "10 pesos"}, {"id": "right-5", "text_md": "20 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara acabou de verificar uma sequência de três exercícios de dinheiro encadeados. Lembra como na lição passada ordenamos moedas? Hoje faremos algo parecido, mas mais longo. Combine cada moeda com seu valor correto.", "difficulty": 1, "explanation_md": "A moeda de 1 MXN vale um peso, a de 2 MXN vale dois pesos, a de 5 MXN vale cinco pesos, a de 10 MXN vale dez pesos e a de 20 MXN vale vinte pesos.", "audio_segment_id": "s1-match-pairs.prompt"}, {"id": "s2-order-steps", "xp": 0, "type": "order_steps", "hints": ["Primeiro separe as moedas por valor."], "title": "Ordene os passos para contar dinheiro", "payload": {"items": [{"id": "step-1", "text_md": "Agrupe as moedas por denominação"}, {"id": "step-2", "text_md": "Some o valor de cada grupo"}, {"id": "step-3", "text_md": "Some todos os grupos"}, {"id": "step-4", "text_md": "Verifique o total"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora ordene os passos para contar corretamente um monte de moedas.", "difficulty": 1, "explanation_md": "Primeiro agrupe as moedas por denominação, depois some cada grupo, depois some todos os grupos e finalmente verifique o total.", "audio_segment_id": "s2-order-steps.prompt"}, {"id": "s3-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Lembre-se que 10 pesos é o limite."], "title": "Classifique moedas em duas categorias", "payload": {"items": [{"id": "item-1", "text_md": "Moeda de 1 MXN"}, {"id": "item-2", "text_md": "Moeda de 2 MXN"}, {"id": "item-3", "text_md": "Moeda de 5 MXN"}, {"id": "item-4", "text_md": "Moeda de 10 MXN"}, {"id": "item-5", "text_md": "Moeda de 20 MXN"}], "buckets": [{"id": "bucket-menor10", "label": "Menos de 10 pesos"}, {"id": "bucket-10omas", "label": "10 pesos ou mais"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Classifique cada moeda no cubo correto: ''Moedas de menos de 10 pesos'' ou ''Moedas de 10 pesos ou mais''.", "difficulty": 1, "explanation_md": "As moedas de 1, 2 e 5 pesos valem menos de 10; as de 10 e 20 pesos valem 10 ou mais.", "audio_segment_id": "s3-sort-buckets.prompt"}, {"id": "s4-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Pense no que aconteceu primeiro na história do dinheiro."], "title": "Localize eventos na linha do tempo", "payload": {"events": [{"id": "event-1", "icon": "trade", "text_md": "Escambo"}, {"id": "event-2", "icon": "coin", "text_md": "Moedas de metal"}, {"id": "event-3", "icon": "bill", "text_md": "Cédulas de papel"}, {"id": "event-4", "icon": "digital", "text_md": "Dinheiro digital"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordene estes eventos na linha do tempo, do mais antigo ao mais recente.", "difficulty": 1, "explanation_md": "O escambo foi o primeiro, depois as moedas de metal, depois as cédulas de papel e finalmente o dinheiro digital.", "audio_segment_id": "s4-timeline-order.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["left-1", "right-1"], ["left-2", "right-2"], ["left-3", "right-3"], ["left-4", "right-4"], ["left-5", "right-5"]]}, "s2-order-steps": {"order": ["step-1", "step-2", "step-3", "step-4"]}, "s3-sort-buckets": {"assignments": {"item-1": "bucket-menor10", "item-2": "bucket-menor10", "item-3": "bucket-menor10", "item-4": "bucket-10omas", "item-5": "bucket-10omas"}}, "s4-timeline-order": {"order": ["event-1", "event-2", "event-3", "event-4"]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/6b8f634c5d85653d8e753e6857642384ee4fb51365d7b22eae280f31b62a8cfe.mp3", "hash": "a1d4591440fc86036670f8456c6951ccbd33d4db2cc995c91d38ee114fb15b7a", "bytes": 89136, "voice": "Ryan", "file_id": "lesson-audio/6b8f634c5d85653d8e753e6857642384ee4fb51365d7b22eae280f31b62a8cfe.mp3", "duration_ms": 14800}, "s2-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/2c2ecceb3c7ee234fc632459def42b6375219296e5fda4c40e0aae4f52c53b8b.mp3", "hash": "8875d84917ef7d618ede513ecf2ffcbbe17be62792d88901b031a1a300eb4d10", "bytes": 27648, "voice": "Ryan", "file_id": "lesson-audio/2c2ecceb3c7ee234fc632459def42b6375219296e5fda4c40e0aae4f52c53b8b.mp3", "duration_ms": 4560}, "s3-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/757a1ffa0a46a6a965568b98017648128a6597a6d3b6dd2bdeaf6dd5ef575814.mp3", "hash": "813db5417486426fe9f1a137b0681c42807e42f672240a17fa9458deb46f4106", "bytes": 38736, "voice": "Ryan", "file_id": "lesson-audio/757a1ffa0a46a6a965568b98017648128a6597a6d3b6dd2bdeaf6dd5ef575814.mp3", "duration_ms": 6400}, "s4-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d875b420433b2fcd1ae3cda4acc729e24c5ab6ffe2f507357f5274d52e165c8.mp3", "hash": "0f9763451045a1d19dcc9e8d3f8d1ff2751f778e247391930da426ba41a6c83f", "bytes": 28656, "voice": "Ryan", "file_id": "lesson-audio/5d875b420433b2fcd1ae3cda4acc729e24c5ab6ffe2f507357f5274d52e165c8.mp3", "duration_ms": 4720}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/d011b9bce5937b3c64e9a0ee45f2c21b5a21d6cae68b847329032d5eaa9722b5.mp3", "hash": "82a243f0df294ba358842859f19caef3c658e7258556cd8016ce0c93a225177a", "bytes": 105984, "voice": "Ryan", "file_id": "lesson-audio/d011b9bce5937b3c64e9a0ee45f2c21b5a21d6cae68b847329032d5eaa9722b5.mp3", "duration_ms": 17600}, "s2-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/c4350e107f6af008cbbbf3645895f1b1c694814d27f7f175a73368006f421f36.mp3", "hash": "9bfbbaaa9d4bbc5a74a9678e4ab3a830d6e7a35d9edb3aa63ff8d2cb6cedf2fa", "bytes": 51696, "voice": "Ryan", "file_id": "lesson-audio/c4350e107f6af008cbbbf3645895f1b1c694814d27f7f175a73368006f421f36.mp3", "duration_ms": 8560}, "s3-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/0935c43d53906584c61e226a8b0d3d7e36d1071f6b2ee16020d833100f237b1a.mp3", "hash": "7120f2bae43ca7fc2550a742a982aa367b0f3bdbf9f92330d63eca6ffcc5f26a", "bytes": 41184, "voice": "Ryan", "file_id": "lesson-audio/0935c43d53906584c61e226a8b0d3d7e36d1071f6b2ee16020d833100f237b1a.mp3", "duration_ms": 6800}, "s4-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/1da86a4b1b672b4ae6a055e9612dd2b7c6a1a9a98c9baf237b837d18bd9d8763.mp3", "hash": "a47c1793f836adcbf31747838b3a3cb8199c3388c42dad10edcceace12f3ae19", "bytes": 47808, "voice": "Ryan", "file_id": "lesson-audio/1da86a4b1b672b4ae6a055e9612dd2b7c6a1a9a98c9baf237b837d18bd9d8763.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "best-decision", "title": "Liruf''s Best Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Verify the ''best_decision'' exercise in isolation.", "Confirm that each type in the choice family is generated and rendered correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["Think about what is fairest for everyone.", "Imagine you lost the coin, what would you want someone to do?"], "title": "Liruf''s Decision", "payload": {"options": [{"id": "opt-devolver", "text_md": "Return the coin to the lost and found office", "rationale_md": "It is the most honest and fair option."}, {"id": "opt-dulce", "text_md": "Buy a candy to share with Zara", "rationale_md": "It may seem generous, but the coin is not Liruf''s, so it is not right to use it without permission."}, {"id": "opt-guardar", "text_md": "Keep it in his pocket and say nothing", "rationale_md": "It is tempting because no one saw it, but it is not honest to keep something that does not belong to him."}], "scenario_md": "Liruf is at the park playing with his friend Zara. Suddenly, he sees a 10-peso coin on the ground. No one else has seen it. Liruf thinks: ''What should I do?''"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember when we learned about honesty. Liruf found a 10-peso coin in the park. What should he do? Think step by step: who could be the owner? How would you feel if you lost something? Choose the best option.", "difficulty": 1, "explanation_md": "The best decision is to return the coin, because it is honest and fair. Buying a candy or keeping it does not consider the owner. Remember: being honest is always the best choice.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"egoísmo": 0, "honestidad": 10, "generosidad": 5}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/5dadc6852feb940bd46afa76dc3816e8e5015cfc8ad31b7ec3353f0b0deb7757.mp3", "hash": "1539dd90743feef28dce5bd2f5b4ec3d39ffefc04ac2e3a5fa83639ef7829435", "bytes": 77616, "voice": "Jennifer", "file_id": "lesson-audio/5dadc6852feb940bd46afa76dc3816e8e5015cfc8ad31b7ec3353f0b0deb7757.mp3", "duration_ms": 12880}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/107d3a1d0a4528b185eed2d8dc820dc79f9410d57bc861311ebce594d34f3ca1.mp3", "hash": "ae57ff92e683cb91b690313154b9317f1b8710b34c2910ad045e3cbb1b203d0d", "bytes": 66528, "voice": "Jennifer", "file_id": "lesson-audio/107d3a1d0a4528b185eed2d8dc820dc79f9410d57bc861311ebce594d34f3ca1.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "best-decision", "title": "A melhor decisão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''best_decision'' de forma isolada.", "Confirmar que cada tipo da família choice é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["Pense no que é mais justo para todos.", "Imagine que você perdeu a moeda, o que gostaria que fizessem?"], "title": "A decisão de Liruf", "payload": {"options": [{"id": "opt-devolver", "text_md": "Devolver a moeda ao achados e perdidos", "rationale_md": "É a opção mais honesta e justa."}, {"id": "opt-dulce", "text_md": "Comprar um doce para compartilhar com Zara", "rationale_md": "Pode parecer generoso, mas a moeda não é de Liruf, então não é correto usá-la sem permissão."}, {"id": "opt-guardar", "text_md": "Guardá-la no bolso e não dizer nada", "rationale_md": "É tentador porque ninguém viu, mas não é honesto ficar com algo que não lhe pertence."}], "scenario_md": "Liruf está no parque brincando com sua amiga Zara. De repente, ele vê uma moeda de 10 reais no chão. Ninguém mais a viu. Liruf pensa: ''O que devo fazer?''"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra quando aprendemos sobre honestidade? Liruf encontrou uma moeda de 10 reais no parque. O que ele deveria fazer? Pense passo a passo: quem poderia ser o dono? Como você se sentiria se perdesse algo? Escolha a melhor opção.", "difficulty": 1, "explanation_md": "A melhor decisão é devolver a moeda, porque é o honesto e justo. Comprar um doce ou guardá-la não considera o dono. Lembre-se: ser honesto é sempre a melhor opção.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"egoísmo": 0, "honestidad": 10, "generosidad": 5}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/f4906d93fe0e4f7433ab56653724b30db2584c77f55baf8b05e8c8364b25c542.mp3", "hash": "384d45f649069344d5916d78cff9a68dc5d42ddea15fff30bc1dd3bb912637d7", "bytes": 89136, "voice": "Ryan", "file_id": "lesson-audio/f4906d93fe0e4f7433ab56653724b30db2584c77f55baf8b05e8c8364b25c542.mp3", "duration_ms": 14800}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/6dbea9ad04c76b0f57c967d1e03c7c5a823c600282e167ece3f34f37507c273c.mp3", "hash": "ec0489ce1bae446aba06b23dec7ba05bdec1d351fe0b5ae17d9279be85c15647", "bytes": 73728, "voice": "Ryan", "file_id": "lesson-audio/6dbea9ad04c76b0f57c967d1e03c7c5a823c600282e167ece3f34f37507c273c.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-input", "title": "Verificar el ejercicio number_input", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia input se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "hints": ["El número que Zara quiere escribir es el que está entre el 4 y el 6."], "title": "Escribe el número", "payload": {"unit": "número", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Recuerda que en la lección pasada aprendimos a contar monedas. Zara quiere pagar 5 pesos por un dulce. ¿Qué número debe presionar en el teclado numérico para escribir 5?", "difficulty": 1, "explanation_md": "¡Correcto! Zara presionó el **5** en el teclado numérico. Así se escribe el número 5, que son los pesos que necesita pagar.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 5, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/7f35eb59fd167dff486bc7aa4b167f016d244810f361c42b9594b7db95306ab6.mp3", "hash": "fa59abe9e9bd403d6cdbd283d24dab856c699a234c6215eec0b500a078d14238", "bytes": 70416, "voice": "Li", "file_id": "lesson-audio/7f35eb59fd167dff486bc7aa4b167f016d244810f361c42b9594b7db95306ab6.mp3", "duration_ms": 11680}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/546347ef2f1808c5695fd9950e6b722a3c19bc5acdd7cbfc44cf551d38181cd4.mp3", "hash": "1f58c16acdde3ef1515f77f9bd576764ee211d3f7838330fc36b8829afbbb714", "bytes": 48384, "voice": "Li", "file_id": "lesson-audio/546347ef2f1808c5695fd9950e6b722a3c19bc5acdd7cbfc44cf551d38181cd4.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Contar objetos con Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''count_objects'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-objects", "xp": 5, "type": "count_objects", "hints": ["Mira bien todos los objetos en la escena. ¿Cuántos círculos ves?", "Señala cada círculo con el dedo mientras cuentas en voz alta."], "title": "Cuenta los objetos", "payload": {"scene": [{"icon": "circle", "tint": "primary", "count": 2}, {"icon": "circle", "tint": "accent", "count": 1}], "ask_icon": "circle"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Recuerdas que ayer contamos manzanas con Liruf? Hoy vamos a contar círculos. Liruf está ordenando juguetes y necesita ayuda para contar sus círculos rojos y azules. Primero, señala cada círculo mientras cuentas: uno, dos, tres. ¿Cuántos círculos hay en total?", "difficulty": 1, "explanation_md": "¡Correcto! Hay 3 círculos en la escena. Contaste correctamente.", "audio_segment_id": "s1-count-objects.prompt"}], "schema_version": 1}', '{"s1-count-objects": {"value": 3}}', '{"units": {"s1-count-objects.prompt": {"url": "http://localhost:4006/files/lesson-audio/6cfc61c6bc92e82f1fb19bfd05c4ab7cfc8f869efb7b634ab8e01f7836b2ff71.mp3", "hash": "13f04f5abd4a20b1da8139ec843d8fbfd5a6af11fdc9de6cd8a6dd1758a48cee", "bytes": 109296, "voice": "Li", "file_id": "lesson-audio/6cfc61c6bc92e82f1fb19bfd05c4ab7cfc8f869efb7b634ab8e01f7836b2ff71.mp3", "duration_ms": 18160}, "s1-count-objects.explanation": {"url": "http://localhost:4006/files/lesson-audio/0df5c2780955d70c81c68268715a6c7b9d7fda810bc9c1d389dbe1329e23e531.mp3", "hash": "e48fadc264907959b21e8f787488db39f1cfdb956703e5901ae7e74d92d8f0fd", "bytes": 26784, "voice": "Li", "file_id": "lesson-audio/0df5c2780955d70c81c68268715a6c7b9d7fda810bc9c1d389dbe1329e23e531.mp3", "duration_ms": 4400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Contar objetos com Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''count_objects'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-objects", "xp": 5, "type": "count_objects", "hints": ["Olhe bem todos os objetos na cena. Quantos círculos você vê?", "Aponte para cada círculo com o dedo enquanto conta em voz alta."], "title": "Conte os objetos", "payload": {"scene": [{"icon": "circle", "tint": "primary", "count": 2}, {"icon": "circle", "tint": "accent", "count": 1}], "ask_icon": "circle"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Lembra que ontem contamos maçãs com Liruf? Hoje vamos contar círculos. Liruf está organizando brinquedos e precisa de ajuda para contar seus círculos vermelhos e azuis. Primeiro, aponte para cada círculo enquanto conta: um, dois, três. Quantos círculos há no total?", "difficulty": 1, "explanation_md": "Correto! Há 3 círculos na cena. Você contou corretamente.", "audio_segment_id": "s1-count-objects.prompt"}], "schema_version": 1}', '{"s1-count-objects": {"value": 3}}', '{"units": {"s1-count-objects.prompt": {"url": "http://localhost:4006/files/lesson-audio/1aa40ceda041d906933c4c4a352b0c6e1ac6f365729b2ffb3264e740979e68f5.mp3", "hash": "d82e86ec0d6b7e5f6fe640ce223cf32c10dfc7c487e91f5f0130d23465682e3f", "bytes": 117936, "voice": "Ryan", "file_id": "lesson-audio/1aa40ceda041d906933c4c4a352b0c6e1ac6f365729b2ffb3264e740979e68f5.mp3", "duration_ms": 19600}, "s1-count-objects.explanation": {"url": "http://localhost:4006/files/lesson-audio/a5b990b3493e867c7293f4f40b1c99231506fa0559ea16fbc7e0e90cd82a270a.mp3", "hash": "f0f1db2d4d8784c28b2aa4d1232ae4269f2d0e83638d3773e2fb21b0792876fe", "bytes": 26208, "voice": "Ryan", "file_id": "lesson-audio/a5b990b3493e867c7293f4f40b1c99231506fa0559ea16fbc7e0e90cd82a270a.mp3", "duration_ms": 4320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "build-sentence", "title": "Armando frases con fichas", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio build_sentence de forma aislada", "Confirmar que cada tipo de la familia arrange se genera y renderiza correctamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sentence", "xp": 10, "type": "build_sentence", "hints": ["Pista 1: La frase comienza con ''Dina''.", "Pista 2: Después de ''Dina'' viene ''decide''."], "title": "Ordena las palabras", "payload": {"slots": 6, "tokens": [{"id": "t1", "text_md": "Dina"}, {"id": "t2", "text_md": "decide"}, {"id": "t3", "text_md": "ahorrar"}, {"id": "t4", "text_md": "sus"}, {"id": "t5", "text_md": "5"}, {"id": "t6", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como viste ayer, Dina guardó 3 pesos. Hoy tiene 5 pesos. ¿Debería comprar un lápiz o ahorrar? Ayúdala a decidir ordenando las palabras para formar su pensamiento.", "difficulty": 1, "explanation_md": "La frase correcta es ''Dina decide ahorrar sus 5 pesos''. Ahorrar es guardar dinero para usarlo después. ¡Bien hecho!", "audio_segment_id": "s1-build-sentence.prompt"}], "schema_version": 1}', '{"s1-build-sentence": {"order": ["t1", "t2", "t3", "t4", "t5", "t6"]}}', '{"units": {"s1-build-sentence.prompt": {"url": "http://localhost:4006/files/lesson-audio/c3941121b01b4f89503d826c9788200d5e22b7d9e810a094fd2b7228f6e09fac.mp3", "hash": "a05b2058548dc7e174265daed3ce01cb63c849c11c96a5a198e998deac78cc9f", "bytes": 67536, "voice": "Li", "file_id": "lesson-audio/c3941121b01b4f89503d826c9788200d5e22b7d9e810a094fd2b7228f6e09fac.mp3", "duration_ms": 11200}, "s1-build-sentence.explanation": {"url": "http://localhost:4006/files/lesson-audio/6408bc5587fdfb767d096f3bbb541d8bdd7783c4afe90cd9c5d24cc3ac30494c.mp3", "hash": "5ca90a8d5cbd134241a909adef23735d2ab4487797a466ed4e176e252f6544c5", "bytes": 55008, "voice": "Li", "file_id": "lesson-audio/6408bc5587fdfb767d096f3bbb541d8bdd7783c4afe90cd9c5d24cc3ac30494c.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "build-sentence", "title": "Montando frases com fichas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício build_sentence de forma isolada", "Confirmar que cada tipo da família arrange é gerado e renderizado corretamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sentence", "xp": 10, "type": "build_sentence", "hints": ["Dica 1: A frase começa com ''Dina''.", "Dica 2: Depois de ''Dina'' vem ''decide''."], "title": "Ordene as palavras", "payload": {"slots": 6, "tokens": [{"id": "t1", "text_md": "Dina"}, {"id": "t2", "text_md": "decide"}, {"id": "t3", "text_md": "economizar"}, {"id": "t4", "text_md": "seus"}, {"id": "t5", "text_md": "5"}, {"id": "t6", "text_md": "reais"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como você viu ontem, Dina guardou 3 reais. Hoje ela tem 5 reais. Ela deve comprar um lápis ou economizar? Ajude-a a decidir ordenando as palavras para formar seu pensamento.", "difficulty": 1, "explanation_md": "A frase correta é ''Dina decide economizar seus 5 reais''. Economizar é guardar dinheiro para usar depois. Muito bem!", "audio_segment_id": "s1-build-sentence.prompt"}], "schema_version": 1}', '{"s1-build-sentence": {"order": ["t1", "t2", "t3", "t4", "t5", "t6"]}}', '{"units": {"s1-build-sentence.prompt": {"url": "http://localhost:4006/files/lesson-audio/b72cdb309a933bcd723186065d1345fc4229d04ff90c8e6f15df0e874b8bf05f.mp3", "hash": "53c79c78cdcf48fa8a8bfeb6aa4c1ffb868b76c24d2f416be741e9bc2bb12631", "bytes": 82944, "voice": "Ryan", "file_id": "lesson-audio/b72cdb309a933bcd723186065d1345fc4229d04ff90c8e6f15df0e874b8bf05f.mp3", "duration_ms": 13760}, "s1-build-sentence.explanation": {"url": "http://localhost:4006/files/lesson-audio/93645eb75f0b74f987aea350141eaf8a5ffe11f9933935fea926ee0e7bcedce3.mp3", "hash": "fd388bc0ec68618a36ebd3831204917bc550e6cb26ccae7bf136124cefa47d8c", "bytes": 48816, "voice": "Ryan", "file_id": "lesson-audio/93645eb75f0b74f987aea350141eaf8a5ffe11f9933935fea926ee0e7bcedce3.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "timeline-order", "title": "Orden en la línea del tiempo", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''timeline_order'' de forma aislada.", "Confirmar que cada tipo de la familia arrange se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Piensa qué ocurre primero en la mañana, luego al mediodía y al final de la tarde. Por ejemplo, ¿qué haces tú justo después de levantarte?", "Relaciona cada evento con la hora del día: despertar es temprano, cenar es al anochecer."], "title": "Ordena los eventos", "payload": {"events": [{"id": "e1", "icon": "sunrise", "text_md": "Despertar"}, {"id": "e2", "icon": "food", "text_md": "Desayunar"}, {"id": "e3", "icon": "school", "text_md": "Ir a la escuela"}, {"id": "e4", "icon": "play", "text_md": "Jugar"}, {"id": "e5", "icon": "dinner", "text_md": "Cenar"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf se despierta a las 7 de la mañana. Después de despertar, desayuna a las 7:30. Luego va a la escuela a las 8. Por la tarde juega con sus amigos y finalmente cena a las 7 de la noche. Ayúdale a poner estos eventos en orden cronológico, del más temprano al más tarde. Recuerda lo que aprendiste sobre las rutinas diarias: primero nos despertamos, luego desayunamos, después vamos a la escuela, más tarde jugamos y finalmente cenamos. ¡Como en la lección anterior!", "difficulty": 1, "explanation_md": "El orden correcto es: Despertar, Desayunar, Ir a la escuela, Jugar, Cenar. Así es como suele transcurrir un día típico. ¡Buen trabajo!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6494fae502285694b9b237123281121f2709bd3e51588a4e2013ae195f4b740.mp3", "hash": "2c2d2944df39a3c367570f80dc66a8d6c402c86b0d4751b37b642391a71d3433", "bytes": 188928, "voice": "Li", "file_id": "lesson-audio/d6494fae502285694b9b237123281121f2709bd3e51588a4e2013ae195f4b740.mp3", "duration_ms": 31440}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/6327929f8091177fa9eb3e82bb29531a6bcc58ea14746ddfd9930c5839e8798c.mp3", "hash": "7e29cec34228cce27696a736246b1c0ca594b5c2b17a0db283a7619b6275ce54", "bytes": 62208, "voice": "Li", "file_id": "lesson-audio/6327929f8091177fa9eb3e82bb29531a6bcc58ea14746ddfd9930c5839e8798c.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "timeline-order", "title": "Order in the timeline", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''timeline_order'' exercise in isolation.", "Confirm that each type in the arrange family is generated and rendered correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Think about what happens first in the morning, then at noon, and at the end of the afternoon. For example, what do you do right after you get up?", "Match each event with the time of day: waking up is early, having dinner is at dusk."], "title": "Order the events", "payload": {"events": [{"id": "e1", "icon": "sunrise", "text_md": "Wake up"}, {"id": "e2", "icon": "food", "text_md": "Have breakfast"}, {"id": "e3", "icon": "school", "text_md": "Go to school"}, {"id": "e4", "icon": "play", "text_md": "Play"}, {"id": "e5", "icon": "dinner", "text_md": "Have dinner"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf wakes up at 7 in the morning. After waking up, he has breakfast at 7:30. Then he goes to school at 8. In the afternoon he plays with his friends and finally has dinner at 7 at night. Help him put these events in chronological order, from earliest to latest. Remember what you learned about daily routines: first we wake up, then we have breakfast, then we go to school, later we play, and finally we have dinner. Just like in the previous lesson!", "difficulty": 1, "explanation_md": "The correct order is: Wake up, Have breakfast, Go to school, Play, Have dinner. That''s how a typical day usually goes. Great job!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/e8c2ceb4fe8325993fa232ff5bab589743d8a667920b3eb3fc1ea821f9365929.mp3", "hash": "82b414bb8a858170ac4daaeeb7277715225974ad5450d5b36535f1687d0d5545", "bytes": 148176, "voice": "Jennifer", "file_id": "lesson-audio/e8c2ceb4fe8325993fa232ff5bab589743d8a667920b3eb3fc1ea821f9365929.mp3", "duration_ms": 24640}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/4ca406dd929776927b1526883ef4feab21f58dbae34b61e5389afc858cc8b503.mp3", "hash": "88b283f379d569524c4783cc1bfa625b937676869fb50b6c9d5d1527542cb3ab", "bytes": 58464, "voice": "Jennifer", "file_id": "lesson-audio/4ca406dd929776927b1526883ef4feab21f58dbae34b61e5389afc858cc8b503.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "confidence-quiz", "title": "Confidence in your answers", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each family choice type is generated and rendered correctly.", "Verify the ''confidence_quiz'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 0, "type": "confidence_quiz", "hints": ["Think about whether Dina feels very confident, somewhat confident, or not confident that she has enough coins."], "title": "How confident are you?", "payload": {"options": [{"id": "opt-muy-segura", "text_md": "Very confident", "rationale_md": "Dina has 10 coins and the toy costs 8, so she has enough and 2 left over."}, {"id": "opt-algo-segura", "text_md": "Somewhat confident", "rationale_md": "Dina is not completely sure how many coins she has or how much the toy costs."}, {"id": "opt-nada-segura", "text_md": "Not confident", "rationale_md": "Dina hasn''t counted her coins and doesn''t know if she has enough."}]}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "In the previous lesson, Dina learned to count coins. Now she has 10 coins and wants to buy a toy that costs 8 coins. Dina is sure she has enough. How confident is Dina that she can buy the toy? Help Dina choose the confidence level that best reflects how she feels. Is she very confident, somewhat confident, or not confident?", "difficulty": 1, "explanation_md": "Correct! Dina is very confident because she has 10 coins and the toy costs 8, so she has 2 left over. When you count your coins well, you can feel confident in your decision.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-muy-segura"}}', '{"units": {"s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/40b1de373f1e22f64a297f3ea591a1965954162122bbc920b1266e9e8458d819.mp3", "hash": "a10ee7578987d5c6e3c0144aed9f1a1eb64c7aed749d7b575f0bc28cd37732c0", "bytes": 136656, "voice": "Jennifer", "file_id": "lesson-audio/40b1de373f1e22f64a297f3ea591a1965954162122bbc920b1266e9e8458d819.mp3", "duration_ms": 22720}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/b5023ffd41496fef5ff77148d99b9c4dd293eb9eb21e6b8c59ece66b63b9d27a.mp3", "hash": "d35cadbcab3ae800b8d1e4f6e5254c96635b7cbe2b51d99e67c054e634612c1a", "bytes": 67536, "voice": "Jennifer", "file_id": "lesson-audio/b5023ffd41496fef5ff77148d99b9c4dd293eb9eb21e6b8c59ece66b63b9d27a.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "fair-trade", "title": "Intercambio justo: ¿Es justo?", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''fair_trade'' de forma aislada.", "Evaluar si un intercambio es justo usando precios de referencia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Compara el valor de cada artículo. ¿Cuánto cuesta el juguete? ¿Cuánto cuestan las golosinas?"], "title": "Intercambio justo: ¿Es justo?", "payload": {"offer_a": {"qty": 1, "icon": "toy", "label": "Juguete"}, "offer_b": {"qty": 1, "icon": "snack", "label": "Golosinas"}, "rate_md": "1 juguete (80 MXN) por 1 bolsa de golosinas (15 MXN)"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quiere cambiar su juguete (que cuesta 80 MXN) por una bolsa de golosinas (que cuesta 15 MXN). ¿Es justo el intercambio?", "difficulty": 1, "explanation_md": "El juguete vale 80 MXN y las golosinas valen 15 MXN. 80 es mayor que 15, por lo que Dina estaría dando mucho más de lo que recibe. El intercambio no es justo.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "a_wins"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/6200f29c6e377f2608c2a4c4e35e714c7e99475d0b0536c287dff378c49cd2cb.mp3", "hash": "6a6880c5b5cc448130beb8e8ed35bff24e80c259b60d7ee7a4f52c8506aa8ff8", "bytes": 51696, "voice": "Li", "file_id": "lesson-audio/6200f29c6e377f2608c2a4c4e35e714c7e99475d0b0536c287dff378c49cd2cb.mp3", "duration_ms": 8560}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/787b082b45e8719ced5142d226ba97a5347a2c898cdf82e1a2f0960a96265e53.mp3", "hash": "daef0ddc52d9fd554c95a8df5610497e88a4d62c2496f6ae679c0a720d666f5c", "bytes": 64656, "voice": "Li", "file_id": "lesson-audio/787b082b45e8719ced5142d226ba97a5347a2c898cdf82e1a2f0960a96265e53.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "fair-trade", "title": "Troca justa: É justo?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''fair_trade'' de forma isolada.", "Avaliar se uma troca é justa usando preços de referência."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Compare o valor de cada item. Quanto custa o brinquedo? Quanto custam as guloseimas?"], "title": "Troca justa: É justo?", "payload": {"offer_a": {"qty": 1, "icon": "toy", "label": "Brinquedo"}, "offer_b": {"qty": 1, "icon": "snack", "label": "Guloseimas"}, "rate_md": "1 brinquedo (80 MXN) por 1 saco de guloseimas (15 MXN)"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quer trocar seu brinquedo (que custa 80 MXN) por um saco de guloseimas (que custa 15 MXN). A troca é justa?", "difficulty": 1, "explanation_md": "O brinquedo vale 80 MXN e as guloseimas valem 15 MXN. 80 é maior que 15, então Dina estaria dando muito mais do que recebe. A troca não é justa.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "a_wins"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/032595de7a353ddf0a1e28aa72f358021868504b34adfd306d32c4f010e3a766.mp3", "hash": "a402f4239d9ad5339185d5dcff0a80e13666d4deeb0f6b5c4456a77d66a6925c", "bytes": 53568, "voice": "Ryan", "file_id": "lesson-audio/032595de7a353ddf0a1e28aa72f358021868504b34adfd306d32c4f010e3a766.mp3", "duration_ms": 8880}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/969c0ee8c60a2691674d33f8b27844d99043278fde504be30d2c4a1085e6a16d.mp3", "hash": "0be8442abe5ccd7e0619c6717089a8ad365aa041d336ad32b70d99b1b3f812a2", "bytes": 67536, "voice": "Ryan", "file_id": "lesson-audio/969c0ee8c60a2691674d33f8b27844d99043278fde504be30d2c4a1085e6a16d.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparando con Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio compare_table de forma aislada", "Confirmar que cada tipo de la familia analyze se genera y renderiza correctamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Mira el dibujo de cada ficha: ¿ayuda a ahorrar para el juguete o es para gastar ahora?", "Piensa: ¿esta ficha va con la opción de ahorrar o con la de gastar?"], "title": "Llena la tabla comparativa", "payload": {"cols": [{"id": "c1", "label": "Ahorrar para el juguete"}, {"id": "c2", "label": "Gastar ahora en golosinas"}], "rows": [{"id": "r1", "label": "Ficha 1"}, {"id": "r2", "label": "Ficha 2"}, {"id": "r3", "label": "Ficha 3"}], "tokens": [{"id": "t1", "text_md": "Ahorra **$10** cada semana"}, {"id": "t2", "text_md": "Gasta *$5* en golosinas"}, {"id": "t3", "text_md": "Junta *$50* en un mes"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quiere comprar un juguete nuevo, pero también le gustan las golosinas. Ayúdala a decidir colocando cada ficha en la columna correcta. **Recuerda**: en el ejercicio anterior de causa y efecto, aprendiste a identificar relaciones. Ahora vamos a practicar con una tabla para comparar dos opciones.", "difficulty": 1, "explanation_md": "¡Muy bien! Has colocado cada ficha donde corresponde. Así Dina puede ver qué opción le conviene más para comprar su juguete.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"r1_c1": "t1", "r2_c2": "t2", "r3_c1": "t3"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/64b1a5bf2902cebc18cd62d1637c208774ce19a8bf874065946df1bf52af51d5.mp3", "hash": "d62f95e0491fdbb03b071a9eb77a7a4e813e4a670a064cd265403058fd1b2fe0", "bytes": 99216, "voice": "Li", "file_id": "lesson-audio/64b1a5bf2902cebc18cd62d1637c208774ce19a8bf874065946df1bf52af51d5.mp3", "duration_ms": 16480}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/7a2349bf75759e6caef33873fd749f28e8fa056e8b0a817fd8d3a52e76747688.mp3", "hash": "e73d8d886f3b26dbee3792a16e37fff48369c23eafea7d7f8a8704b42a65a2de", "bytes": 46944, "voice": "Li", "file_id": "lesson-audio/7a2349bf75759e6caef33873fd749f28e8fa056e8b0a817fd8d3a52e76747688.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparing with Dina", "locale": "en-US", "subject": "mixed", "objectives": ["Check the compare_table exercise in isolation", "Confirm that each type in the analyze family is generated and rendered correctly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Look at the picture on each card: does it help save for the toy or is it for spending now?", "Think: does this card go with the saving option or the spending option?"], "title": "Fill in the comparison table", "payload": {"cols": [{"id": "c1", "label": "Save for the toy"}, {"id": "c2", "label": "Spend now on treats"}], "rows": [{"id": "r1", "label": "Card 1"}, {"id": "r2", "label": "Card 2"}, {"id": "r3", "label": "Card 3"}], "tokens": [{"id": "t1", "text_md": "Save **$10** each week"}, {"id": "t2", "text_md": "Spend *$5* on treats"}, {"id": "t3", "text_md": "Save *$50* in a month"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina wants to buy a new toy, but she also likes treats. Help her decide by placing each card in the correct column. **Remember**: in the previous cause and effect exercise, you learned to identify relationships. Now we''ll practice with a table to compare two options.", "difficulty": 1, "explanation_md": "Great job! You placed each card where it belongs. Now Dina can see which option is better for buying her toy.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"r1_c1": "t1", "r2_c2": "t2", "r3_c1": "t3"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/39c6ae23cb1555f9c285e878da85a123dd121c89279041f1e0ce954293203b54.mp3", "hash": "8bb663edb7e1d1a0bb590d831d6b2833e85bd6024e883806b8a991e2833662cc", "bytes": 88704, "voice": "Jennifer", "file_id": "lesson-audio/39c6ae23cb1555f9c285e878da85a123dd121c89279041f1e0ce954293203b54.mp3", "duration_ms": 14720}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/a9153a6ceff3e1f04e8f45b2c1324b56cc0366826dd2395aecf2f30b9955d956.mp3", "hash": "d68331495fcc57a014ef65cb9ed9065221ba3fb74f33a7503624d618fa7f0278", "bytes": 42624, "voice": "Jennifer", "file_id": "lesson-audio/a9153a6ceff3e1f04e8f45b2c1324b56cc0366826dd2395aecf2f30b9955d956.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparando com Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício compare_table de forma isolada", "Confirmar que cada tipo da família analyze é gerado e renderizado corretamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Olhe o desenho de cada ficha: ela ajuda a economizar para o brinquedo ou é para gastar agora?", "Pense: esta ficha vai com a opção de economizar ou com a de gastar?"], "title": "Preencha a tabela comparativa", "payload": {"cols": [{"id": "c1", "label": "Economizar para o brinquedo"}, {"id": "c2", "label": "Gastar agora em guloseimas"}], "rows": [{"id": "r1", "label": "Ficha 1"}, {"id": "r2", "label": "Ficha 2"}, {"id": "r3", "label": "Ficha 3"}], "tokens": [{"id": "t1", "text_md": "Economize **$10** por semana"}, {"id": "t2", "text_md": "Gaste *$5* em guloseimas"}, {"id": "t3", "text_md": "Junte *$50* em um mês"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quer comprar um brinquedo novo, mas também gosta de guloseimas. Ajude-a a decidir colocando cada ficha na coluna correta. **Lembre-se**: no exercício anterior de causa e efeito, você aprendeu a identificar relações. Agora vamos praticar com uma tabela para comparar duas opções.", "difficulty": 1, "explanation_md": "Muito bem! Você colocou cada ficha no lugar certo. Assim Dina pode ver qual opção é melhor para comprar o brinquedo dela.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"r1_c1": "t1", "r2_c2": "t2", "r3_c1": "t3"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/6443b3e998cfdc994079c395d930f0e77fe592ab096bd8bcd19f139e99e06dc3.mp3", "hash": "7a8c7f46905ce07c3cbb87b7855394aea99d0cfa6fa8a38fcf8324f744b3234f", "bytes": 106416, "voice": "Ryan", "file_id": "lesson-audio/6443b3e998cfdc994079c395d930f0e77fe592ab096bd8bcd19f139e99e06dc3.mp3", "duration_ms": 17680}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/8669040c6876a7792a083d40d08d4a884c79cc4e49223ba29d0e9fae292b6a9d.mp3", "hash": "6e3efbee1e62b3874f8a84aa1f0b736aa8a4d424cd2be538dbe82efafb511fe4", "bytes": 58896, "voice": "Ryan", "file_id": "lesson-audio/8669040c6876a7792a083d40d08d4a884c79cc4e49223ba29d0e9fae292b6a9d.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "cause-effect", "title": "Cadena de causa y efecto", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''cause_effect'' de forma aislada.", "Confirmar que cada tipo de la familia analyze se genera y renderiza correctamente."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 15, "type": "cause_effect", "hints": ["Piensa qué evento ocurre primero y cuál es el resultado final.", "Busca palabras como ''porque'' o ''entonces'' que conectan las ideas."], "title": "La cadena de Zara", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Zara olvidó su lonche en casa."}, {"id": "e2", "text_md": "Zara sintió hambre a media mañana."}, {"id": "e3", "text_md": "Zara le pidió prestado a su amigo."}, {"id": "e4", "text_md": "Zara compró una fruta en la tienda."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerdas cómo Dina y Zara hablaron de decisiones ayer? Hoy veremos lo que pasa después. Zara está armando una cadena de causa y efecto. Ayúdala a ordenar los eventos del 1 al 4, donde 1 es la causa inicial y 4 el efecto final. Por ejemplo, si Zara tenía 0 snacks, ¿qué pasó?", "difficulty": 2, "explanation_md": "La causa inicial es que Zara olvidó su lonche, lo que la llevó a tener hambre, luego a pedir prestado, y finalmente a comprar una fruta. ¡Bien hecho!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e4c4f6a71a3b0b8395e5337f4343d09f248db2bbe12eae23ee31ff6fc463bc7.mp3", "hash": "43f86f739da8684393fa9bbc28b0610e8db2eb7c450718dc77677e61495dd765", "bytes": 125568, "voice": "Li", "file_id": "lesson-audio/5e4c4f6a71a3b0b8395e5337f4343d09f248db2bbe12eae23ee31ff6fc463bc7.mp3", "duration_ms": 20880}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/ce05cdecc202996e7a4d022a82e78ef81783b383814a59dbccefc181fddaeff6.mp3", "hash": "be097b7e361b79ca5e2bcb7ffb1cec004ec71b5924133887bc1a46d51dd39672", "bytes": 54144, "voice": "Li", "file_id": "lesson-audio/ce05cdecc202996e7a4d022a82e78ef81783b383814a59dbccefc181fddaeff6.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "cause-effect", "title": "Cause and effect chain", "locale": "en-US", "subject": "mixed", "objectives": ["Verify the ''cause_effect'' exercise in isolation.", "Confirm that each type of the analyze family is generated and rendered correctly."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 15, "type": "cause_effect", "hints": ["Think about which event happens first and what the final result is.", "Look for words like ''because'' or ''so'' that connect the ideas."], "title": "Zara''s chain", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Zara forgot her lunch at home."}, {"id": "e2", "text_md": "Zara felt hungry mid-morning."}, {"id": "e3", "text_md": "Zara borrowed from her friend."}, {"id": "e4", "text_md": "Zara bought a fruit at the store."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember how Dina and Zara talked about decisions yesterday? Today we''ll see what happens next. Zara is putting together a cause and effect chain. Help her order the events from 1 to 4, where 1 is the initial cause and 4 is the final effect. For example, if Zara had 0 snacks, what happened?", "difficulty": 2, "explanation_md": "The initial cause is that Zara forgot her lunch, which led to her being hungry, then to borrowing, and finally to buying a fruit. Well done!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/6111da4751b6941ae2a8f928a743c8012e875bb613f66b3cae6effce978c774d.mp3", "hash": "04547a05eb12bc4ad88fb7efe1ad73d55a9d860d1d68da3124a08ebd0a382448", "bytes": 105408, "voice": "Jennifer", "file_id": "lesson-audio/6111da4751b6941ae2a8f928a743c8012e875bb613f66b3cae6effce978c774d.mp3", "duration_ms": 17520}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/e918f0091251876f2f6ec712e8aeee23fbcafd141cecc4ec99de29bf2a73b107.mp3", "hash": "12c12862fe0f1cfc081fb8244e946356b56b63ca32fe64233f3fbc2676961d3c", "bytes": 51264, "voice": "Jennifer", "file_id": "lesson-audio/e918f0091251876f2f6ec712e8aeee23fbcafd141cecc4ec99de29bf2a73b107.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "cause-effect", "title": "Cadeia de causa e efeito", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''cause_effect'' de forma isolada.", "Confirmar que cada tipo da família analyze é gerado e renderizado corretamente."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 15, "type": "cause_effect", "hints": ["Pense em qual evento ocorre primeiro e qual é o resultado final.", "Procure palavras como ''porque'' ou ''então'' que conectam as ideias."], "title": "A cadeia da Zara", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Zara esqueceu o lanche em casa."}, {"id": "e2", "text_md": "Zara sentiu fome no meio da manhã."}, {"id": "e3", "text_md": "Zara pediu emprestado ao amigo."}, {"id": "e4", "text_md": "Zara comprou uma fruta na loja."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra como Dina e Zara falaram sobre decisões ontem? Hoje veremos o que acontece depois. Zara está montando uma cadeia de causa e efeito. Ajude-a a ordenar os eventos de 1 a 4, onde 1 é a causa inicial e 4 o efeito final. Por exemplo, se Zara tinha 0 lanches, o que aconteceu?", "difficulty": 2, "explanation_md": "A causa inicial é que Zara esqueceu seu lanche, o que a levou a sentir fome, depois a pedir emprestado e, finalmente, a comprar uma fruta. Muito bem!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/96b1cbffea3858ef072540faa9844370aa8fb2af05ab6b92852f01d2701e3126.mp3", "hash": "5bce14644d2b292b5a560fae6a2effc00834066a7a9b1008c1a0c77bd30ed7d5", "bytes": 110736, "voice": "Ryan", "file_id": "lesson-audio/96b1cbffea3858ef072540faa9844370aa8fb2af05ab6b92852f01d2701e3126.mp3", "duration_ms": 18400}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/6aef9b1eb3c113b6316854153f0dfe7cd41751361f60c52861269c993d5cdbc5.mp3", "hash": "e195ad17b56e9e3dd87edd7b5fe2d9fc9671bd7480e717403cd86517eb1083fe", "bytes": 65664, "voice": "Ryan", "file_id": "lesson-audio/6aef9b1eb3c113b6316854153f0dfe7cd41751361f60c52861269c993d5cdbc5.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "Señales sospechosas en un anuncio", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''red_flags'' de forma aislada.", "Identificar señales sospechosas en un anuncio falso."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Piensa en promesas que parecen demasiado buenas para ser verdad.", "Fíjate en los detalles que piden información personal."], "title": "¿Qué señales ves?", "payload": {"flags": [{"id": "flag-1", "text_md": "Promesa de algo gratis sin condiciones claras"}, {"id": "flag-2", "text_md": "Solicita información personal sensible"}, {"id": "flag-3", "text_md": "Urgencia: ''solo hoy'' para presionar a decidir rápido"}, {"id": "flag-4", "text_md": "No hay detalles de la empresa o contacto real"}], "artifact_md": "¡Gana una tablet **GRATIS**! Solo responde 3 preguntas. Envía tu nombre, dirección y número de teléfono para reclamar. ¡Oferta válida solo hoy!", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Como aprendimos ayer sobre anuncios confiables, hoy veremos señales de alerta. Zara encontró un anuncio en internet que promete una tablet **gratis** solo por llenar una encuesta. Ella sospecha que es una estafa. Dina, Liruf y Rho también están viendo el anuncio y quieren ayudar. Juntos, identifiquen las **señales de alerta**. Por ejemplo, Zara dice: ''Prometer algo gratis sin condiciones claras es sospechoso''. ¿Qué otras señales ven?", "difficulty": 1, "explanation_md": "Las señales de alerta son pistas que indican que algo puede ser un fraude. En este anuncio, las promesas exageradas y la solicitud de datos personales son banderas rojas.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag-1", "flag-2", "flag-3", "flag-4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/c980bc7a400a54c18ef3f30395943536bd79edb9f5ef3403371f4cec58b4888f.mp3", "hash": "ae0a923a5508cf016d4f62e23302dfbf86746ce6d31232c7d6c6933d1e434a92", "bytes": 180864, "voice": "Li", "file_id": "lesson-audio/c980bc7a400a54c18ef3f30395943536bd79edb9f5ef3403371f4cec58b4888f.mp3", "duration_ms": 30080}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/baeb118c3a7d48ebeb871e975be10646114add80737ef424ac73b9797b9191a8.mp3", "hash": "95031fdf2a6b104aa0758c4dc7fe43c086a30678f379958370e785dd538ba2e4", "bytes": 58464, "voice": "Li", "file_id": "lesson-audio/baeb118c3a7d48ebeb871e975be10646114add80737ef424ac73b9797b9191a8.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "Sinais suspeitos em um anúncio", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''red_flags'' de forma isolada.", "Identificar sinais suspeitos em um anúncio falso."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Pense em promessas que parecem boas demais para ser verdade.", "Observe os detalhes que pedem informações pessoais."], "title": "Que sinais você vê?", "payload": {"flags": [{"id": "flag-1", "text_md": "Promessa de algo grátis sem condições claras"}, {"id": "flag-2", "text_md": "Solicita informações pessoais sensíveis"}, {"id": "flag-3", "text_md": "Urgência: ''só hoje'' para pressionar a decidir rápido"}, {"id": "flag-4", "text_md": "Não há detalhes da empresa ou contato real"}], "artifact_md": "Ganhe um tablet **GRÁTIS**! Responda apenas 3 perguntas. Envie seu nome, endereço e número de telefone para resgatar. Oferta válida só hoje!", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Como aprendemos ontem sobre anúncios confiáveis, hoje veremos sinais de alerta. Zara encontrou um anúncio na internet que promete um tablet **grátis** só por preencher uma pesquisa. Ela suspeita que é um golpe. Dina, Liruf e Rho também estão vendo o anúncio e querem ajudar. Juntos, identifiquem os **sinais de alerta**. Por exemplo, Zara diz: ''Prometer algo grátis sem condições claras é suspeito''. Que outros sinais vocês veem?", "difficulty": 1, "explanation_md": "Os sinais de alerta são pistas que indicam que algo pode ser uma fraude. Neste anúncio, as promessas exageradas e a solicitação de dados pessoais são bandeiras vermelhas.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag-1", "flag-2", "flag-3", "flag-4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/1dae44b242eb05e98d858bba49015feb31fe735528b89c7743e21b5103773851.mp3", "hash": "ac96c6c43fc069c1742bc02b5f7cd8c1970e36f25233845a250797352a8e11a0", "bytes": 167328, "voice": "Ryan", "file_id": "lesson-audio/1dae44b242eb05e98d858bba49015feb31fe735528b89c7743e21b5103773851.mp3", "duration_ms": 27840}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/0da3c54acc3b685be56cd99db1c41e20dc619cecc5cfd4dce8426ccae184f1b0.mp3", "hash": "eeaa73b0c5788823e1492fa04395b6dd2b444b459f1bd592ad6a51a3dca6b818", "bytes": 76176, "voice": "Ryan", "file_id": "lesson-audio/0da3c54acc3b685be56cd99db1c41e20dc619cecc5cfd4dce8426ccae184f1b0.mp3", "duration_ms": 12640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "dialogue-choice", "title": "Diálogo com Rho: Escolha sua resposta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''dialogue_choice'' de forma isolada (fluxo de diálogo)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue-choice", "xp": 0, "type": "dialogue_choice", "hints": ["Pense no que você aprendeu antes sobre trocas: é justo trocar 5 maçãs por 3 laranjas? Lembre-se de que 1 maçã = 1 moeda, 1 laranja = 2 moedas.", "Se tiver dúvidas, você pode pedir tempo para pensar, mas às vezes é preciso decidir rápido."], "title": "Escolha sua resposta", "payload": {"turns": [{"id": "turn-1", "npc_md": "Olá, Rho! Tenho 5 maçãs e quero trocá-las por 3 das suas laranjas. O que você acha?", "replies": [{"id": "reply-1a", "text_md": "Claro, aceito a troca."}, {"id": "reply-1b", "text_md": "Não, prefiro ficar com minhas laranjas."}, {"id": "reply-1c", "text_md": "Deixe-me pensar um momento."}]}, {"id": "turn-2", "npc_md": "Tudo bem, mas se você não aceitar agora, talvez eu não tenha mais maçãs depois. O que me diz?", "replies": [{"id": "reply-2a", "text_md": "Tudo bem, vamos fazer a troca."}, {"id": "reply-2b", "text_md": "Não, obrigado, melhor não."}, {"id": "reply-2c", "text_md": "Preciso consultar outra pessoa."}]}], "persona": {"name": "Rho", "role_md": "Um explorador curioso que sempre pergunta antes de agir.", "character": "rho"}, "opening_md": "Rho encontra um amigo no mercado. O amigo lhe oferece uma troca. Rho lembra que na aula anterior aprendeu a comparar quantidades usando valores. Será um bom negócio?"}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho precisa da sua ajuda para decidir o que responder. Leia cada opção e escolha a que você acha melhor. Lembre-se de que na lição anterior você aprendeu que as trocas justas têm valor total igual. Por exemplo, se 1 maçã vale 1 moeda e 1 laranja vale 2 moedas, então 5 maçãs (5 moedas) não são equivalentes a 3 laranjas (6 moedas). O que você faria?", "difficulty": 1, "explanation_md": "Neste exercício, você pratica como escolher uma resposta em um diálogo. Cada escolha pode mudar a história. Preste atenção nas consequências de cada opção.", "audio_segment_id": "s1-dialogue-choice.prompt"}], "schema_version": 1}', '{"s1-dialogue-choice": {"turns": [{"turn_id": "turn-1", "qualities": {"decisión": 1}, "reactions": {"reply-1a": "aceptó", "reply-1b": "rechazó", "reply-1c": "dudó"}}, {"turn_id": "turn-2", "qualities": {"decisión": 1}, "reactions": {"reply-2a": "aceptó", "reply-2b": "rechazó", "reply-2c": "dudó"}}]}}', '{"units": {"s1-dialogue-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/6c7da5a4c43ef02d82d3a8255a7a71de05d4111285ac950e759127573cf90629.mp3", "hash": "bc53d2266dac804dc331a23622554155e4bbbbd28bd8b5bc3c7f4a448cd974c6", "bytes": 167328, "voice": "Ryan", "file_id": "lesson-audio/6c7da5a4c43ef02d82d3a8255a7a71de05d4111285ac950e759127573cf90629.mp3", "duration_ms": 27840}, "s1-dialogue-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/f4dba0df4c2b54f1ac30d7b7fc22aa1481874c2f037867ad168e90e8983b8476.mp3", "hash": "f1986a24120c097bd1b140bb5b83be43ccd2d1647e7bb03eceb57a2aa6bd688d", "bytes": 60336, "voice": "Ryan", "file_id": "lesson-audio/f4dba0df4c2b54f1ac30d7b7fc22aa1481874c2f037867ad168e90e8983b8476.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "machine-io", "title": "Zara''s Function Machine", "locale": "en-US", "subject": "mixed", "objectives": ["Test the machine_io exercise in isolation.", "Confirm that each type in the maker family is generated and rendered correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Hint 1: The machine always adds the same number of candies.", "Hint 2: From 1 to 6 you add 5; from 2 to 7 also 5. So, 3 + 5 = 8."], "title": "Practice: machine_io", "payload": {"options": [{"id": "opt-a", "text_md": "6"}, {"id": "opt-b", "text_md": "7"}, {"id": "opt-c", "text_md": "8"}, {"id": "opt-d", "text_md": "9"}], "examples": [{"in": 1, "out": 6}, {"in": 2, "out": 7}], "probe_in": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara is building a machine to hand out candies fairly at her party. First, she tests with real candies: if she puts 1 candy on a plate, she adds 5 more so there are 6. If she puts 2, she adds 5 and gets 7. Remember how Zara handed out candies last time: she always added the same amount. How many candies come out if she puts 3?", "difficulty": 1, "explanation_md": "Correct! The rule is: output = input + 5. So with input 3, the output is 8.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "opt-c"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/815285b9f483c7fa5dcf45b801f1bf2dabdd281afe64b3ce1d46c3c06b4fe42c.mp3", "hash": "fdcd9131a37645b2058b18dc5962da8b6baa12d560f4fdf0487fa513d7e419b8", "bytes": 129024, "voice": "Jennifer", "file_id": "lesson-audio/815285b9f483c7fa5dcf45b801f1bf2dabdd281afe64b3ce1d46c3c06b4fe42c.mp3", "duration_ms": 21440}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/d71936dcb811075d04e3dec4a0383ecbca2a34609f0fcdf21c0a0443a069702d.mp3", "hash": "9dc0f6c3be42af9e8284d1a6438f1d8e8009648a1ef3a337c028e69ee95b29ee", "bytes": 41184, "voice": "Jennifer", "file_id": "lesson-audio/d71936dcb811075d04e3dec4a0383ecbca2a34609f0fcdf21c0a0443a069702d.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "story-scene", "title": "Liruf ahorra para una guitarra", "locale": "es-MX", "subject": "mixed", "objectives": ["Comprender la importancia de ahorrar para una meta", "Practicar la toma de decisiones financieras básicas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verificar-story-scene", "xp": 0, "type": "story_scene", "hints": ["Pista 1: Piensa en una recta numérica del 0 al 100. ¿Cuántos saltos hay desde 40 hasta 100?", "Pista 2: Si tienes 40 monedas y necesitas 100, puedes restar: 100 - 40 = ?"], "title": "Liruf ahorra para una guitarra", "payload": {"art": {"icon": "liruf", "tint": "primary"}, "action": "idle", "body_md": "Liruf está emocionado porque quiere comprar una guitarra nueva. Ha estado ahorrando monedas en su alcancía. Ya tiene 40 monedas, pero la guitarra cuesta 100. ¡Le faltan muchas! Pero no se rinde: cada semana guarda 10 monedas. ¿Cuántas monedas le faltan? Ayuda a Liruf a calcularlo. (Recuerda: en la lección anterior aprendiste a restar números hasta 100).", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf quiere comprar una guitarra que cuesta 100 monedas. Ya ha ahorrado 40 monedas. ¿Cuántas monedas más necesita? Observa la imagen y ayuda a Liruf a decidir.", "difficulty": 1, "explanation_md": "Liruf necesita 60 monedas más para comprar la guitarra. ¡Ahorrar poco a poco ayuda a alcanzar las metas! Por ejemplo, 100 - 40 = 60. Si juntaras 10 monedas cada semana, en 6 semanas tendrías las 60 monedas.", "audio_segment_id": "s1-verificar-story-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-verificar-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/1b166fa934f6ee372208970a2fd4baf1631ca7117ab5b0ded91b633422785d21.mp3", "hash": "a465c294527a21ada453a7f4774e2f675783efb3fe75ae69823a0b00f5b36fa6", "bytes": 128448, "voice": "Li", "file_id": "lesson-audio/1b166fa934f6ee372208970a2fd4baf1631ca7117ab5b0ded91b633422785d21.mp3", "duration_ms": 21360}, "s1-verificar-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/4ea7054b4eccd006f5c634e7695b075150f85db3a83c4b52d0d8589dad9fa721.mp3", "hash": "512bfe63bce648d2311420900a9e9eea76ffe04611ab7383826409812feb99cf", "bytes": 64656, "voice": "Li", "file_id": "lesson-audio/4ea7054b4eccd006f5c634e7695b075150f85db3a83c4b52d0d8589dad9fa721.mp3", "duration_ms": 10720}, "s1-verificar-story-scene.explanation": {"url": "http://localhost:4006/files/lesson-audio/2403acccb5820958e8e161f39449c2cc59a2d97a4c0e60a8c77c500399a87eeb.mp3", "hash": "40ec161c21d7eefbd55ef752b774c24ce82a55906f483a9ea87c95c1ea117522", "bytes": 98208, "voice": "Li", "file_id": "lesson-audio/2403acccb5820958e8e161f39449c2cc59a2d97a4c0e60a8c77c500399a87eeb.mp3", "duration_ms": 16320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "story-scene", "title": "Liruf saves for a guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Understand the importance of saving for a goal", "Practice basic financial decision-making"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verificar-story-scene", "xp": 0, "type": "story_scene", "hints": ["Hint 1: Think of a number line from 0 to 100. How many jumps are there from 40 to 100?", "Hint 2: If you have 40 coins and you need 100, you can subtract: 100 - 40 = ?"], "title": "Liruf saves for a guitar", "payload": {"art": {"icon": "liruf", "tint": "primary"}, "action": "idle", "body_md": "Liruf is excited because he wants to buy a new guitar. He has been saving coins in his piggy bank. He already has 40 coins, but the guitar costs 100. He still needs many! But he doesn''t give up: each week he saves 10 coins. How many coins does he still need? Help Liruf calculate it. (Remember: in the previous lesson you learned to subtract numbers up to 100.)", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf wants to buy a guitar that costs 100 coins. He has already saved 40 coins. How many more coins does he need? Look at the picture and help Liruf decide.", "difficulty": 1, "explanation_md": "Liruf needs 60 more coins to buy the guitar. Saving little by little helps you reach your goals! For example, 100 - 40 = 60. If you saved 10 coins each week, in 6 weeks you would have the 60 coins.", "audio_segment_id": "s1-verificar-story-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-verificar-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/c3a26be221e0a7ca6efe4b7ed0d1e2fc2cea81c4c5919be3c52fe6311d2f86e9.mp3", "hash": "c8b54bfd57e2501b7921f2fbeed453b329a54723de02f7abaee5a3a39a464d84", "bytes": 129888, "voice": "Jennifer", "file_id": "lesson-audio/c3a26be221e0a7ca6efe4b7ed0d1e2fc2cea81c4c5919be3c52fe6311d2f86e9.mp3", "duration_ms": 21600}, "s1-verificar-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/456dda7ffe414869019a43efe85747003d346c5bb4f482fa41e1b98bd8c5d93a.mp3", "hash": "06c052589cf2953ef0fd1a09b8e5897e714198d979f4b160d7b41d2a915f010d", "bytes": 63216, "voice": "Jennifer", "file_id": "lesson-audio/456dda7ffe414869019a43efe85747003d346c5bb4f482fa41e1b98bd8c5d93a.mp3", "duration_ms": 10480}, "s1-verificar-story-scene.explanation": {"url": "http://localhost:4006/files/lesson-audio/305bfb76ae6cf6682608f7296f6890ae734fb37fd0b8f22545895832efd3869f.mp3", "hash": "6dac12d8e6cf6264398266e125ccd9dd8c1cee8440feaa2e6de9d1c5079eec1c", "bytes": 86256, "voice": "Jennifer", "file_id": "lesson-audio/305bfb76ae6cf6682608f7296f6890ae734fb37fd0b8f22545895832efd3869f.mp3", "duration_ms": 14320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "story-scene", "title": "Liruf poupa para um violão", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender a importância de poupar para uma meta", "Praticar a tomada de decisões financeiras básicas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verificar-story-scene", "xp": 0, "type": "story_scene", "hints": ["Dica 1: Pense em uma reta numérica de 0 a 100. Quantos saltos existem de 40 até 100?", "Dica 2: Se você tem 40 moedas e precisa de 100, pode subtrair: 100 - 40 = ?"], "title": "Liruf poupa para um violão", "payload": {"art": {"icon": "liruf", "tint": "primary"}, "action": "idle", "body_md": "Liruf está animado porque quer comprar um violão novo. Ele vem poupando moedas em seu cofrinho. Já tem 40 moedas, mas o violão custa 100. Faltam muitas! Mas ele não desiste: a cada semana guarda 10 moedas. Quantas moedas faltam? Ajude Liruf a calcular. (Lembre-se: na lição anterior você aprendeu a subtrair números até 100).", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf quer comprar um violão que custa 100 moedas. Ele já poupou 40 moedas. Quantas moedas ele precisa a mais? Observe a imagem e ajude Liruf a decidir.", "difficulty": 1, "explanation_md": "Liruf precisa de mais 60 moedas para comprar o violão. Poupar aos poucos ajuda a alcançar as metas! Por exemplo, 100 - 40 = 60. Se você juntasse 10 moedas a cada semana, em 6 semanas teria as 60 moedas.", "audio_segment_id": "s1-verificar-story-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-verificar-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/59994b7b86a194b4b66c35d8143d94cdc421a97102ff5b740f0e788cd54f5d08.mp3", "hash": "f4caf9b72d7292f81747615f14c24776cbd1bb9662654fc978af84283ca48079", "bytes": 145728, "voice": "Ryan", "file_id": "lesson-audio/59994b7b86a194b4b66c35d8143d94cdc421a97102ff5b740f0e788cd54f5d08.mp3", "duration_ms": 24240}, "s1-verificar-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/d7c7bab97501663603f5d977cbe2f7db17d7c3b693f544bfff8322d99562dfbf.mp3", "hash": "211ae0b9f34f3041d4ec0190308550c6d5cf4e9d30e70fb9352ceaf47f778eb0", "bytes": 63648, "voice": "Ryan", "file_id": "lesson-audio/d7c7bab97501663603f5d977cbe2f7db17d7c3b693f544bfff8322d99562dfbf.mp3", "duration_ms": 10560}, "s1-verificar-story-scene.explanation": {"url": "http://localhost:4006/files/lesson-audio/f026a3ebd845a936dbcaecb07994c72cd9e24978c81bc24594b0048888172adb.mp3", "hash": "ad7f382409db850ff3ec582df0fc0dc4526f638db7f1a9532f4a39c5d44a71b6", "bytes": 108864, "voice": "Ryan", "file_id": "lesson-audio/f026a3ebd845a936dbcaecb07994c72cd9e24978c81bc24594b0048888172adb.mp3", "duration_ms": 18080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "yes-no-cases", "title": "Comprar ou poupar?", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se comprar um brinquedo ou poupar as moedas, aplicando uma regra de gasto responsável."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": [], "title": "Comprar ou poupar?", "payload": {"cases": [{"id": "caso1", "text_md": "**Sim**, comprar o carrinho (8 moedas) e poupar as 2 que sobram."}, {"id": "caso2", "text_md": "**Não**, comprar o carrinho e também um sorvete de 3 moedas, gastando 11 moedas."}, {"id": "caso3", "text_md": "**Sim**, não comprar nada e poupar as 10 moedas para a bola."}], "rule_md": "Só gastar se sobrar o suficiente para poupar pelo menos metade do que você tem."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho tem 10 moedas. Quer comprar um carrinho de brinquedo que custa 8 moedas, mas também quer poupar para uma bola que custa 12 moedas. Ajude Rho a decidir se cada opção é uma boa escolha de acordo com a regra: **Só gastar se sobrar o suficiente para poupar pelo menos metade do que você tem**.", "difficulty": 1, "explanation_md": "Muito bem! Rho aprendeu a pensar antes de gastar. Se você gasta muito, não sobra para poupar.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["caso1", "caso3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/0fb700bc61554dab49c8d9f13bdc2e5049d4331094d520cc8dfd9fe66d6660d0.mp3", "hash": "f29110a02d64677c93cb3b7c28fc35b2ff87d1a18a7651ab2d41d3751d70c9d2", "bytes": 133776, "voice": "Ryan", "file_id": "lesson-audio/0fb700bc61554dab49c8d9f13bdc2e5049d4331094d520cc8dfd9fe66d6660d0.mp3", "duration_ms": 22240}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/0fa05cb8f7fdde26469a492e28a30079584c1eb776c63097b99677dff8fd1968.mp3", "hash": "2f0e2862b7c32f154c57f8a981b41b07be1dbc3287fead35895540f79e209a7f", "bytes": 41616, "voice": "Ryan", "file_id": "lesson-audio/0fa05cb8f7fdde26469a492e28a30079584c1eb776c63097b99677dff8fd1968.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "yes-no-cases", "title": "Buy or save?", "locale": "en-US", "subject": "money", "objectives": ["Deciding whether to buy a toy or save coins, applying a responsible spending rule."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": [], "title": "Buy or save?", "payload": {"cases": [{"id": "caso1", "text_md": "**Yes**, buy the car (8 coins) and save the remaining 2 coins."}, {"id": "caso2", "text_md": "**No**, buy the car and also an ice cream for 3 coins, spending 11 coins."}, {"id": "caso3", "text_md": "**Yes**, buy nothing and save all 10 coins for the ball."}], "rule_md": "Only spend if you have enough left to save at least half of what you have."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho has 10 coins. He wants to buy a toy car that costs 8 coins, but he also wants to save for a ball that costs 12 coins. Help Rho decide if each option is a good choice according to the rule: **Only spend if you have enough left to save at least half of what you have**.", "difficulty": 1, "explanation_md": "Great job! Rho learned to think before spending. If you spend too much, you won''t have anything left to save.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["caso1", "caso3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce24a70cdd0ca36017f2d741bc49f26516a9d50c9e371554fb8fbd1fb9edf168.mp3", "hash": "7f68d1bf21535bccc4c56b9f41f0e78a0db45afa869161876f965b768e69c28c", "bytes": 90144, "voice": "Jennifer", "file_id": "lesson-audio/ce24a70cdd0ca36017f2d741bc49f26516a9d50c9e371554fb8fbd1fb9edf168.mp3", "duration_ms": 14960}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/0ea04116370f1492e44ac2d16b36526a8f3c13dedf9fdff56f77d8856b609b68.mp3", "hash": "e4d6fc9e449b2cf1d33ac40ce5fafa103ef1c1c45194f6467cdb31fd77aa3581", "bytes": 35424, "voice": "Jennifer", "file_id": "lesson-audio/0ea04116370f1492e44ac2d16b36526a8f3c13dedf9fdff56f77d8856b609b68.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "match-pairs", "title": "Emparejando elementos", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''match_pairs'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "hints": ["Fíjate bien: el calcetín rojo va con el calcetín rojo, la manzana con la canasta de frutas, y los lápices con el estuche.", "¿No estás seguro? Intenta con el calcetín rojo primero: debe ir con el otro calcetín rojo."], "title": "Emparejando elementos", "payload": {"left": [{"id": "l1", "text_md": "**Calcetín rojo**"}, {"id": "l2", "text_md": "**Manzana**"}, {"id": "l3", "text_md": "**Lápices**"}], "right": [{"id": "r1", "text_md": "Calcetín rojo"}, {"id": "r2", "text_md": "Canasta de frutas"}, {"id": "r3", "text_md": "Estuche"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "¡Hola! Zara está ordenando su cuarto. Recuerda que la última vez aprendiste a agrupar objetos similares. Ahora, Zara tiene calcetines rojos, una manzana y un grupo de lápices. Ayúdala a emparejar cada cosa de la izquierda con su lugar correcto de la derecha. Arrastra o selecciona la conexión correcta. Si te equivocas, te daré una pista especial.", "difficulty": 1, "explanation_md": "¡Muy bien! Zara emparejó cada cosa con su lugar: el calcetín rojo con el calcetín rojo, la manzana con la canasta de frutas, y los lápices con el estuche. ¡Todo en orden!", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/0601b7f3afc2b0551916715c1dd27fa36ad7e6ce82a8cc408ab7ae15e31f9a67.mp3", "hash": "e6baa381a6449b752a5192bce103fa4da3f96e81bfb996f86f5947b1a6e846e9", "bytes": 133776, "voice": "Li", "file_id": "lesson-audio/0601b7f3afc2b0551916715c1dd27fa36ad7e6ce82a8cc408ab7ae15e31f9a67.mp3", "duration_ms": 22240}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/0e44695e33a3a0b7e6a04420f5d2fe93189fde22a9c57220f2a3604929e480d8.mp3", "hash": "f9eef1fb1581136379bdca53de466bbb4d1beb1209355cbf372d0583993b2c70", "bytes": 77184, "voice": "Li", "file_id": "lesson-audio/0e44695e33a3a0b7e6a04420f5d2fe93189fde22a9c57220f2a3604929e480d8.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "match-pairs", "title": "Emparelhando elementos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''match_pairs'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "hints": ["Preste atenção: a meia vermelha vai com a meia vermelha, a maçã com a cesta de frutas, e os lápis com o estojo.", "Não tem certeza? Tente com a meia vermelha primeiro: ela deve ir com a outra meia vermelha."], "title": "Emparelhando elementos", "payload": {"left": [{"id": "l1", "text_md": "**Meia vermelha**"}, {"id": "l2", "text_md": "**Maçã**"}, {"id": "l3", "text_md": "**Lápis**"}], "right": [{"id": "r1", "text_md": "Meia vermelha"}, {"id": "r2", "text_md": "Cesta de frutas"}, {"id": "r3", "text_md": "Estojo"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Olá! A Zara está arrumando o quarto dela. Lembra que da última vez você aprendeu a agrupar objetos parecidos? Agora, a Zara tem meias vermelhas, uma maçã e um grupo de lápis. Ajude ela a emparelhar cada coisa da esquerda com o lugar certo da direita. Arraste ou selecione a conexão correta. Se você errar, vou te dar uma dica especial.", "difficulty": 1, "explanation_md": "Muito bem! A Zara emparelhou cada coisa com seu lugar: a meia vermelha com a meia vermelha, a maçã com a cesta de frutas, e os lápis com o estojo. Tudo em ordem!", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/e1854ee39910a9b824658551f05f6baaa00ed1d901f6ae484c4cd46b057e6a6a.mp3", "hash": "8aacae9fc7e01051f8acaf12d78cf42463dd6dedc8201a45bf0367f7950b3bdd", "bytes": 124704, "voice": "Ryan", "file_id": "lesson-audio/e1854ee39910a9b824658551f05f6baaa00ed1d901f6ae484c4cd46b057e6a6a.mp3", "duration_ms": 20720}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/c451070d743397fd7aa0355047d07df3a8c45ff160fcf6a87eb85fc80b0ed947.mp3", "hash": "91662e4f2e8ac1575c0374042ed86a0e0f7a79ed11cfbfb040a7370c1062bcd5", "bytes": 77184, "voice": "Ryan", "file_id": "lesson-audio/c451070d743397fd7aa0355047d07df3a8c45ff160fcf6a87eb85fc80b0ed947.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "budget-fit", "title": "Rho''s Shopping Cart", "locale": "en-US", "subject": "mixed", "objectives": ["Check the budget_fit exercise in isolation", "Confirm that each type in the money family is generated and rendered correctly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Add up the prices of the items you choose and make sure they don''t go over 100 MXN."], "title": "Rho''s Shopping Cart", "payload": {"items": [{"id": "item-toy", "icon": "toy", "need": false, "label": "Small toy", "price": 80}, {"id": "item-snack", "icon": "snack", "need": false, "label": "Treat", "price": 15}, {"id": "item-book", "icon": "book", "need": false, "label": "Storybook", "price": 25}, {"id": "item-pencil", "icon": "pencil", "need": true, "label": "Pencil", "price": 5}], "budget": 100, "currency": "MXN", "must_buy_needs": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho wants to put together a shopping cart without going over their budget of **100 MXN**. Help them choose items that add up to **100 MXN** or less.", "difficulty": 1, "explanation_md": "Great job! Rho was able to buy everything they needed without going over 100 MXN. Well done!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/e9a19ce7003701d0d0ad0c545d5b9f05aa53826aabcbb64c67f0b5339eb27dcb.mp3", "hash": "317d0ad1b40868d7877c5a634cd6dc2d81291b40065302643e45033fa6902f3f", "bytes": 52128, "voice": "Jennifer", "file_id": "lesson-audio/e9a19ce7003701d0d0ad0c545d5b9f05aa53826aabcbb64c67f0b5339eb27dcb.mp3", "duration_ms": 8640}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/13dc69a71cf9b7d4ff13eb73089890ffdfad0c6ca32357f36d981d2a24a4325b.mp3", "hash": "3908fb201d0e916c39a96b5fc335cd2205a97976e3157a17849d417c0a8b76bf", "bytes": 42624, "voice": "Jennifer", "file_id": "lesson-audio/13dc69a71cf9b7d4ff13eb73089890ffdfad0c6ca32357f36d981d2a24a4325b.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', E'{"meta": {"cast": ["dina", "zara"], "slug": "group-sets", "title": "Agrupando elementos con Zara", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio group_sets de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 5, "type": "group_sets", "hints": ["Observa bien las etiquetas de cada zona.", "Piensa a qué grupo pertenece cada objeto."], "title": "Agrupando elementos con Zara", "payload": {"items": [{"id": "item1", "text_md": "Manzana"}, {"id": "item2", "text_md": "Plátano"}, {"id": "item3", "text_md": "Naranja"}, {"id": "item4", "text_md": "Zanahoria"}, {"id": "item5", "text_md": "Brócoli"}], "set_a": "Zona A (Frutas)", "set_b": "Zona B (Verduras)"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Recuerdas que la vez pasada agruparon juguetes por color y tamaño? ¡Hoy Dina y Zara agrupan alimentos! Zara ha separado algunos objetos en dos zonas: la zona A (frutas) y la zona B (verduras). Ayuda a Zara a decidir en qué zona va cada objeto. Arrastra cada elemento a la zona correcta.\\n\\nPor ejemplo, la manzana es una fruta, así que va en la zona A. Piensa: ¿el plátano es fruta o verdura? ¿la zanahoria? ¡Tú puedes!", "difficulty": 1, "explanation_md": "¡Muy bien! Zara colocó 3 objetos en la zona A (frutas) y 2 en la zona B (verduras). La manzana, el plátano y la naranja son frutas, por eso van en A. La zanahoria y el brócoli son verduras, por eso van en B. ¡Excelente trabajo!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/986e9c38334badbcee281cc41fe01e0ca6c0aac2ce0e3e91ffdbd8a971050bf1.mp3", "hash": "d32122b6d41b3213b8d2928d9cbde8cf9233de9d6f5dadf56a8a9df4db072bb6", "bytes": 200016, "voice": "Li", "file_id": "lesson-audio/986e9c38334badbcee281cc41fe01e0ca6c0aac2ce0e3e91ffdbd8a971050bf1.mp3", "duration_ms": 33280}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/c1559b596621abc459f639d3014793787dc449d1c0d39183fd06364b08680034.mp3", "hash": "721daa35fd93ae2a33f8400c39ac05bbda66f0219543df35eaf2007506fd824a", "bytes": 103536, "voice": "Li", "file_id": "lesson-audio/c1559b596621abc459f639d3014793787dc449d1c0d39183fd06364b08680034.mp3", "duration_ms": 17200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "zara"], "slug": "group-sets", "title": "Agrupando elementos com Zara", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício group_sets de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 5, "type": "group_sets", "hints": ["Observe bem as etiquetas de cada zona.", "Pense a qual grupo pertence cada objeto."], "title": "Agrupando elementos com Zara", "payload": {"items": [{"id": "item1", "text_md": "Maçã"}, {"id": "item2", "text_md": "Banana"}, {"id": "item3", "text_md": "Laranja"}, {"id": "item4", "text_md": "Cenoura"}, {"id": "item5", "text_md": "Brócolis"}], "set_a": "Zona A (Frutas)", "set_b": "Zona B (Verduras)"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Lembra que da outra vez vocês agruparam brinquedos por cor e tamanho? Hoje Dina e Zara agrupam alimentos! Zara separou alguns objetos em duas zonas: a zona A (frutas) e a zona B (verduras). Ajude Zara a decidir em qual zona vai cada objeto. Arraste cada elemento para a zona correta.\\n\\nPor exemplo, a maçã é uma fruta, então vai na zona A. Pense: a banana é fruta ou verdura? E a cenoura? Você consegue!", "difficulty": 1, "explanation_md": "Muito bem! Zara colocou 3 objetos na zona A (frutas) e 2 na zona B (verduras). A maçã, a banana e a laranja são frutas, por isso vão em A. A cenoura e o brócolis são verduras, por isso vão em B. Excelente trabalho!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/5973c03881e96dde293170b593976d7287bb12c77539f04f85bc67f5dd76b133.mp3", "hash": "f98d4b57374bfcd41d355d82e5fead3e18ba805836f2868bcf1a994fa7680188", "bytes": 178848, "voice": "Ryan", "file_id": "lesson-audio/5973c03881e96dde293170b593976d7287bb12c77539f04f85bc67f5dd76b133.mp3", "duration_ms": 29760}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/6a52f661f32ab53b33b63be42e916f17c870ffb4cfc7fe7d19fc5071cd82f658.mp3", "hash": "fab4d3821b6b98e6067ae1bcc7eac354c75c90daff8b46cc3cb42b41fe457758", "bytes": 97776, "voice": "Ryan", "file_id": "lesson-audio/6a52f661f32ab53b33b63be42e916f17c870ffb4cfc7fe7d19fc5071cd82f658.mp3", "duration_ms": 16240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', E'{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Facts and Opinions with Dina", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''fact_opinion'' exercise in isolation.", "Distinguish between facts and opinions in everyday sentences."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 5, "type": "fact_opinion", "hints": ["A fact can be verified with data or evidence. For example: ''Water boils at 100°C''.", "An opinion expresses a feeling or preference, like ''Pizza is the best food''."], "title": "Facts and Opinions", "payload": {"statements": [{"id": "s1-st1", "text_md": "The sun rises in the east."}, {"id": "s1-st2", "text_md": "Classical music is the most beautiful."}, {"id": "s1-st3", "text_md": "The year has 365 days."}, {"id": "s1-st4", "text_md": "Chocolate is delicious."}, {"id": "s1-st5", "text_md": "Water is made of hydrogen and oxygen."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Do you remember yesterday when we talked about truth? Today Dina is helping her teacher organize a debate in the classroom. She needs to separate statements that are verifiable facts from those that are personal opinions. First, look at these real-life examples: ''Water boils at 100°C'' is a fact; ''Chocolate ice cream is the best'' is an opinion. Now, help Dina identify which of the following sentences are **facts** (things that can be proven) and which are **opinions** (personal beliefs).\\n\\nRead each sentence and select the ones that are **facts**.", "difficulty": 1, "explanation_md": "Great job! Dina separated 3 facts from 2 opinions. Remember: facts are based on evidence, opinions on feelings.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1-st1", "s1-st3", "s1-st5"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/ee11fda33bd517f3f7b10539e4fc8f9fc4f3d00a3c9197195d0f8178e657a888.mp3", "hash": "03a0cbba16a4e976f92d7180d1174c197fae97a2ceebdadcc74f797ae396f518", "bytes": 213984, "voice": "Jennifer", "file_id": "lesson-audio/ee11fda33bd517f3f7b10539e4fc8f9fc4f3d00a3c9197195d0f8178e657a888.mp3", "duration_ms": 35600}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a58d8f2b38df72f130eb6d79400b276b0712dca4bb63f105207bc77c53ca432.mp3", "hash": "bddbff016e5c64351323b7812e4b6d700fb38c024ff4a8fc4d1a6db62a905c15", "bytes": 43056, "voice": "Jennifer", "file_id": "lesson-audio/0a58d8f2b38df72f130eb6d79400b276b0712dca4bb63f105207bc77c53ca432.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', E'{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Fatos e Opiniões com Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''fact_opinion'' de forma isolada.", "Distinguir entre fatos e opiniões em frases cotidianas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 5, "type": "fact_opinion", "hints": ["Um fato pode ser verificado com dados ou evidências. Por exemplo: ''A água ferve a 100°C''.", "Uma opinião expressa um sentimento ou preferência, como ''Pizza é a melhor comida''."], "title": "Fatos e Opiniões", "payload": {"statements": [{"id": "s1-st1", "text_md": "O sol nasce no leste."}, {"id": "s1-st2", "text_md": "Música clássica é a mais bonita."}, {"id": "s1-st3", "text_md": "O ano tem 365 dias."}, {"id": "s1-st4", "text_md": "Chocolate é delicioso."}, {"id": "s1-st5", "text_md": "A água é composta por hidrogênio e oxigênio."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Você se lembra de ontem quando falamos sobre a verdade? Hoje a Dina está ajudando seu professor a organizar um debate na sala. Ela precisa separar as afirmações que são fatos comprováveis das que são opiniões pessoais. Primeiro, observe estes exemplos da vida real: ''A água ferve a 100°C'' é um fato; ''Sorvete de chocolate é o melhor'' é uma opinião. Agora, ajude a Dina a identificar quais das seguintes frases são **fatos** (coisas que podem ser comprovadas) e quais são **opiniões** (crenças pessoais).\\n\\nLeia cada frase e selecione as que são **fatos**.", "difficulty": 1, "explanation_md": "Muito bem! Dina separou 3 fatos de 2 opiniões. Lembre-se: fatos são baseados em evidências, opiniões em sentimentos.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1-st1", "s1-st3", "s1-st5"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/2e2a6df07aa0130c4c3c8cb49ced3ef7f2d5a69e68c8731d16a859bd67bc8010.mp3", "hash": "18c57fa6d2342def45c0333a4bdc128a09c3335891c30a01a1f3a7f25e655b5f", "bytes": 219168, "voice": "Ryan", "file_id": "lesson-audio/2e2a6df07aa0130c4c3c8cb49ced3ef7f2d5a69e68c8731d16a859bd67bc8010.mp3", "duration_ms": 36480}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/999591153a5630c52c17ef77c47dc8457c5ef9b0483da478208773fef033c321.mp3", "hash": "60875d1a18d36b025bb9b753cec170bf25e6f89f86c5dae6f2aeb7045a6b5c79", "bytes": 48384, "voice": "Ryan", "file_id": "lesson-audio/999591153a5630c52c17ef77c47dc8457c5ef9b0483da478208773fef033c321.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "would-you-rather", "title": "¿Qué prefieres? ¡Elige tu aventura!", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''would_you_rather'' de forma aislada", "Confirmar que el tipo ''would_you_rather'' se genera y renderiza correctamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Piensa en lo que más le gusta a Liruf: ¿aventura o tranquilidad?"], "title": "¿Qué prefieres?", "payload": {"a": {"icon": "cave", "text_md": "Explorar una cueva misteriosa y ganar 10 monedas"}, "b": {"icon": "book", "text_md": "Leer un libro bajo un árbol y ganar 5 monedas"}, "followup_md": "¡Genial! Ahora veremos qué sucede con cada elección."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf acaba de terminar el ejercicio ''lightning_round'', donde practicó tomar decisiones rápidas. ¡Ahora vamos a comparar opciones y pensar en cómo gastar o ahorrar monedas! Ayuda a Liruf a elegir entre dos opciones y descubre qué pasa con cada una.", "difficulty": 1, "explanation_md": "¡Liruf eligió la opción A y ganó 10 monedas de experiencia! Recuerda: a veces elegir la opción que da más monedas puede ayudarte a ahorrar para algo especial.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 10, "b": 5}, "reveal_md": "**Opción A: Explorar la cueva** — Liruf encuentra un cofre con 10 monedas de experiencia. **Opción B: Leer un libro** — Liruf aprende un dato curioso y gana 5 monedas. ¡Ambas son buenas, pero la aventura da más monedas para ahorrar!"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/85539ff2f6bc59dcb5a32458b392135d0ede2b8c6846b0d272dfee77ad57b42b.mp3", "hash": "a6a66fb5a267a38cdbc4d1c7cce7c19a2467b60a9e1ccd228b5f834d5af2ab22", "bytes": 89136, "voice": "Li", "file_id": "lesson-audio/85539ff2f6bc59dcb5a32458b392135d0ede2b8c6846b0d272dfee77ad57b42b.mp3", "duration_ms": 14800}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/10f225ffc00d3c09921efdb9b8d2557ca20d77a2b45e3bc3515438ce53d8e57a.mp3", "hash": "b97e37c319f5533b9beeae444c0495cd6c793ebf2f2ddbc126bbed2e5982acdb", "bytes": 80928, "voice": "Li", "file_id": "lesson-audio/10f225ffc00d3c09921efdb9b8d2557ca20d77a2b45e3bc3515438ce53d8e57a.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "would-you-rather", "title": "What do you prefer? Choose your adventure!", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''would_you_rather'' exercise in isolation", "Confirm that the ''would_you_rather'' type is generated and rendered correctly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Think about what Liruf likes most: adventure or relaxation?"], "title": "What do you prefer?", "payload": {"a": {"icon": "cave", "text_md": "Explore a mysterious cave and earn 10 coins"}, "b": {"icon": "book", "text_md": "Read a book under a tree and earn 5 coins"}, "followup_md": "Great! Now let''s see what happens with each choice."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf just finished the ''lightning_round'' exercise, where they practiced making quick decisions. Now let''s compare options and think about how to spend or save coins! Help Liruf choose between two options and discover what happens with each.", "difficulty": 1, "explanation_md": "Liruf chose option A and earned 10 experience coins! Remember: sometimes choosing the option that gives more coins can help you save for something special.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 10, "b": 5}, "reveal_md": "**Opción A: Explorar la cueva** — Liruf encuentra un cofre con 10 monedas de experiencia. **Opción B: Leer un libro** — Liruf aprende un dato curioso y gana 5 monedas. ¡Ambas son buenas, pero la aventura da más monedas para ahorrar!"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/8fd6f3e5be3e04224fbc37aeb3b07f1dd1c7b0605e34b45f19e3de12acec819d.mp3", "hash": "b3dd7e542d2c9560dbbcbaf08d93ecec067f16a4109e3593c1cb07fd84ed21a8", "bytes": 78624, "voice": "Jennifer", "file_id": "lesson-audio/8fd6f3e5be3e04224fbc37aeb3b07f1dd1c7b0605e34b45f19e3de12acec819d.mp3", "duration_ms": 13040}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c3a4e9905f59eb8414d2385e0ca2e2c1a8d8a16700ca7ab2912b5db1a1d6fb2.mp3", "hash": "46901dbe6a72bd5add01a351b625606d82488636db7e9813bcf07662874f93bb", "bytes": 58896, "voice": "Jennifer", "file_id": "lesson-audio/0c3a4e9905f59eb8414d2385e0ca2e2c1a8d8a16700ca7ab2912b5db1a1d6fb2.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "would-you-rather", "title": "O que você prefere? Escolha sua aventura!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''would_you_rather'' de forma isolada", "Confirmar que o tipo ''would_you_rather'' é gerado e renderizado corretamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Pense no que Liruf mais gosta: aventura ou tranquilidade?"], "title": "O que você prefere?", "payload": {"a": {"icon": "cave", "text_md": "Explorar uma caverna misteriosa e ganhar 10 moedas"}, "b": {"icon": "book", "text_md": "Ler um livro debaixo de uma árvore e ganhar 5 moedas"}, "followup_md": "Legal! Agora vamos ver o que acontece com cada escolha."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf acabou de terminar o exercício ''lightning_round'', onde praticou tomar decisões rápidas. Agora vamos comparar opções e pensar em como gastar ou economizar moedas! Ajude Liruf a escolher entre duas opções e descubra o que acontece com cada uma.", "difficulty": 1, "explanation_md": "Liruf escolheu a opção A e ganhou 10 moedas de experiência! Lembre-se: às vezes escolher a opção que dá mais moedas pode ajudar você a economizar para algo especial.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 10, "b": 5}, "reveal_md": "**Opción A: Explorar la cueva** — Liruf encuentra un cofre con 10 monedas de experiencia. **Opción B: Leer un libro** — Liruf aprende un dato curioso y gana 5 monedas. ¡Ambas son buenas, pero la aventura da más monedas para ahorrar!"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/9d84d3a874447382184851338dbaff4b21308e458de7ad9a36b848f93cd7a6a5.mp3", "hash": "7148b7a15dca0fe70724d2b97f4fe3e6f54c8db85a875c714c304a4159bf5e04", "bytes": 105408, "voice": "Ryan", "file_id": "lesson-audio/9d84d3a874447382184851338dbaff4b21308e458de7ad9a36b848f93cd7a6a5.mp3", "duration_ms": 17520}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/8291b94b86787753f1742e7c9d1f692d420204c147dfaf6f1135a4bd753ebe99.mp3", "hash": "0c3697e8c3d81e46833a83b6faa3f86957c9dd0a76ea5a52a65d72fb9145f668", "bytes": 68544, "voice": "Ryan", "file_id": "lesson-audio/8291b94b86787753f1742e7c9d1f692d420204c147dfaf6f1135a4bd753ebe99.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "lightning-round", "title": "¡Juguemos un rapidito!", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''lightning_round'' de forma aislada (flujo cronometrado)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 0, "type": "lightning_round", "hints": [], "title": "¡Juguemos un rapidito!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "Identificar la necesidad (¿realmente necesita las calcomanías?)"}, {"id": "q1-b", "text_md": "Gastar dinero de inmediato"}, {"id": "q1-c", "text_md": "Pedir prestado a un amigo"}], "prompt_md": "Dina quiere decidir si comprar calcomanías o ahorrar. ¿Cuál es el primer paso para tomar una decisión financiera?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Seleccionar una opción entre varias (como escoger entre juguete o ahorro)"}, {"id": "q2-b", "text_md": "Ahorrar todo el dinero sin gastar nada"}, {"id": "q2-c", "text_md": "Gastar en lo primero que veas"}], "prompt_md": "Cuando Dina piensa entre calcomanías y el libro, está ''eligiendo''. ¿Qué significa ''elegir''?"}, {"id": "q3", "options": [{"id": "q3-a", "text_md": "Evaluar el resultado (¿está contenta con su decisión?)"}, {"id": "q3-b", "text_md": "Olvidar la decisión y no pensar más"}, {"id": "q3-c", "text_md": "Repetir la misma elección siempre sin pensar"}], "prompt_md": "Dina eligió ahorrar para el libro. ¿Qué debe hacer después de elegir?"}], "seconds_per_q": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda que en la lección pasada Dina quería comprar un helado pero decidió ahorrar para una patineta. Ahora tiene $5 y quiere comprar calcomanías, pero también está ahorrando para un libro. ¿Qué debería hacer? ¡Ayúdala a decidir en esta ronda rápida! Responde cada pregunta en menos de 10 segundos.", "difficulty": 1, "explanation_md": "¡Muy bien! Dina aprendió que antes de gastar, hay que pensar si realmente lo necesitas. Por ejemplo, si tienes $5, puedes elegir entre comprar un juguete hoy o ahorrar para algo más grande mañana.", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1-a", "q2": "q2-a", "q3": "q3-a"}}}', '{"units": {"s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/bb4b55a35ccb78eacb27705c3a3b713e8ff19c5b3dadd650955273365d8cf1c4.mp3", "hash": "8c1a7f40434585b305236b3bfc0f38313ad9e58ad9d727c9df9d5ee35d7a03a6", "bytes": 112608, "voice": "Li", "file_id": "lesson-audio/bb4b55a35ccb78eacb27705c3a3b713e8ff19c5b3dadd650955273365d8cf1c4.mp3", "duration_ms": 18720}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/a52bafa674dd98a9688a3007b9d074861e0b19cf53964ade5389a13fbbc17135.mp3", "hash": "28e3c9aaf5ab11abea71e393e679de3016595589f59bc3a0116995cbd181309e", "bytes": 69984, "voice": "Li", "file_id": "lesson-audio/a52bafa674dd98a9688a3007b9d074861e0b19cf53964ade5389a13fbbc17135.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "lightning-round", "title": "Let''s play a quick game!", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''lightning_round'' exercise in isolation (timed flow)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 0, "type": "lightning_round", "hints": [], "title": "Let''s play a quick game!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "Identify the need (does she really need the stickers?)"}, {"id": "q1-b", "text_md": "Spend money right away"}, {"id": "q1-c", "text_md": "Borrow from a friend"}], "prompt_md": "Dina wants to decide whether to buy stickers or save. What is the first step in making a financial decision?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Selecting one option among several (like picking between a toy or saving)"}, {"id": "q2-b", "text_md": "Save all the money without spending any"}, {"id": "q2-c", "text_md": "Spend on the first thing you see"}], "prompt_md": "When Dina thinks between stickers and the book, she is ''choosing''. What does ''choosing'' mean?"}, {"id": "q3", "options": [{"id": "q3-a", "text_md": "Evaluate the result (is she happy with her decision?)"}, {"id": "q3-b", "text_md": "Forget the decision and not think about it anymore"}, {"id": "q3-c", "text_md": "Always repeat the same choice without thinking"}], "prompt_md": "Dina chose to save for the book. What should she do after choosing?"}], "seconds_per_q": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember, in the last lesson Dina wanted to buy an ice cream but decided to save for a skateboard. Now she has $5 and wants to buy stickers, but she''s also saving for a book. What should she do? Help her decide in this quick round! Answer each question in less than 10 seconds.", "difficulty": 1, "explanation_md": "Great job! Dina learned that before spending, you need to think about whether you really need it. For example, if you have $5, you can choose between buying a toy today or saving for something bigger tomorrow.", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1-a", "q2": "q2-a", "q3": "q3-a"}}}', '{"units": {"s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/5649cbcdae4e6b29762d49f724001778a9b5ebdc5474d27ee44e235e6afe7b24.mp3", "hash": "c0b11d5cbc5ade7aaea0a4054b55dcd32b489c55ac65c8bf1911309dd4fe9a91", "bytes": 99216, "voice": "Jennifer", "file_id": "lesson-audio/5649cbcdae4e6b29762d49f724001778a9b5ebdc5474d27ee44e235e6afe7b24.mp3", "duration_ms": 16480}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/1fd96f838a9ff6035e3b8ab078f4f1e7605ec6f738225dd03585cb66f0b6d805.mp3", "hash": "94af00c6bc2cf09264c92dd74204f4aa44047508b1dedab6c740c6e372cf2c4d", "bytes": 62784, "voice": "Jennifer", "file_id": "lesson-audio/1fd96f838a9ff6035e3b8ab078f4f1e7605ec6f738225dd03585cb66f0b6d805.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "lightning-round", "title": "Vamos jogar um rapidinho!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''lightning_round'' de forma isolada (fluxo cronometrado)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 0, "type": "lightning_round", "hints": [], "title": "Vamos jogar um rapidinho!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1-a", "text_md": "Identificar a necessidade (ela realmente precisa dos adesivos?)"}, {"id": "q1-b", "text_md": "Gastar dinheiro imediatamente"}, {"id": "q1-c", "text_md": "Pedir emprestado a um amigo"}], "prompt_md": "A Dina quer decidir se compra adesivos ou poupa. Qual é o primeiro passo para tomar uma decisão financeira?"}, {"id": "q2", "options": [{"id": "q2-a", "text_md": "Selecionar uma opção entre várias (como escolher entre brinquedo ou poupança)"}, {"id": "q2-b", "text_md": "Poupar todo o dinheiro sem gastar nada"}, {"id": "q2-c", "text_md": "Gastar na primeira coisa que você vê"}], "prompt_md": "Quando a Dina pensa entre adesivos e o livro, ela está ''escolhendo''. O que significa ''escolher''?"}, {"id": "q3", "options": [{"id": "q3-a", "text_md": "Avaliar o resultado (ela está feliz com a decisão?)"}, {"id": "q3-b", "text_md": "Esquecer a decisão e não pensar mais"}, {"id": "q3-c", "text_md": "Repetir a mesma escolha sempre sem pensar"}], "prompt_md": "A Dina escolheu poupar para o livro. O que ela deve fazer depois de escolher?"}], "seconds_per_q": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra que na lição passada a Dina queria comprar um sorvete, mas decidiu poupar para um skate. Agora ela tem $5 e quer comprar adesivos, mas também está poupando para um livro. O que ela deveria fazer? Ajude-a a decidir nesta rodada rápida! Responda cada pergunta em menos de 10 segundos.", "difficulty": 1, "explanation_md": "Muito bem! A Dina aprendeu que antes de gastar, é preciso pensar se você realmente precisa. Por exemplo, se você tem $5, pode escolher entre comprar um brinquedo hoje ou poupar para algo maior amanhã.", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1-a", "q2": "q2-a", "q3": "q3-a"}}}', '{"units": {"s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/f17e32156c8353176d7bebcc90e0708ea73cabe203da9f220e5a126ebd2a28cd.mp3", "hash": "3e7ecee24134275fb632ac2ccbe13d1a650d47330d14a81d54f308e2104cb757", "bytes": 114624, "voice": "Ryan", "file_id": "lesson-audio/f17e32156c8353176d7bebcc90e0708ea73cabe203da9f220e5a126ebd2a28cd.mp3", "duration_ms": 19040}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/d9d8bdf6d96f43afcce32e5f436b3940ec128ff8033d505791f050d614a4f72c.mp3", "hash": "39b2582b6d90ccd8e3c14f06d1ee74f0fafab9cd2090aeaa157f94fa80dcacf2", "bytes": 86688, "voice": "Ryan", "file_id": "lesson-audio/d9d8bdf6d96f43afcce32e5f436b3940ec128ff8033d505791f050d614a4f72c.mp3", "duration_ms": 14400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "confidence-quiz", "title": "Confianza en tus respuestas", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia choice se genera y renderiza correctamente.", "Verificar el ejercicio ''confidence_quiz'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 0, "type": "confidence_quiz", "hints": ["Piensa si Dina se siente muy segura, algo segura o nada segura de que le alcanzan las monedas."], "title": "¿Qué tan segura estás?", "payload": {"options": [{"id": "opt-muy-segura", "text_md": "Muy segura", "rationale_md": "Dina tiene 10 monedas y el juguete cuesta 8, así que le alcanza y le sobran 2."}, {"id": "opt-algo-segura", "text_md": "Algo segura", "rationale_md": "Dina no está completamente segura de cuántas monedas tiene o cuánto cuesta el juguete."}, {"id": "opt-nada-segura", "text_md": "Nada segura", "rationale_md": "Dina no ha contado sus monedas y no sabe si le alcanza."}]}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "En la lección anterior, Dina aprendió a contar monedas. Ahora tiene 10 monedas y quiere comprar un juguete que cuesta 8 monedas. Dina está segura de que le alcanza. ¿Qué tan segura está Dina de que puede comprar el juguete? Ayuda a Dina a elegir el nivel de confianza que mejor refleje cómo se siente. ¿Está muy segura, algo segura o nada segura?", "difficulty": 1, "explanation_md": "¡Correcto! Dina está muy segura porque tiene 10 monedas y el juguete cuesta 8, así que le sobran 2. Cuando cuentas bien tus monedas, puedes sentirte seguro/a de tu decisión.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-muy-segura"}}', '{"units": {"s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/f115da54c9eb23b56a46c6020417c48b664614baa37bc0c75065b4d07bd99981.mp3", "hash": "12931cf67f26c8a5de3306d2e8306a21bb545051db3940082f725fdb477ffb44", "bytes": 129888, "voice": "Li", "file_id": "lesson-audio/f115da54c9eb23b56a46c6020417c48b664614baa37bc0c75065b4d07bd99981.mp3", "duration_ms": 21600}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f377256235f2f38dbb8d6bbc4d4c82b3378f925a908b225b53be537c207412e.mp3", "hash": "d148b33f10ea58dd9354e44f1687cda0327b1159a411588104f2d06179ccd29e", "bytes": 79056, "voice": "Li", "file_id": "lesson-audio/3f377256235f2f38dbb8d6bbc4d4c82b3378f925a908b225b53be537c207412e.mp3", "duration_ms": 13120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "confidence-quiz", "title": "Confiança nas suas respostas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família choice é gerado e renderizado corretamente.", "Verificar o exercício ''confidence_quiz'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 0, "type": "confidence_quiz", "hints": ["Pense se Dina se sente muito segura, um pouco segura ou nada segura de que tem moedas suficientes."], "title": "Quão segura você está?", "payload": {"options": [{"id": "opt-muy-segura", "text_md": "Muito segura", "rationale_md": "Dina tem 10 moedas e o brinquedo custa 8, então ela tem o suficiente e sobram 2."}, {"id": "opt-algo-segura", "text_md": "Um pouco segura", "rationale_md": "Dina não está completamente segura de quantas moedas tem ou quanto custa o brinquedo."}, {"id": "opt-nada-segura", "text_md": "Nada segura", "rationale_md": "Dina não contou suas moedas e não sabe se tem o suficiente."}]}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Na lição anterior, Dina aprendeu a contar moedas. Agora ela tem 10 moedas e quer comprar um brinquedo que custa 8 moedas. Dina está segura de que tem o suficiente. Quão segura Dina está de que pode comprar o brinquedo? Ajude Dina a escolher o nível de confiança que melhor reflete como ela se sente. Ela está muito segura, um pouco segura ou nada segura?", "difficulty": 1, "explanation_md": "Correto! Dina está muito segura porque ela tem 10 moedas e o brinquedo custa 8, então sobram 2. Quando você conta bem suas moedas, pode se sentir seguro(a) da sua decisão.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-muy-segura"}}', '{"units": {"s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/f8fc018824d9b4aa1b228d6a83e396c13ac858dd4731054f548b815214e3d54e.mp3", "hash": "fc885cb51016b4064b293fc0fef547add6ff0623e9f29a66824a152ca442b0c7", "bytes": 134784, "voice": "Ryan", "file_id": "lesson-audio/f8fc018824d9b4aa1b228d6a83e396c13ac858dd4731054f548b815214e3d54e.mp3", "duration_ms": 22400}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/4f36546a6fc7311703161cee616963b67a9e7f35f3e41d4779a1e08408537faa.mp3", "hash": "ea250c2f5f3af1981eeb66770c6fe048dcf4988da78faa9ee57e54e98611856c", "bytes": 73296, "voice": "Ryan", "file_id": "lesson-audio/4f36546a6fc7311703161cee616963b67a9e7f35f3e41d4779a1e08408537faa.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "savings-goal", "title": "Savings goal: Zara''s toy", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate how many weeks it takes to save for a savings goal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 5, "type": "savings_goal", "hints": ["Divide the total cost by the weekly savings."], "title": "Zara''s toy", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [8]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara wants to buy a toy that costs **80 MXN**. She has 0 MXN saved so far. She plans to save a fixed amount each week. How many weeks will it take if she saves **8 MXN** per week?", "difficulty": 1, "explanation_md": "Zara needs 10 weeks because 80 ÷ 8 = 10.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"8": 10}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/eeb87a97c4494f36128f2934eb7c8a4dd91dc64e4cb0af5a50ceabca7586ef10.mp3", "hash": "96a5442aa32ce2ae51edc302dd436312e825ccc80a470651953d26614312a278", "bytes": 71424, "voice": "Jennifer", "file_id": "lesson-audio/eeb87a97c4494f36128f2934eb7c8a4dd91dc64e4cb0af5a50ceabca7586ef10.mp3", "duration_ms": 11840}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/a61b1fbb83d8d6d29baa9c17ff256c16ee7b129d612f1895101a5c76733c717a.mp3", "hash": "4295d9e76a76c0cc3f36f2b4651b41f6b617ab110b6ec4fe4274d24b114dfea0", "bytes": 25344, "voice": "Jennifer", "file_id": "lesson-audio/a61b1fbb83d8d6d29baa9c17ff256c16ee7b129d612f1895101a5c76733c717a.mp3", "duration_ms": 4160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "Un vistazo al interés", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''interest_peek'' de forma aislada (flujo de predicción)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["El primer mes, gana el 10% de 80, que son 8 MXN. Así que después de un mes tiene 88 MXN.", "El segundo mes, vuelve a ganar el 10% de los 80 MXN iniciales, que son otros 8 MXN."], "title": "Predice el ahorro de Liruf", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf guardó **80 MXN** en su alcancía. Cada mes, su dinero crece un **10%** (interés simple). ¿Cuánto tendrá después de **2 meses**?", "difficulty": 1, "explanation_md": "¡Correcto! Liruf tendrá **96 MXN** después de 2 meses. Cada mes gana 8 MXN (10% de 80), así que en total gana 16 MXN. ¡Su dinero crece!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce6b0ac1865a948d6b770e601a8996c1c6d9866e2817dadd091b75b513bbfa82.mp3", "hash": "6895d0c4e52d9e56d6b29af3e0a7472067a268c9cd86c0345b2e744912efb0f7", "bytes": 65664, "voice": "Li", "file_id": "lesson-audio/ce6b0ac1865a948d6b770e601a8996c1c6d9866e2817dadd091b75b513bbfa82.mp3", "duration_ms": 10880}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/6aa99801415a9e763b38303dc3187bf830a9cffe06db81321aebc9bf62965788.mp3", "hash": "c20efde8361d985390d79f7321ce6853e79ca675cf82e6b11fb6c9d84cf8dd50", "bytes": 76176, "voice": "Li", "file_id": "lesson-audio/6aa99801415a9e763b38303dc3187bf830a9cffe06db81321aebc9bf62965788.mp3", "duration_ms": 12640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "El camino del robot", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''robot_path'' de forma aislada (flujo de simulación)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 0, "type": "robot_path", "hints": ["Recuerda que el robot solo puede avanzar hacia adelante si no hay pared."], "title": "Programa el robot", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward"], "max_commands": 5}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Como aprendimos ayer con Zara y los pasos del robot, hoy Zara está ayudando a su robot amigo a encontrar un tesoro en una cuadrícula de 3x3. El robot empieza en la primera casilla de abajo a la izquierda, mirando hacia arriba. El tesoro está en la última casilla de arriba a la derecha. No hay paredes. ¿Qué instrucción debe ejecutar primero?", "difficulty": 1, "explanation_md": "¡Muy bien! Zara eligió ''forward'' para empezar. El robot avanza una casilla hacia arriba.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/2b627de195e40c5e6e6d7844b9c20be044cf755749c8f6a88f1abe0bbf9c444f.mp3", "hash": "a5f259a7ee87de75e8e9e21a0329373ee8aa105945fca6012da00c451e82b2e8", "bytes": 114048, "voice": "Li", "file_id": "lesson-audio/2b627de195e40c5e6e6d7844b9c20be044cf755749c8f6a88f1abe0bbf9c444f.mp3", "duration_ms": 18960}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/ad853490839dabb25be19fac7bc7cc70e915a8a19b6ad9fb6ae0248d77fb7892.mp3", "hash": "00dbac469c708063da7fc3ba778e8cefbf42e38d822bfc4f5ec69b470cf82236", "bytes": 31536, "voice": "Li", "file_id": "lesson-audio/ad853490839dabb25be19fac7bc7cc70e915a8a19b6ad9fb6ae0248d77fb7892.mp3", "duration_ms": 5200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "The robot''s path", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''robot_path'' exercise in isolation (simulation flow)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 0, "type": "robot_path", "hints": ["Remember that the robot can only move forward if there is no wall."], "title": "Program the robot", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward"], "max_commands": 5}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "As we learned yesterday with Zara and the robot steps, today Zara is helping her robot friend find a treasure on a 3x3 grid. The robot starts in the bottom-left square, facing up. The treasure is in the top-right square. There are no walls. What instruction should it execute first?", "difficulty": 1, "explanation_md": "Great job! Zara chose ''forward'' to start. The robot moves one square up.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/d90a2e0952fa01fb03a2d0f06c817de17a9c2cb312edb7478c5f5941fa5358ce.mp3", "hash": "e5bb19ce9babb8af0dc4d95f03124a8f99f44e31ae694004379186f91308ee5f", "bytes": 112176, "voice": "Jennifer", "file_id": "lesson-audio/d90a2e0952fa01fb03a2d0f06c817de17a9c2cb312edb7478c5f5941fa5358ce.mp3", "duration_ms": 18640}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/8d08728dad5dba0c8d8ae3450ceae22e3d561bdce72e8d606383934b3834aa0f.mp3", "hash": "3fd22362fe1b1671919b7deb917c7d02bfb546c4c245bb84f6f210f7d8f4bc6d", "bytes": 30096, "voice": "Jennifer", "file_id": "lesson-audio/8d08728dad5dba0c8d8ae3450ceae22e3d561bdce72e8d606383934b3834aa0f.mp3", "duration_ms": 4960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "combo-narrativa-choice", "title": "La secuencia de Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar que una narrativa seguida de una pregunta de opción múltiple fluya en secuencia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-historia", "xp": 0, "type": "story_scene", "hints": [], "title": "La historia de Dina", "payload": {"art": {"icon": "coin", "tint": "primary"}, "action": "idle", "body_md": "Dina encontró una moneda de 10 MXN en su bolsillo. Decidió guardarla en su alcancía para comprar un libro. Al día siguiente, su amigo Liruf le regaló otra moneda de 5 MXN. Ahora Dina tiene 15 MXN en su alcancía.", "emotion": "neutral", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina te contará una historia corta. Después, responderás una pregunta sobre ella.", "difficulty": 1, "explanation_md": "Dina usó una moneda de 10 MXN para empezar su ahorro.", "audio_segment_id": "s1-historia.prompt"}, {"id": "s2-pregunta", "xp": 10, "type": "quiz_mcq", "hints": ["Recuerda que Dina primero encontró 10 MXN y luego recibió 5 MXN."], "title": "¿Cuánto ahorró Dina?", "payload": {"options": [{"id": "a", "text_md": "10 MXN", "rationale_md": "Esa es solo la primera moneda, pero Dina también recibió otra de 5 MXN."}, {"id": "b", "text_md": "15 MXN", "rationale_md": "¡Correcto! 10 MXN + 5 MXN = 15 MXN."}, {"id": "c", "text_md": "5 MXN", "rationale_md": "Esa es solo la segunda moneda, pero Dina también encontró una de 10 MXN."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Cuánto dinero ahorró Dina en total después de recibir las dos monedas?", "difficulty": 1, "explanation_md": "Dina ahorró 15 MXN: 10 MXN + 5 MXN = 15 MXN.", "audio_segment_id": "s2-pregunta.prompt"}], "schema_version": 1}', '{"s2-pregunta": {"correct_option_id": "b"}}', '{"units": {"s1-historia.body": {"url": "http://localhost:4006/files/lesson-audio/870cea032e641f66513e180091eb6a946608ecc27aa4b1a9f48dd2d421fe324f.mp3", "hash": "888055db5f9e7342fe5437ac7722ce5c035a30646136fad6b8e361cf6a238202", "bytes": 104544, "voice": "Li", "file_id": "lesson-audio/870cea032e641f66513e180091eb6a946608ecc27aa4b1a9f48dd2d421fe324f.mp3", "duration_ms": 17360}, "s1-historia.prompt": {"url": "http://localhost:4006/files/lesson-audio/f08db020696b7d02bf69062b0e8459cdfafaaab769b9b31cc8f97f45e5217dc7.mp3", "hash": "4843550df9553ba71a4ea805e56a82e24bb240bc9262a4578510d51e988dea56", "bytes": 28656, "voice": "Li", "file_id": "lesson-audio/f08db020696b7d02bf69062b0e8459cdfafaaab769b9b31cc8f97f45e5217dc7.mp3", "duration_ms": 4720}, "s2-pregunta.prompt": {"url": "http://localhost:4006/files/lesson-audio/a33eec3714b0fb9f276de60cf561508456e46996e375a185b23bd4a175edb0c7.mp3", "hash": "fc98c77f302826d80019dee98c04ebc9b20de7651f0c494824010102d4fce840", "bytes": 23904, "voice": "Li", "file_id": "lesson-audio/a33eec3714b0fb9f276de60cf561508456e46996e375a185b23bd4a175edb0c7.mp3", "duration_ms": 3920}, "s1-historia.explanation": {"url": "http://localhost:4006/files/lesson-audio/ab56a69429680ef4bf82222590dc11fc982b16d17e4e69437ff4eea6060f2570.mp3", "hash": "5815f603ef1e1b5c4e65b8be34b3b01ae30d553f40d718222379b225c2a4b586", "bytes": 22896, "voice": "Li", "file_id": "lesson-audio/ab56a69429680ef4bf82222590dc11fc982b16d17e4e69437ff4eea6060f2570.mp3", "duration_ms": 3760}, "s2-pregunta.explanation": {"url": "http://localhost:4006/files/lesson-audio/22667f970e3308263c4827ccd5a4a29dd6260c14f64dc60100f96d9a987b5422.mp3", "hash": "a04d8c66afec779fefb33895da785de65575ebe9a70abc74f18656ba84abdcaf", "bytes": 48816, "voice": "Li", "file_id": "lesson-audio/22667f970e3308263c4827ccd5a4a29dd6260c14f64dc60100f96d9a987b5422.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "best-decision", "title": "La mejor decisión de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''best_decision'' de forma aislada.", "Confirmar que cada tipo de la familia choice se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["Piensa en lo que es más justo para todos.", "Imagina que tú perdiste la moneda, ¿qué te gustaría que hicieran?"], "title": "La decisión de Liruf", "payload": {"options": [{"id": "opt-devolver", "text_md": "Devolver la moneda a la oficina de objetos perdidos", "rationale_md": "Es la opción más honesta y justa."}, {"id": "opt-dulce", "text_md": "Comprar un dulce para compartir con Zara", "rationale_md": "Puede parecer generoso, pero la moneda no es de Liruf, así que no es correcto usarla sin permiso."}, {"id": "opt-guardar", "text_md": "Guardarla en su bolsillo y no decir nada", "rationale_md": "Es tentador porque nadie la vio, pero no es honesto quedarse con algo que no le pertenece."}], "scenario_md": "Liruf está en el parque jugando con su amiga Zara. De repente, ve una moneda de 10 pesos en el suelo. Nadie más la ha visto. Liruf piensa: ''¿Qué debo hacer?''"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda cuando aprendimos sobre honestidad. Liruf encontró una moneda de 10 pesos en el parque. ¿Qué debería hacer? Piensa paso a paso: ¿quién podría ser el dueño? ¿cómo se sentiría si perdiera algo? Elige la mejor opción.", "difficulty": 1, "explanation_md": "La mejor decisión es devolver la moneda, porque es lo honesto y justo. Comprar un dulce o guardarla no considera al dueño. Recuerda: ser honesto siempre es la mejor opción.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"egoísmo": 0, "honestidad": 10, "generosidad": 5}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/76d6c33abac8751718f69d7422938b8945fd3d4d28684d3410ea593d845c2d04.mp3", "hash": "ac66249254cee43088fca839d467e23ff5f6f05ab7ddcf95ff8ac0f263a44584", "bytes": 93456, "voice": "Li", "file_id": "lesson-audio/76d6c33abac8751718f69d7422938b8945fd3d4d28684d3410ea593d845c2d04.mp3", "duration_ms": 15520}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f3c078c7ffb2a448ec08bd50d569e70447eb4226f9669c0a02e6c8125eb1b7e.mp3", "hash": "6ff5c17ac0fa9225e45a90777e22980077e297e2ee5f61588bedeaaa9c78702f", "bytes": 70848, "voice": "Li", "file_id": "lesson-audio/7f3c078c7ffb2a448ec08bd50d569e70447eb4226f9669c0a02e6c8125eb1b7e.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "debug-hunt", "title": "Cacería de errores: depura el bloque", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''debug_hunt'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": ["Observa cada instrucción con atención, como cuando armas un juguete.", "Recuerda que las instrucciones deben ser claras para que el robot funcione."], "title": "Encuentra el error en el bloque", "payload": {"blocks": [{"id": "b1", "text_md": "Instrucción 1: construir un robot"}, {"id": "b2", "text_md": "Instrucción 2: medirr la distancia"}, {"id": "b3", "text_md": "Instrucción 3: programar el movimiento"}], "intro_md": "Dina revisa las instrucciones para armar un robot. Algo no está bien... ¡Hay un error! Ayúdala a encontrar la instrucción equivocada. ¡El robot no se mueve y Dina necesita entregarlo!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendiste ayer con Leo, los errores pequeños pueden detener todo. Dina está armando un robot y las instrucciones tienen un error. Ayúdale a encontrarlo y corregirlo.", "difficulty": 1, "explanation_md": "¡Excelente! Dina encontró el error en la instrucción 2: decía ''medirr'' en lugar de ''medir''. Al corregirlo, el robot puede moverse. ¡Buen trabajo!", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''medirr'' por ''medir'' en la instrucción 2.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/99154a01b8f57587e36eacaf0824be6fe79d980fde71a3381b21189164cee84c.mp3", "hash": "b33a7534bc8d5b5ee861df3b24a8663c8b6932a18499dc5a0fa9f54655002b68", "bytes": 69408, "voice": "Li", "file_id": "lesson-audio/99154a01b8f57587e36eacaf0824be6fe79d980fde71a3381b21189164cee84c.mp3", "duration_ms": 11520}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/43d75af5d162d908e9e87b5a7714cde12a83c635270f4ab4f7d7581b69596a54.mp3", "hash": "230e3773c06f0ab8b7bba39d2ff570957e36f24a288c7a6de4fd6f3e02659243", "bytes": 60768, "voice": "Li", "file_id": "lesson-audio/43d75af5d162d908e9e87b5a7714cde12a83c635270f4ab4f7d7581b69596a54.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "debug-hunt", "title": "Bug hunt: debug the block", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''debug_hunt'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": ["Look at each instruction carefully, like when you assemble a toy.", "Remember that instructions must be clear for the robot to work."], "title": "Find the error in the block", "payload": {"blocks": [{"id": "b1", "text_md": "Instruction 1: build a robot"}, {"id": "b2", "text_md": "Instruction 2: measurre the distance"}, {"id": "b3", "text_md": "Instruction 3: program the movement"}], "intro_md": "Dina reviews the instructions to build a robot. Something is not right... There''s a mistake! Help her find the wrong instruction. The robot won''t move and Dina needs to deliver it!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As you learned yesterday with Leo, small errors can stop everything. Dina is building a robot and the instructions have a mistake. Help her find and fix it.", "difficulty": 1, "explanation_md": "Excellent! Dina found the error in instruction 2: it said ''measurre'' instead of ''measure''. By fixing it, the robot can move. Great job!", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''medirr'' por ''medir'' en la instrucción 2.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/e5795e2afe936ec668e0588c0fd5cbdd627d4d85e6819615a930c5c6fddea7de.mp3", "hash": "49a33476cfb51795846d92657a3977aa7e44da711c28b6e0c0e58a9cb70569ac", "bytes": 46944, "voice": "Jennifer", "file_id": "lesson-audio/e5795e2afe936ec668e0588c0fd5cbdd627d4d85e6819615a930c5c6fddea7de.mp3", "duration_ms": 7760}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/0e50b170905a4a7aae20193a6f7e69eb4f940015f4480bae42200b231016da05.mp3", "hash": "25b01ac8b2825069ebb02e8ad86bd4fe617c1d4ccb26814733e83ac2e4f0411a", "bytes": 51264, "voice": "Jennifer", "file_id": "lesson-audio/0e50b170905a4a7aae20193a6f7e69eb4f940015f4480bae42200b231016da05.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "debug-hunt", "title": "Caça de erros: depure o bloco", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verifique o exercício ''debug_hunt'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": ["Observe cada instrução com atenção, como quando você monta um brinquedo.", "Lembre-se de que as instruções devem ser claras para o robô funcionar."], "title": "Encontre o erro no bloco", "payload": {"blocks": [{"id": "b1", "text_md": "Instrução 1: construir um robô"}, {"id": "b2", "text_md": "Instrução 2: medirr a distância"}, {"id": "b3", "text_md": "Instrução 3: programar o movimento"}], "intro_md": "Dina revisa as instruções para montar um robô. Algo não está certo... Há um erro! Ajude-a a encontrar a instrução errada. O robô não se move e Dina precisa entregá-lo!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como você aprendeu ontem com Leo, pequenos erros podem parar tudo. Dina está montando um robô e as instruções têm um erro. Ajude-a a encontrá-lo e corrigi-lo.", "difficulty": 1, "explanation_md": "Excelente! Dina encontrou o erro na instrução 2: dizia ''medirr'' em vez de ''medir''. Ao corrigi-lo, o robô pode se mover. Bom trabalho!", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''medirr'' por ''medir'' en la instrucción 2.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/6fc4bcc7b9a9be666a995b9298c12eb2ba8b44785f7298d97b0ca173d37e0e2f.mp3", "hash": "1b39f5be6db9ed0066ee5059a5301c10df876c663b061de9bf687bd1eaedeb90", "bytes": 68976, "voice": "Ryan", "file_id": "lesson-audio/6fc4bcc7b9a9be666a995b9298c12eb2ba8b44785f7298d97b0ca173d37e0e2f.mp3", "duration_ms": 11440}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/b9c70010a7c84f007d71876e92df61e95bbe91fc2e900db50348b8e0ef27358e.mp3", "hash": "11ee9bf802e7907d226564732c754c224a5a19de5f7fcacf5d5c45c3e5948df0", "bytes": 59904, "voice": "Ryan", "file_id": "lesson-audio/b9c70010a7c84f007d71876e92df61e95bbe91fc2e900db50348b8e0ef27358e.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "combo-narrativa-choice", "title": "A sequência de Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar que uma narrativa seguida de uma pergunta de múltipla escolha flua em sequência."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-historia", "xp": 0, "type": "story_scene", "hints": [], "title": "A história de Dina", "payload": {"art": {"icon": "coin", "tint": "primary"}, "action": "idle", "body_md": "Dina encontrou uma moeda de 10 MXN no bolso. Decidiu guardá-la no cofrinho para comprar um livro. No dia seguinte, seu amigo Liruf deu a ela outra moeda de 5 MXN. Agora Dina tem 15 MXN no cofrinho.", "emotion": "neutral", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vai te contar uma história curta. Depois, você responderá a uma pergunta sobre ela.", "difficulty": 1, "explanation_md": "Dina usou uma moeda de 10 MXN para começar sua poupança.", "audio_segment_id": "s1-historia.prompt"}, {"id": "s2-pregunta", "xp": 10, "type": "quiz_mcq", "hints": ["Lembre-se que Dina primeiro encontrou 10 MXN e depois recebeu 5 MXN."], "title": "Quanto Dina economizou?", "payload": {"options": [{"id": "a", "text_md": "10 MXN", "rationale_md": "Essa é apenas a primeira moeda, mas Dina também recebeu outra de 5 MXN."}, {"id": "b", "text_md": "15 MXN", "rationale_md": "Correto! 10 MXN + 5 MXN = 15 MXN."}, {"id": "c", "text_md": "5 MXN", "rationale_md": "Essa é apenas a segunda moeda, mas Dina também encontrou uma de 10 MXN."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Quanto dinheiro Dina economizou no total depois de receber as duas moedas?", "difficulty": 1, "explanation_md": "Dina economizou 15 MXN: 10 MXN + 5 MXN = 15 MXN.", "audio_segment_id": "s2-pregunta.prompt"}], "schema_version": 1}', '{"s2-pregunta": {"correct_option_id": "b"}}', '{"units": {"s1-historia.body": {"url": "http://localhost:4006/files/lesson-audio/48ea950d00d64d651de0d461aeed8a62591c7600c0261003f431f548c3644b17.mp3", "hash": "79dae5ea178ed70958f57c6fe2f338fc79e42bfdbd1402759b47904547af3203", "bytes": 93888, "voice": "Ryan", "file_id": "lesson-audio/48ea950d00d64d651de0d461aeed8a62591c7600c0261003f431f548c3644b17.mp3", "duration_ms": 15600}, "s1-historia.prompt": {"url": "http://localhost:4006/files/lesson-audio/6ef43d984725e311edf2deeec60adbdb71886bb0aa26f2c94f3a91e7d197dd19.mp3", "hash": "991070018a3e329042b4db6f3dc8774b47e329d56d6e9cda51a4cfe583c3de43", "bytes": 37296, "voice": "Ryan", "file_id": "lesson-audio/6ef43d984725e311edf2deeec60adbdb71886bb0aa26f2c94f3a91e7d197dd19.mp3", "duration_ms": 6160}, "s2-pregunta.prompt": {"url": "http://localhost:4006/files/lesson-audio/488acf944e138fa3a81e199344a11d65e433dc3d295d2c787f3e4f97ea06c047.mp3", "hash": "f447f2dc434af9d521473b92446cba3d5dfe2ebf0583bb8838272affe5ed1ff3", "bytes": 25344, "voice": "Ryan", "file_id": "lesson-audio/488acf944e138fa3a81e199344a11d65e433dc3d295d2c787f3e4f97ea06c047.mp3", "duration_ms": 4160}, "s1-historia.explanation": {"url": "http://localhost:4006/files/lesson-audio/e705b850d2e003d99b02344e5043e68cf1ce0718fe76f9be3cf7e231b2fa41fb.mp3", "hash": "cfaa3b937d4e7f8b178034e36147aaddd1945422d3615f7f60d9e4b377a29708", "bytes": 24336, "voice": "Ryan", "file_id": "lesson-audio/e705b850d2e003d99b02344e5043e68cf1ce0718fe76f9be3cf7e231b2fa41fb.mp3", "duration_ms": 4000}, "s2-pregunta.explanation": {"url": "http://localhost:4006/files/lesson-audio/87e61dff56002e124eb0b263061bb41ef26ad671aa51fdd9b5e0ac14890a8329.mp3", "hash": "92c806ac6452381064c6a261ffecf5cac827f1b7330c800fde656a1180895359", "bytes": 85824, "voice": "Ryan", "file_id": "lesson-audio/87e61dff56002e124eb0b263061bb41ef26ad671aa51fdd9b5e0ac14890a8329.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Repaso: Pregunta de opción múltiple", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar la diferencia entre ahorrar y gastar con ejemplos concretos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 8, "type": "quiz_mcq", "hints": ["Recuerda que ahorrar significa guardar dinero para usarlo después. Si Dina ya tiene $10, ¿cuánto le falta?", "Piensa en lo que aprendiste en la lección anterior sobre cómo ahorrar poco a poco."], "title": "Elige la opción correcta", "payload": {"options": [{"id": "opt-a", "text_md": "Gastar los $10 ahora en un dulce", "rationale_md": "Si gasta todo ahora, no tendrá dinero para el juguete. No es la mejor opción."}, {"id": "opt-b", "text_md": "Seguir ahorrando hasta tener $15", "rationale_md": "¡Exacto! Ahorrando más, podrá comprar el juguete. Esta es la opción correcta."}, {"id": "opt-c", "text_md": "Pedir prestado a un amigo y pagar después", "rationale_md": "Pedir prestado puede ser riesgoso y no es una forma de ahorro. Mejor es ahorrar."}, {"id": "opt-d", "text_md": "Comprar el juguete ahora y pagar después", "rationale_md": "No tiene suficiente dinero ahora, así que no puede comprarlo. Debe ahorrar primero."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina ahorró $10 de su mesada y quiere comprar un juguete que cuesta $15. ¿Qué debería hacer Dina para poder comprar el juguete?", "difficulty": 1, "explanation_md": "¡Correcto! Dina debe seguir ahorrando hasta juntar los $15. Gastar todo ahora no le permitiría comprar el juguete más caro.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "opt-b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/c35f4bce3b38f706bc7ddcce73090e97602d0ae59609858b3ab19efa8f2764e5.mp3", "hash": "036d66ec228035dafde5bd32b38fcd6bf2a3bf2e13d92810296e266376f2b500", "bytes": 39168, "voice": "Li", "file_id": "lesson-audio/c35f4bce3b38f706bc7ddcce73090e97602d0ae59609858b3ab19efa8f2764e5.mp3", "duration_ms": 6480}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/d3db6d56a33f64169809f72b4f540459bc2aa23adc68a7c4860126b42187b68d.mp3", "hash": "e5f4932ef8b29bcf2e670cf557b29ded07d0cda025d96bc38d12c02d8e1e2dcd", "bytes": 47808, "voice": "Li", "file_id": "lesson-audio/d3db6d56a33f64169809f72b4f540459bc2aa23adc68a7c4860126b42187b68d.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Review: Multiple Choice Question", "locale": "en-US", "subject": "mixed", "objectives": ["Review the difference between saving and spending with concrete examples."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 8, "type": "quiz_mcq", "hints": ["Remember that saving means keeping money to use later. If Dina already has $10, how much more does she need?", "Think about what you learned in the previous lesson about saving little by little."], "title": "Choose the correct option", "payload": {"options": [{"id": "opt-a", "text_md": "Spend the $10 now on a candy", "rationale_md": "If she spends everything now, she won''t have money for the toy. That''s not the best option."}, {"id": "opt-b", "text_md": "Keep saving until she has $15", "rationale_md": "Exactly! By saving more, she will be able to buy the toy. This is the correct option."}, {"id": "opt-c", "text_md": "Borrow from a friend and pay later", "rationale_md": "Borrowing can be risky and is not a form of saving. It''s better to save."}, {"id": "opt-d", "text_md": "Buy the toy now and pay later", "rationale_md": "She doesn''t have enough money now, so she can''t buy it. She must save first."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina saved $10 from her allowance and wants to buy a toy that costs $15. What should Dina do to be able to buy the toy?", "difficulty": 1, "explanation_md": "Correct! Dina should keep saving until she has $15. Spending everything now would not let her buy the more expensive toy.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "opt-b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/196b7f7df81c9779b8dd2a4a0e3fa82dc0fa070d7d9d10139721aa65518ca5b5.mp3", "hash": "736858fc2a9a887c59ebb39a780e5636e4c3edeed953048968349e0a32b067c2", "bytes": 42048, "voice": "Jennifer", "file_id": "lesson-audio/196b7f7df81c9779b8dd2a4a0e3fa82dc0fa070d7d9d10139721aa65518ca5b5.mp3", "duration_ms": 6960}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/5d669628abf2a5288e7bf9bcc3acb37229bfc80799d6cbd0b02f33f95b86aba3.mp3", "hash": "437f96e03cacacccc94a0ab27495c4921cd99eab8556344d1337f249b6ee4077", "bytes": 48816, "voice": "Jennifer", "file_id": "lesson-audio/5d669628abf2a5288e7bf9bcc3acb37229bfc80799d6cbd0b02f33f95b86aba3.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Revisão: Pergunta de múltipla escolha", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar a diferença entre poupar e gastar com exemplos concretos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 8, "type": "quiz_mcq", "hints": ["Lembre-se que poupar significa guardar dinheiro para usar depois. Se Dina já tem R$10, quanto falta?", "Pense no que você aprendeu na lição anterior sobre como poupar aos poucos."], "title": "Escolha a opção correta", "payload": {"options": [{"id": "opt-a", "text_md": "Gastar os R$10 agora em um doce", "rationale_md": "Se gastar tudo agora, não terá dinheiro para o brinquedo. Não é a melhor opção."}, {"id": "opt-b", "text_md": "Continuar poupando até ter R$15", "rationale_md": "Exato! Poupando mais, ela poderá comprar o brinquedo. Esta é a opção correta."}, {"id": "opt-c", "text_md": "Pedir emprestado a um amigo e pagar depois", "rationale_md": "Pedir emprestado pode ser arriscado e não é uma forma de poupança. Melhor é poupar."}, {"id": "opt-d", "text_md": "Comprar o brinquedo agora e pagar depois", "rationale_md": "Ela não tem dinheiro suficiente agora, então não pode comprá-lo. Deve poupar primeiro."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina poupou R$10 da sua mesada e quer comprar um brinquedo que custa R$15. O que Dina deveria fazer para conseguir comprar o brinquedo?", "difficulty": 1, "explanation_md": "Correto! Dina deve continuar poupando até juntar os R$15. Gastar tudo agora não permitiria comprar o brinquedo mais caro.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "opt-b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/b03f6a910fed1b834b79791f54ea5bf35d89558a1b2becf8509b85d18f009ff4.mp3", "hash": "3cc2a5f0337505f1b2dc81e2e751ac6f147c03a7a224a429127bcc65204da7cf", "bytes": 48384, "voice": "Ryan", "file_id": "lesson-audio/b03f6a910fed1b834b79791f54ea5bf35d89558a1b2becf8509b85d18f009ff4.mp3", "duration_ms": 8000}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/2569fc3ddba3b0f0d8b25ce821a7daf109670bdac46e4730ee4d587ada24badd.mp3", "hash": "034fcc880744bc8aae6089d51aca775131c591964c0fc54643367fac523b3071", "bytes": 47376, "voice": "Ryan", "file_id": "lesson-audio/2569fc3ddba3b0f0d8b25ce821a7daf109670bdac46e4730ee4d587ada24badd.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "concept-reveal", "title": "Revelación de conceptos con Zara", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio concept_reveal de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Voltea las tarjetas", "payload": {"cards": [{"icon": "book", "back_md": "Una **historia** es lo que pasa en un cuento: por ejemplo, cuando un perro se pierde y su dueña lo busca. Tiene un inicio, un problema y un final.", "front_md": "¿Qué es una **historia**?"}, {"icon": "person", "back_md": "Un **personaje** es quien vive la historia: como la niña y el perro del cuento. Puede ser una persona, un animal o un ser mágico.", "front_md": "¿Qué es un **personaje**?"}, {"icon": "theater", "back_md": "Una **escena** es un lugar y momento donde pasan cosas: como el parque donde el perro se perdió. Cada escena es como una foto del cuento.", "front_md": "¿Qué es una **escena**?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara ha preparado tarjetas con conceptos que ya viste. Voltea cada una para recordar lo que aprendiste con Dina y Zara en el cuento de la semana pasada. Como vimos en la lección anterior con Dina buscando a su perro, estos conceptos te ayudarán a entender mejor esa historia.", "difficulty": 1, "explanation_md": "Cada tarjeta te ayuda a recordar partes importantes de un cuento. Por ejemplo, en el cuento de ''El perro perdido'', la **historia** es lo que pasó (el perro se perdió y lo buscaron), el **personaje** es el perro y la niña, y la **escena** es el parque donde ocurrió. ¡Así armamos un cuento!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/8bfe3b417a47d6cf4aabafb509d1ced69ac834ed3d21dec494af03f8e4ce53bc.mp3", "hash": "ed1811aaecbe55338cdf47cfbeb8e1c77835be8a15f6e315cb79dc5111c38644", "bytes": 86256, "voice": "Li", "file_id": "lesson-audio/8bfe3b417a47d6cf4aabafb509d1ced69ac834ed3d21dec494af03f8e4ce53bc.mp3", "duration_ms": 14320}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/490c5d6cfd41f0bf9b2eade79f7376ad523fb657a681cc850d29abb68774d800.mp3", "hash": "c2fb60962d27fba2da58c93482669beb284ca186ba3cb27410a2f06ad1b5ffc6", "bytes": 54144, "voice": "Li", "file_id": "lesson-audio/490c5d6cfd41f0bf9b2eade79f7376ad523fb657a681cc850d29abb68774d800.mp3", "duration_ms": 8960}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/6f30e519f05e4d637da1a4f09c6a95ede52f13aabd96b67434692f0fc418a112.mp3", "hash": "aca21430eb4197b0a0bb438b9d672b019f35e977dd62669aff709c1f8f7b0215", "bytes": 42624, "voice": "Li", "file_id": "lesson-audio/6f30e519f05e4d637da1a4f09c6a95ede52f13aabd96b67434692f0fc418a112.mp3", "duration_ms": 7040}, "s1-concept-reveal.card.2.back": {"url": "http://localhost:4006/files/lesson-audio/d3abdac3a2064795dfcc60669ea963a09e1256feeadc5f933c5b8cf326c994ce.mp3", "hash": "680bbd976fadff43c644b30b5371e3d233dcf0443ba9660824cc31e12f3c5bf2", "bytes": 48816, "voice": "Li", "file_id": "lesson-audio/d3abdac3a2064795dfcc60669ea963a09e1256feeadc5f933c5b8cf326c994ce.mp3", "duration_ms": 8080}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d04a243f5fe68bb47de7d674d3bd9d8a7f2f14d820f706095bc5b71f1fd7819.mp3", "hash": "bf080a3f0fb1cc9045b1535f513cb94dfff2652b5e6f86c15ad1fecc19c2facf", "bytes": 101664, "voice": "Li", "file_id": "lesson-audio/0d04a243f5fe68bb47de7d674d3bd9d8a7f2f14d820f706095bc5b71f1fd7819.mp3", "duration_ms": 16880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "concept-reveal", "title": "Concept Reveal with Zara", "locale": "en-US", "subject": "mixed", "objectives": ["Test the concept_reveal exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Flip the cards", "payload": {"cards": [{"icon": "book", "back_md": "A **story** is what happens in a tale: for example, when a dog gets lost and its owner looks for it. It has a beginning, a problem, and an end.", "front_md": "What is a **story**?"}, {"icon": "person", "back_md": "A **character** is who lives the story: like the girl and the dog in the tale. It can be a person, an animal, or a magical being.", "front_md": "What is a **character**?"}, {"icon": "theater", "back_md": "A **scene** is a place and moment where things happen: like the park where the dog got lost. Each scene is like a snapshot of the story.", "front_md": "What is a **scene**?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara has prepared cards with concepts you''ve already seen. Flip each one to remember what you learned with Dina and Zara in last week''s story. As we saw in the previous lesson with Dina looking for her dog, these concepts will help you better understand that story.", "difficulty": 1, "explanation_md": "Each card helps you remember important parts of a story. For example, in the story ''The Lost Dog'', the **story** is what happened (the dog got lost and they looked for it), the **character** is the dog and the girl, and the **scene** is the park where it happened. That''s how we build a story!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/6ab8da9d63df805d7d6d4899e716fd2a53d39e037312c0bc43096fbc51a0dfee.mp3", "hash": "26e54f98d8a354d4d5d39dcdc0b3f07e2816b9d37bc06be0f53a4fb775d8cb86", "bytes": 88128, "voice": "Jennifer", "file_id": "lesson-audio/6ab8da9d63df805d7d6d4899e716fd2a53d39e037312c0bc43096fbc51a0dfee.mp3", "duration_ms": 14640}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/4551c37f3b1db6b793bebcc604a19276b0cd9f94971854964fceb072d140309d.mp3", "hash": "96fc00d62b6eeb356320cca9cdf233ebebbc455f25628b8a877fc12f94eacef4", "bytes": 51264, "voice": "Jennifer", "file_id": "lesson-audio/4551c37f3b1db6b793bebcc604a19276b0cd9f94971854964fceb072d140309d.mp3", "duration_ms": 8480}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/9029bb2c5a76b6aea37f374416b323fb52997b3cdca7382dff8c13c6b5e03ef0.mp3", "hash": "acfa2e0567945f3622e3919da7699ec5ba17209405813aa7da9790a29d2c92fb", "bytes": 48384, "voice": "Jennifer", "file_id": "lesson-audio/9029bb2c5a76b6aea37f374416b323fb52997b3cdca7382dff8c13c6b5e03ef0.mp3", "duration_ms": 8000}, "s1-concept-reveal.card.2.back": {"url": "http://localhost:4006/files/lesson-audio/f787af55e13e13b795000e882b98553fabd37f2e462b707df6d825016d6cae7e.mp3", "hash": "74aac69329b6ce2009113fd5cbc985bf6df894d97ed8c2bcdb2d63f2c305dce4", "bytes": 46368, "voice": "Jennifer", "file_id": "lesson-audio/f787af55e13e13b795000e882b98553fabd37f2e462b707df6d825016d6cae7e.mp3", "duration_ms": 7680}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/eda32c5ca3fb905af26c8ff3f39fb534bbb244613c4d5462d35c67267aafbd8e.mp3", "hash": "16de41311804909cd7dd6fc151c9619634b211543d0f80e1aec2e775b0d394a8", "bytes": 97344, "voice": "Jennifer", "file_id": "lesson-audio/eda32c5ca3fb905af26c8ff3f39fb534bbb244613c4d5462d35c67267aafbd8e.mp3", "duration_ms": 16160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "Economizar para o que quero", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar a diferença entre um desejo e uma necessidade", "Explicar por que é importante economizar para alcançar metas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Lembre-se de que economizar é guardar dinheiro aos poucos para uma meta.", "Divida o custo total pelo que você economiza a cada semana."], "title": "Economizar para o que quero", "payload": {"ideas": [{"icon": "savings", "title": "Economizar", "body_md": "Guardar dinheiro para usar depois em algo importante."}, {"icon": "goal", "title": "Meta", "body_md": "Algo que você quer alcançar, como comprar um brinquedo ou uma bicicleta."}, {"icon": "choice", "title": "Necessidade vs. Desejo", "body_md": "As necessidades são coisas que você precisa ter (comida, roupa). Os desejos são coisas que você gostaria de ter (brinquedos, guloseimas)."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quer comprar uma bicicleta nova que custa 500 reais. Cada semana ela economiza 50 reais da mesada. Quantas semanas ela precisa economizar para comprar a bicicleta?", "difficulty": 1, "explanation_md": "Dina precisa economizar por 10 semanas: 500 ÷ 50 = 10. Economizar ajuda você a conseguir o que quer sem pedir emprestado.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/ec65be61fb58189ee2cd1485fb931288568ad5425e21ee955b741f815289ff99.mp3", "hash": "114cb6bb601a561e367494ead76b06a3554a3cecd7ea95c9d9de983a7c7e3fb9", "bytes": 18144, "voice": "Ryan", "file_id": "lesson-audio/ec65be61fb58189ee2cd1485fb931288568ad5425e21ee955b741f815289ff99.mp3", "duration_ms": 2960}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/13cb3989dbd1a7273ee3b0583e29ea254624273232f4d10a864ecbf50fedfd68.mp3", "hash": "ae89d097be31e523f17a050940dcea8b0145ae696d894509e1357e319af98498", "bytes": 25776, "voice": "Ryan", "file_id": "lesson-audio/13cb3989dbd1a7273ee3b0583e29ea254624273232f4d10a864ecbf50fedfd68.mp3", "duration_ms": 4240}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/83430274b8afdd020fd6df58bb78b8f32ee4a9771e9cc88efd97a7ec5ade284c.mp3", "hash": "4eae7c81bcba2321cc4f9c8027da6b6920164083d1e9128af94e6961a74e71b3", "bytes": 61344, "voice": "Ryan", "file_id": "lesson-audio/83430274b8afdd020fd6df58bb78b8f32ee4a9771e9cc88efd97a7ec5ade284c.mp3", "duration_ms": 10160}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/d9396ade3e4009dac48ea31009d33f007c3d93ecb8cf56e7858d246b26a2a042.mp3", "hash": "c4d6a609ed7128527de4b73219108d13def3602d51c552c1056edd19ee1a7c8f", "bytes": 70848, "voice": "Ryan", "file_id": "lesson-audio/d9396ade3e4009dac48ea31009d33f007c3d93ecb8cf56e7858d246b26a2a042.mp3", "duration_ms": 11760}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/bbadeab45e5dfff8cdfdd4218ab4876d3c54f6a87afea9da1101ce46738802d6.mp3", "hash": "18c8d180dd2bee1fbc799392faf3164ab935211959f0e1a363c5356371aa4e61", "bytes": 59904, "voice": "Ryan", "file_id": "lesson-audio/bbadeab45e5dfff8cdfdd4218ab4876d3c54f6a87afea9da1101ce46738802d6.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Review with Dina", "locale": "en-US", "subject": "mixed", "objectives": ["Review the concepts from the previous lesson with a concrete example."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": ["Think about the coin example you saw before."], "title": "Review with Dina", "payload": {"recap_md": "You''ve learned about numbers and examples with coins. Keep it up!", "mood_prompt_md": "How do you feel about this review?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! I''m Dina. Do you remember when last week I saved 5 coins? Today we''re going to review what you learned. First, tell me: how many coins did I save?", "difficulty": 1, "explanation_md": "Very good! I saved 5 coins. That''s a number. Now remember: numbers help us count things.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/1016284f3f9918418aa3e9db8b90da6b2c1e36ce4e4a61eec6ce906ddbc9ad2b.mp3", "hash": "d89577eaf64ed7eb07416550afb61c949e703582372823bbcde7e520c5a6d19d", "bytes": 21024, "voice": "Jennifer", "file_id": "lesson-audio/1016284f3f9918418aa3e9db8b90da6b2c1e36ce4e4a61eec6ce906ddbc9ad2b.mp3", "duration_ms": 3440}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/6ed3492c3178e237572a2683a7bd6fda84e571af5d2b17c546e271c0cd98c3db.mp3", "hash": "eb53c90d9e13b85f5c1d09a51a5e51482e6420f76d330552a3c72793901bb912", "bytes": 57888, "voice": "Jennifer", "file_id": "lesson-audio/6ed3492c3178e237572a2683a7bd6fda84e571af5d2b17c546e271c0cd98c3db.mp3", "duration_ms": 9600}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/dc5c539aeab4b3242956a380055ce403f0d33007402fc2c7c8c5f57b8b79eddd.mp3", "hash": "8134b05cfd4f089d6a07889f8673eac385470322fbe2043a1f0db292ee6f0698", "bytes": 37296, "voice": "Jennifer", "file_id": "lesson-audio/dc5c539aeab4b3242956a380055ce403f0d33007402fc2c7c8c5f57b8b79eddd.mp3", "duration_ms": 6160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "quiz-mcq", "title": "Liruf''s Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Practice deciding whether to spend or save money in a concrete situation."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-quiz-mcq", "xp": 0, "type": "quiz_mcq", "hints": ["Think: if Liruf wants to save, should he spend or keep the money?"], "title": "Liruf''s Decision", "payload": {"options": [{"id": "a", "text_md": "Buy the apple", "rationale_md": "Spending reduces his savings, it''s not the best option for saving."}, {"id": "b", "text_md": "Keep the money", "rationale_md": "Correct. Keeping the money increases his savings."}, {"id": "c", "text_md": "Give away the money", "rationale_md": "Giving away also reduces his savings."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As we learned earlier with Dina and her piggy bank, saving means keeping money for the future. Liruf has saved 10 pesos in his piggy bank. He can buy an apple for 5 pesos or keep the money. What should Liruf do to keep saving?", "difficulty": 1, "explanation_md": "Great! If Liruf wants to save, the best thing is to keep the money. Spending reduces his savings.", "audio_segment_id": "s1-quiz-mcq.prompt"}], "schema_version": 1}', '{"s1-quiz-mcq": {"correct_option_id": "b"}}', '{"units": {"s1-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/5fedfdebc81daa87bd0f48d4b2909c27f86f8cf62b4f451b21783d6f7c9a6991.mp3", "hash": "9dc87649d6c0422d99b6c5c49e8400368d704e8f5e691b6e600e9536290ef45f", "bytes": 74736, "voice": "Jennifer", "file_id": "lesson-audio/5fedfdebc81daa87bd0f48d4b2909c27f86f8cf62b4f451b21783d6f7c9a6991.mp3", "duration_ms": 12400}, "s1-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/47c42c2164587314eb5f83b381c0145f140d56d0fcca2e250797c5631371dffe.mp3", "hash": "7e7529dd528ac3a71541f27b1d8509a6f3d1d1513a3d2a96dc383764e0a974e3", "bytes": 38304, "voice": "Jennifer", "file_id": "lesson-audio/47c42c2164587314eb5f83b381c0145f140d56d0fcca2e250797c5631371dffe.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "piggy-split", "title": "Prática: Piggy Split", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família money é gerado e renderizado corretamente.", "Verificar o exercício ''piggy_split'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["Lembre-se de que os potes devem somar o total de 80 MXN.", "Você pode usar moedas de 1, 2, 5, 10 e 20 MXN para formar as quantidades."], "title": "Dividindo em potes", "payload": {"jars": [{"id": "jar-golosinas", "icon": "candy", "label": "Guloseimas", "hint_md": "Preço de referência de uma guloseima: 15 MXN."}, {"id": "jar-juguetes", "icon": "toy", "label": "Brinquedos", "hint_md": "Preço de referência de um brinquedo pequeno: 80 MXN."}], "step": 1, "unit": "MXN", "income": 80}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! No exercício anterior você verificou ''make_change''. Agora vamos praticar ''piggy_split''. Zara ganhou **80 MXN** por ajudar na loja. Ela quer dividir esse dinheiro em seus potes de poupança: um para *guloseimas* e outro para *brinquedos*. Você pode ajudá-la a dividir os 80 MXN corretamente?", "difficulty": 1, "explanation_md": "Zara dividiu 80 MXN em dois potes: 15 MXN para guloseimas e 65 MXN para brinquedos. Assim ela pode poupar para o que mais quer!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-juguetes": {"max": 65, "min": 65}, "jar-golosinas": {"max": 15, "min": 15}}, "rationale_md": "Zara quiere ahorrar 15 MXN para golosinas y el resto (65 MXN) para juguetes. 15 + 65 = 80 MXN."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/dceda8f8a33d78f1e11b004c297ee4558e45ec019b5ea196538fab7558f264b5.mp3", "hash": "7e8c357bddc71afe398a8b7aba4260ba1bf253a63940d7f41fbcbc119f765bd5", "bytes": 116064, "voice": "Ryan", "file_id": "lesson-audio/dceda8f8a33d78f1e11b004c297ee4558e45ec019b5ea196538fab7558f264b5.mp3", "duration_ms": 19280}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/c22f57086d89b1f7de47e4615ac7be3338f17e7556dea6d59a6b8d16e2e92da1.mp3", "hash": "1021e7901c50ec4b4ce32e0da2d40cee221ab11dbecb235090f3e61fd03aa92d", "bytes": 72288, "voice": "Ryan", "file_id": "lesson-audio/c22f57086d89b1f7de47e4615ac7be3338f17e7556dea6d59a6b8d16e2e92da1.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "true-false", "title": "Verificar o exercício ''true_false'' de forma isolada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que o tipo true_false é gerado e renderizado corretamente"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Pense se Rho tem dinheiro suficiente para comprar o sorvete.", "Compare o dinheiro que ele tem com o preço."], "title": "Verdadeiro ou falso: Rho pode comprar um sorvete?", "payload": {"statement_md": "Rho pode comprar um sorvete de 8 moedas se tiver 10 moedas.", "justifications": [{"id": "j1", "text_md": "Porque 10 moedas são mais que 8 moedas, então dá para ele."}, {"id": "j2", "text_md": "Porque 10 moedas são menos que 8 moedas, então não dá para ele."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho tem 10 moedas e quer comprar um sorvete que custa 8 moedas. Isso é verdadeiro ou falso? Ajude-o a escolher a resposta correta e a justificativa adequada.", "difficulty": 1, "explanation_md": "A afirmação é verdadeira: Rho tem 10 moedas e o sorvete custa 8, então ele pode comprá-lo. A justificativa correta explica que ele tem dinheiro suficiente.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/7c0d651b2ffc10f402700589934eccb809252fb06cd81fe2f608197ba0994bcb.mp3", "hash": "c36e1ccbaf3045299b133caf043f93a8b1a232a6d832be24a8017de8e7c8557e", "bytes": 69408, "voice": "Ryan", "file_id": "lesson-audio/7c0d651b2ffc10f402700589934eccb809252fb06cd81fe2f608197ba0994bcb.mp3", "duration_ms": 11520}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/cbe5fe011294ed896a2213aba320e959eb29107415c3031b6ef64de83482a741.mp3", "hash": "7f8aef098c7ce8e7e2cf25da56006c7ceb7ab1a8deb9662c79bb3d9689759f66", "bytes": 71856, "voice": "Ryan", "file_id": "lesson-audio/cbe5fe011294ed896a2213aba320e959eb29107415c3031b6ef64de83482a741.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Práctica: Elige la imagen correcta", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''picture_choice'' de forma aislada (incluye generación de imágenes)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Pista: Busca la moneda o billete que vale 5 pesos."], "title": "Elige la imagen correcta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correcto. Esta es la moneda de 5 pesos que Zara necesita."}, {"id": "opt2", "icon": "apple", "label": "Manzana", "image_url": "https://example.com/apple.png", "rationale_md": "La manzana es lo que Zara quiere comprar, pero no es el precio."}, {"id": "opt3", "icon": "banana", "label": "Plátano", "image_url": "https://example.com/banana.png", "rationale_md": "El plátano es otra fruta, no el precio de la manzana."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! La última vez ayudaste a Dina a contar monedas. Ahora Zara quiere comprar una manzana. **Mira las imágenes** y elige la que muestra cuánto cuesta la manzana.\\n\\n**¿Cuál de estas imágenes muestra 5 pesos?**", "difficulty": 1, "explanation_md": "¡Muy bien! La imagen con la moneda de 5 pesos es la correcta. Las otras opciones muestran una manzana y un plátano.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/cf3ad2bd56d51768aca663ebee5fb09af44409516a72700aca36eacebfdc11c2.mp3", "hash": "6a26498306015dacba50a705ebca8c00c3fc0609320fbe73d0d94e4eff046d9d", "bytes": 71424, "voice": "Li", "file_id": "lesson-audio/cf3ad2bd56d51768aca663ebee5fb09af44409516a72700aca36eacebfdc11c2.mp3", "duration_ms": 11840}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/de912cf0157dcaf5900ac8127ef3518f17bf5312acbd79797cb0414ba46a81d8.mp3", "hash": "a3c11da206bd9f5fdcc312aebf1a4b2cbce5c85154a0991d9c833db4554d5bd1", "bytes": 45936, "voice": "Li", "file_id": "lesson-audio/de912cf0157dcaf5900ac8127ef3518f17bf5312acbd79797cb0414ba46a81d8.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "timeline-order", "title": "Ordem na linha do tempo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''timeline_order'' de forma isolada.", "Confirmar que cada tipo da família arrange é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 0, "type": "timeline_order", "hints": ["Pense no que acontece primeiro de manhã, depois ao meio-dia e no final da tarde. Por exemplo, o que você faz logo depois de acordar?", "Relacione cada evento com a hora do dia: acordar é cedo, jantar é ao anoitecer."], "title": "Ordene os eventos", "payload": {"events": [{"id": "e1", "icon": "sunrise", "text_md": "Acordar"}, {"id": "e2", "icon": "food", "text_md": "Tomar café da manhã"}, {"id": "e3", "icon": "school", "text_md": "Ir para a escola"}, {"id": "e4", "icon": "play", "text_md": "Brincar"}, {"id": "e5", "icon": "dinner", "text_md": "Jantar"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf acorda às 7 da manhã. Depois de acordar, ele toma café da manhã às 7:30. Em seguida, vai para a escola às 8. À tarde, brinca com seus amigos e finalmente janta às 7 da noite. Ajude-o a colocar esses eventos em ordem cronológica, do mais cedo ao mais tarde. Lembre-se do que aprendeu sobre as rotinas diárias: primeiro acordamos, depois tomamos café da manhã, em seguida vamos para a escola, mais tarde brincamos e finalmente jantamos. Como na lição anterior!", "difficulty": 1, "explanation_md": "A ordem correta é: Acordar, Tomar café da manhã, Ir para a escola, Brincar, Jantar. Assim é como geralmente transcorre um dia típico. Bom trabalho!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/d643b42704b3ccecbc74d72f8cca53fe93394b7a39137bc203da5e514749912f.mp3", "hash": "e5e46cc285be6a8bad39fa228247ecc4ba61383ff2959395d71414312fb1a5bb", "bytes": 188928, "voice": "Ryan", "file_id": "lesson-audio/d643b42704b3ccecbc74d72f8cca53fe93394b7a39137bc203da5e514749912f.mp3", "duration_ms": 31440}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/1f3c3743a875b9ba9a87dca774e682aa86bfce001145ae7fb9e7f8df339ede2a.mp3", "hash": "730427edd2dce55db99dd5a1fec9d14b2ef2224f07e770f3a80c785876610551", "bytes": 84384, "voice": "Ryan", "file_id": "lesson-audio/1f3c3743a875b9ba9a87dca774e682aa86bfce001145ae7fb9e7f8df339ede2a.mp3", "duration_ms": 14000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Prática: Escolha a imagem correta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''picture_choice'' de forma isolada (inclui geração de imagens)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Dica: Procure a moeda ou nota que vale 5 pesos."], "title": "Escolha a imagem correta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correto. Esta é a moeda de 5 pesos que a Zara precisa."}, {"id": "opt2", "icon": "apple", "label": "Maçã", "image_url": "https://example.com/apple.png", "rationale_md": "A maçã é o que a Zara quer comprar, mas não é o preço."}, {"id": "opt3", "icon": "banana", "label": "Banana", "image_url": "https://example.com/banana.png", "rationale_md": "A banana é outra fruta, não o preço da maçã."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Da última vez você ajudou a Dina a contar moedas. Agora a Zara quer comprar uma maçã. **Olhe as imagens** e escolha aquela que mostra quanto custa a maçã.\\n\\n**Qual destas imagens mostra 5 pesos?**", "difficulty": 1, "explanation_md": "Muito bem! A imagem com a moeda de 5 pesos é a correta. As outras opções mostram uma maçã e uma banana.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/22af40e7f22ad2d37137bd36884f14f6e46f327754d2cb17a40e3337c0ff0c9c.mp3", "hash": "339e3cc1a099b14ce5de0e890a019819f4822200502d4ff4326a612cdb820d6c", "bytes": 73728, "voice": "Ryan", "file_id": "lesson-audio/22af40e7f22ad2d37137bd36884f14f6e46f327754d2cb17a40e3337c0ff0c9c.mp3", "duration_ms": 12240}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/7c80f774789228d408806b57f9be9f8eedd447622dd0aa6aeaa097a5b5e12903.mp3", "hash": "bb39834c3a7598fa122daaf1db892c299cd1510b287f39196b70e5099149ca71", "bytes": 50688, "voice": "Ryan", "file_id": "lesson-audio/7c80f774789228d408806b57f9be9f8eedd447622dd0aa6aeaa097a5b5e12903.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "speed-tap", "title": "Speed Tap: Tap Fast!", "locale": "en-US", "subject": "mixed", "objectives": ["Test the speed_tap exercise in isolation (timed flow)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["Look carefully at the items before you start.", "Focus on the ones that are star-shaped."], "title": "Speed Tap: Tap Fast!", "payload": {"items": [{"id": "item1", "text_md": "⭐ Star"}, {"id": "item2", "text_md": "🔵 Circle"}, {"id": "item3", "text_md": "⭐ Star"}, {"id": "item4", "text_md": "🔺 Triangle"}, {"id": "item5", "text_md": "⭐ Star"}, {"id": "item6", "text_md": "🔴 Square"}], "seconds": 10, "instruction_md": "Tap all the star-shaped items as fast as you can. Remember: stars are important income."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "In the previous lesson, you learned that stars represent income in our finance game. Today, Zara needs your help to collect stars before time runs out. She is very excited because each star means more money for her project! But she has to be fast, because there are only 10 seconds. Are you ready to help her?", "difficulty": 1, "explanation_md": "Great job! You helped Zara tap the right items on time. Each star you tapped is income for her project. Keep it up!", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["item1", "item3", "item5"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/0ef7cf75487a3561a3c725a82d43f2591f35d6042b19fa3f03bdf905c1d5a368.mp3", "hash": "394e1617177aa80be2fa49e18d7c15816bfe19a1e03844091dc1d892decbfc68", "bytes": 122256, "voice": "Jennifer", "file_id": "lesson-audio/0ef7cf75487a3561a3c725a82d43f2591f35d6042b19fa3f03bdf905c1d5a368.mp3", "duration_ms": 20320}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e6ad9031ab19e9aee803b0c248fd386e86a5c4a11eeea2849f36f5940db71a9.mp3", "hash": "ebc2aeba22f327410400ba0d19714fcdb4229e6b257ae3d6b4d9c479998733d6", "bytes": 44064, "voice": "Jennifer", "file_id": "lesson-audio/2e6ad9031ab19e9aee803b0c248fd386e86a5c4a11eeea2849f36f5940db71a9.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "estimate-slider", "title": "Verificar control deslizante de estimación", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que el tipo control deslizante de estimación se genera y renderiza correctamente.", "Verificar el ejercicio de control deslizante de estimación de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Arrastra el control deslizante hacia la derecha hasta cerca del número 50.", "Puedes soltar el control cuando veas que el número se acerca a 50."], "title": "Ajusta la barra", "payload": {"max": 100, "min": 0, "step": 1, "unit": "monedas", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Recuerdas cuando Dina contó sus monedas la vez pasada? Ahora va a estimar cuántas tiene en su alcancía sin contarlas una por una. Piensa: si juntaste 10 monedas en tu mano, ¿cuántas serían 5 montones así? Dina ahorró toda la semana y quiere saber si tiene cerca de 50 monedas. Mueve la barra para indicar tu estimación. La respuesta correcta es 50 monedas. Ajusta el control deslizante lo más cerca posible de 50.", "difficulty": 1, "explanation_md": "¡Bien hecho! La barra te permite elegir un valor moviendo el control. En este caso, la respuesta correcta era 50. Si tu estimación estuvo dentro del rango de acierto, ¡felicidades!", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 50, "full_credit_delta": 5, "zero_credit_delta": 20}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/65040110f7a1583fcfc80416239827f4eb776bb64bc4a0341b475346209e8326.mp3", "hash": "6067c2c39c1bab61c3c9c3b2a080116f5af98ef5eb0942b1d5487861c7d26663", "bytes": 157248, "voice": "Li", "file_id": "lesson-audio/65040110f7a1583fcfc80416239827f4eb776bb64bc4a0341b475346209e8326.mp3", "duration_ms": 26160}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/706564ee35f377790947bbd0c6adb9378fc52e2687181a75307d08fec02892a9.mp3", "hash": "23f28947a8f56a13dc92e04cbfa4f94972fa7da85e2753b94515551c7c358972", "bytes": 66528, "voice": "Li", "file_id": "lesson-audio/706564ee35f377790947bbd0c6adb9378fc52e2687181a75307d08fec02892a9.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "memory-flip", "title": "Memory Flip: Finding Pairs", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''memory_flip'' exercise in isolation (memory flow)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Remember in the previous lesson you saw how to group similar objects. Can you group these concepts with their examples like you grouped apples and pears?"], "title": "Memory Flip: Finding Pairs", "payload": {"pairs": [{"a_md": "Order", "b_md": "Having things in their place, like apples in one basket and pears in another."}, {"a_md": "Pair", "b_md": "Two things that go together, like a left sock and a right sock."}, {"a_md": "Group", "b_md": "Several things that are the same, like three red balls."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina helps her friends organize their toys. She has 4 cards: two with apples and two with pears. Can you flip the cards to match each concept with its example? For instance, the card ''Order'' is already paired with ''Having things in their place, like apples in one basket and pears in another.''", "difficulty": 1, "explanation_md": "In this exercise, you practice matching concepts with their definitions, just like in the memory game. For example, ''Order'' means having things in their place, like when Dina puts her apples in one basket and pears in another.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/248d33b3937c25954e66d524e07e2d1c96c66687533f77b3f0c2c4c7bf943c10.mp3", "hash": "d64ae4c5cbfb9b4cecdfefe65cee89e90ba176e6544faec2cc88117975cfb8d8", "bytes": 93024, "voice": "Jennifer", "file_id": "lesson-audio/248d33b3937c25954e66d524e07e2d1c96c66687533f77b3f0c2c4c7bf943c10.mp3", "duration_ms": 15440}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/95935ad229e33d01c09e29972b514bbc845c3bb637442d45eba1d0339df39254.mp3", "hash": "395d61660382b440728c4d8be111784ccfa1e0d5eb3c0c7c1431d09ca69972d0", "bytes": 68976, "voice": "Jennifer", "file_id": "lesson-audio/95935ad229e33d01c09e29972b514bbc845c3bb637442d45eba1d0339df39254.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasifica con Liruf: Canastas ordenadas", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''sort_buckets'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Observa la etiqueta de cada canasta para saber qué va dentro.", "Si no estás seguro, piensa en el uso de cada objeto."], "title": "Clasifica con Liruf", "payload": {"items": [{"id": "i1", "text_md": "Pelota"}, {"id": "i2", "text_md": "Camiseta"}, {"id": "i3", "text_md": "Cuento"}, {"id": "i4", "text_md": "Zapatos"}, {"id": "i5", "text_md": "Muñeca"}, {"id": "i6", "text_md": "Enciclopedia"}], "buckets": [{"id": "b1", "label": "Juguetes"}, {"id": "b2", "label": "Ropa"}, {"id": "b3", "label": "Libros"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! Ayer aprendimos a agrupar cosas por color; hoy, Liruf quiere agruparlas por tipo.\\n\\nLiruf está limpiando su cuarto antes de la fiesta y encontró un montón de objetos. Quiere poner cada uno en la canasta correcta. Ayúdale a clasificarlos.\\n\\n**Instrucciones:** Arrastra cada objeto a la canasta que corresponda según su tipo.\\n\\n**Ejemplo:** Mira, la pelota es un juguete, así que va en la canasta de juguetes.", "difficulty": 1, "explanation_md": "¡Buen trabajo! Clasificar objetos nos ayuda a mantener todo en orden. Liruf está muy contento con tu ayuda.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"i1": "b1", "i2": "b2", "i3": "b3", "i4": "b2", "i5": "b1", "i6": "b3"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/57bd79508f8a27aa1f2103971533e4837d1eab5bee1d15b23edc43e19c55e02a.mp3", "hash": "37c57f850e801ee3044d3fd5e1d7f6600e600dac892056cada51a6031743d2cd", "bytes": 147744, "voice": "Li", "file_id": "lesson-audio/57bd79508f8a27aa1f2103971533e4837d1eab5bee1d15b23edc43e19c55e02a.mp3", "duration_ms": 24560}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/f47970591da1242eae68b689546928e5ff352e9629555960c96adbd193971f0f.mp3", "hash": "bf6a538940667e5466b9a1446f83ef7e47d740c80e9a2441b49fdd93202f5650", "bytes": 42048, "voice": "Li", "file_id": "lesson-audio/f47970591da1242eae68b689546928e5ff352e9629555960c96adbd193971f0f.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "rank-choices", "title": "Verificar o exercício rank_choices", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família arrange é gerado e renderizado corretamente.", "Verificar o exercício rank_choices de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 0, "type": "rank_choices", "hints": ["Pense no preço de cada item: um doce custa 5 reais, um livro custa 50 reais e uma bicicleta custa 500 reais.", "A ordem do menor para o maior preço é: doce (5 reais), livro (50 reais), bicicleta (500 reais)."], "title": "Ordene as opções", "payload": {"items": [{"id": "item-dulce", "text_md": "doce"}, {"id": "item-libro", "text_md": "livro"}, {"id": "item-bicicleta", "text_md": "bicicleta"}], "criterion_md": "do mais barato ao mais caro"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra como ordenamos coisas por tamanho da última vez? Agora faremos por preço. Zara economizou 20 reais e quer escolher sabiamente. Ajude-a a ordenar os itens **do mais barato ao mais caro**. Arraste cada opção para o lugar correto. Os preços são: doce: R$5, livro: R$50, bicicleta: R$500.", "difficulty": 1, "explanation_md": "A ordem correta é: doce (5 reais, mais barato), livro (50 reais, preço médio), bicicleta (500 reais, mais caro). Muito bem!", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["item-dulce", "item-libro", "item-bicicleta"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/3172b9a8128f28d390e591444116afda62e7471cd870e4e8aa069276dc371062.mp3", "hash": "cbfef75e101495b74133033bda49a9403791178361c94a8c95dfd450dcafdecb", "bytes": 128016, "voice": "Ryan", "file_id": "lesson-audio/3172b9a8128f28d390e591444116afda62e7471cd870e4e8aa069276dc371062.mp3", "duration_ms": 21280}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/18db2c7c40b4583cac976825fdc0cabfbe25c3fb8d4fc545b78a678da70d6397.mp3", "hash": "dd534407bf40bdad014de59516979c6f95af0a8aecf44e70fea319e5b0782ba8", "bytes": 75168, "voice": "Ryan", "file_id": "lesson-audio/18db2c7c40b4583cac976825fdc0cabfbe25c3fb8d4fc545b78a678da70d6397.mp3", "duration_ms": 12480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "make-change", "title": "Verificar el ejercicio make_change", "locale": "es-MX", "subject": "mixed", "objectives": ["Confirmar que cada tipo de la familia money se genera y renderiza correctamente.", "Verificar el ejercicio ''make_change'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 0, "type": "make_change", "hints": ["Recuerda: el cambio es la diferencia entre lo que pagaste y el precio."], "title": "El cambio correcto", "payload": {"price": 80, "currency": "MXN", "paid_with": 100, "denominations": [1, 2, 5, 10, 20, 20, 50, 100, 200]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya contaste monedas en la lección anterior, Rho te ayudará a verificar el ejercicio ''make_change''. Dina está comprando un juguete en la tienda de Rho. Imagina que compras un juguete que cuesta **80 MXN** y pagas con un billete de **100 MXN**. ¿Cuánto cambio debes recibir?", "difficulty": 1, "explanation_md": "El cambio se calcula restando el precio del dinero entregado: 100 - 80 = 20 MXN. Puedes recibir, por ejemplo, una moneda de 20 MXN.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/af492f58e67bfc9e74f39f7ac546433f81afbdf5012eefb6e172774e3218ef78.mp3", "hash": "82f3a79712fb546cdfc2d36bbe6c3b95c9bc3a6453e0cb32cf9841cade6b1468", "bytes": 125136, "voice": "Li", "file_id": "lesson-audio/af492f58e67bfc9e74f39f7ac546433f81afbdf5012eefb6e172774e3218ef78.mp3", "duration_ms": 20800}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/4bb5742972b20dc88295268d91d71596937da39f7cb95893c87f309caaf302f2.mp3", "hash": "f532060d3f20f59f774ea5548115285c571c53eec96f73c14a3065594177cbb7", "bytes": 54144, "voice": "Li", "file_id": "lesson-audio/4bb5742972b20dc88295268d91d71596937da39f7cb95893c87f309caaf302f2.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "price-compare", "title": "Comparando precios con Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''price_compare'' de forma aislada.", "Identificar la mejor oferta entre dos opciones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 0, "type": "price_compare", "hints": ["Fíjate en el precio por unidad. Primero, calcula cuánto cuesta cada juguete en la oferta A: 1 juguete cuesta 80 MXN. Luego, en la oferta B: 2 juguetes cuestan 150 MXN, así que divide 150 entre 2 para obtener el precio por juguete. Compara los dos precios por juguete."], "title": "Compara ofertas", "payload": {"offers": [{"id": "offer-a", "qty": 1, "unit": "juguete", "label": "Oferta A: 1 juguete", "price": 80}, {"id": "offer-b", "qty": 2, "unit": "juguetes", "label": "Oferta B: 2 juguetes", "price": 150}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendimos ayer con Dina sobre precios, hoy Liruf necesita ayuda para comprar un juguete para su amigo Rho. Liruf encontró dos ofertas. ¿Cuál es la mejor?", "difficulty": 1, "explanation_md": "La oferta A da 1 juguete por 80 MXN, así que el precio por juguete es 80 MXN. La oferta B da 2 juguetes por 150 MXN, así que el precio por juguete es 150 ÷ 2 = 75 MXN. Como 75 es menor que 80, la oferta B es la mejor.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "offer-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/e46dc328b217fff9d5a2282a572f495b339f62db517eafe7672454c6bf0dbee4.mp3", "hash": "4609592ecb53f4adaf2df92902f9c471dcb6c97e8695d11456cde94cc375cb75", "bytes": 62208, "voice": "Li", "file_id": "lesson-audio/e46dc328b217fff9d5a2282a572f495b339f62db517eafe7672454c6bf0dbee4.mp3", "duration_ms": 10320}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/b2009f90e88be44c1b18bdc8ff79bb3018c140deede9550027630aab12c4525a.mp3", "hash": "d8bba7093a07f45517b20fe3b7ff1b489118dcc8e0e962520963de339918b6d2", "bytes": 123696, "voice": "Li", "file_id": "lesson-audio/b2009f90e88be44c1b18bdc8ff79bb3018c140deede9550027630aab12c4525a.mp3", "duration_ms": 20560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Needs and Wants with Dina", "locale": "en-US", "subject": "mixed", "objectives": ["Classify items as needs or wants.", "Understand the difference between what is necessary and what we just like."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Think about whether the item is necessary for living or just a want."], "title": "Separate needs from wants", "payload": {"items": [{"id": "item1", "icon": "water", "text_md": "Water"}, {"id": "item2", "icon": "toy", "text_md": "Toy for 80 MXN"}, {"id": "item3", "icon": "food", "text_md": "Food"}, {"id": "item4", "icon": "candy", "text_md": "Candy for 15 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! Last time we learned that money is earned and saved. Today we''ll see what to spend it on. Dina will use it to decide between needs and wants. Dina is saving and wants to know what she should spend on first. Help her classify each item: is it a need or a want?", "difficulty": 1, "explanation_md": "Needs are things we must have to live, like food and water. Wants are things that make us happy but are not necessary.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item1", "item3"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/9ac0ee1545ef0b18f597a09ba8fca00622d4ce4eeffe7abe98c1fb03afd29d55.mp3", "hash": "7cdcb55e18f88b343a2b27f9ef599f76d25604a00879c1fd3f06f5ce9bc77a04", "bytes": 96768, "voice": "Jennifer", "file_id": "lesson-audio/9ac0ee1545ef0b18f597a09ba8fca00622d4ce4eeffe7abe98c1fb03afd29d55.mp3", "duration_ms": 16080}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/2be34ea2f16b1071f90faf319b898601851b5cab0f1d4af469e51c2a6bf2df7a.mp3", "hash": "967ae88ad63a094a14550cb612654d6cf635de2116fd64c2ec82786488d24191", "bytes": 55584, "voice": "Jennifer", "file_id": "lesson-audio/2be34ea2f16b1071f90faf319b898601851b5cab0f1d4af469e51c2a6bf2df7a.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "spot-error", "title": "Encontre o erro no procedimento", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''spot_error'' de forma isolada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Revise cada passo com cuidado. Há algum passo que não faz sentido?", "Pense na ordem lógica. Qual passo deveria vir antes ou depois?"], "title": "Encontre o passo errado", "payload": {"steps": [{"id": "step1", "text_md": "Passo 1: Anote os preços dos itens: uma maçã de $5 e um pão de $10."}, {"id": "step2", "text_md": "Passo 2: Multiplique as quantidades para obter o total."}, {"id": "step3", "text_md": "Passo 3: Revise se não falta nenhum item."}], "context_md": "Como aprendemos ontem ao somar compras, Rho está revisando um procedimento para calcular o total de uma compra em uma lojinha. Estes são os passos que alguém escreveu:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho encontrou um procedimento com um erro. Ajude-o a identificar o passo que está errado.", "difficulty": 1, "explanation_md": "O passo 2 diz ''Multiplique as quantidades'' mas primeiro devemos somar. A ordem correta é: somar primeiro, depois multiplicar.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El paso 2 debería decir: ''Suma los precios para obtener el total''."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/c41a8a4ba3a89e8ffe2f82410feee917e674c59cd8cdda399603d837e54d72a4.mp3", "hash": "eda67c94721512f0ff3315ce9e7a4ec355e396ae42d9920a67730be6861526a3", "bytes": 32976, "voice": "Ryan", "file_id": "lesson-audio/c41a8a4ba3a89e8ffe2f82410feee917e674c59cd8cdda399603d837e54d72a4.mp3", "duration_ms": 5440}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/991fc50adb44601164b64ea8f1d20b546ba24bd3dfbd4c8ae53bf539e0352487.mp3", "hash": "190c6b4a35c3c0d53f44e71790547549d36a2819c347f072533974540a69eb5d", "bytes": 54576, "voice": "Ryan", "file_id": "lesson-audio/991fc50adb44601164b64ea8f1d20b546ba24bd3dfbd4c8ae53bf539e0352487.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "code-order", "title": "Verificar o exercício code_order", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família maker é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Dica: Pense em qual passo vem primeiro: construir, medir ou programar?"], "title": "Ordene os blocos", "payload": {"blocks": [{"id": "b1", "text_md": "construir"}, {"id": "b2", "text_md": "medir"}, {"id": "b3", "text_md": "programar"}], "language_hint": "pt-BR"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ontem você aprendeu a construir com peças. Hoje, Rho quer construir um robô com 5 peças. Primeiro, construa o robô com as peças. Depois, meça sua altura com uma régua. Finalmente, coloque baterias para programá-lo. Ajude Rho a ordenar os blocos de código na ordem correta: primeiro construir, depois medir, depois programar.", "difficulty": 1, "explanation_md": "A ordem correta é: **construir**, depois **medir**, depois **programar**. Assim você garante que o robô esteja pronto.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/d50245983195ffb957659bbeba87b29c085cfd8cbeef74aba03c082a1248ea50.mp3", "hash": "9e7210c1b8fcd3038cc5e7a60b5f91c98e9f2a763f15e495d112b972ad22714b", "bytes": 139536, "voice": "Ryan", "file_id": "lesson-audio/d50245983195ffb957659bbeba87b29c085cfd8cbeef74aba03c082a1248ea50.mp3", "duration_ms": 23200}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/ec0674b47c67cfc138165ce7c0501a2750f15a2825d7eef52b537a9a8275aec9.mp3", "hash": "cc8e596a34f4b4459fe90b95a96a34e01b590e51511cc6751aa5d76b5437e508", "bytes": 47376, "voice": "Ryan", "file_id": "lesson-audio/ec0674b47c67cfc138165ce7c0501a2750f15a2825d7eef52b537a9a8275aec9.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Balancing the Scale", "locale": "en-US", "subject": "mixed", "objectives": ["Solve balance problems using a pan balance.", "Practice small sums to equalize amounts."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Try a weight of 2 and a weight of 3.", "You can also use five weights of 1."], "title": "Balancing the Scale", "payload": {"weights": [{"id": "w1", "label": "Weight of 1", "value": 1}, {"id": "w2", "label": "Weight of 2", "value": 2}, {"id": "w3", "label": "Weight of 3", "value": 3}], "left_fixed": [{"label": "Fixed weight", "value": 5}], "unknown_label": "Unknown weight"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina and Liruf are playing with a real balance. On the left pan there is a weight of 5. On the table there are weights of 1, 2, and 3. Help Liruf put weights on the right pan so that the balance is even. Which weights do you choose?", "difficulty": 1, "explanation_md": "Great job! For the balance to be even, both pans must have the same weight. 5 equals 2+3, or also 1+1+1+1+1. You did it!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f63cabfbd6df1e9d76e1e3a3ad4882fa298a6caaf7e2debb6c45bf8b9161619.mp3", "hash": "b22b31fe3430a760f38f42f92bc875383060b516a49dab5008c8810912c96b2a", "bytes": 80496, "voice": "Jennifer", "file_id": "lesson-audio/8f63cabfbd6df1e9d76e1e3a3ad4882fa298a6caaf7e2debb6c45bf8b9161619.mp3", "duration_ms": 13360}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/4678ad3dd0ad36d318c9fa79da41fc1d16a13f8807439fd993a43ec1e189350c.mp3", "hash": "ed8713df24a8c52c55fd655ffd22441cbe8867ac532cc8aa226624e50bc11955", "bytes": 70416, "voice": "Jennifer", "file_id": "lesson-audio/4678ad3dd0ad36d318c9fa79da41fc1d16a13f8807439fd993a43ec1e189350c.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "measure-read", "title": "Verificar el ejercicio measure_read", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''measure_read'' de forma aislada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 0, "type": "measure_read", "hints": ["Cuenta los centímetros desde el cero hasta donde apunta la flecha."], "title": "Lee la medida", "payload": {"max": 10, "min": 0, "unit": "cm", "ticks": 10, "instrument": "ruler", "pointer_value": 7}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! En el ejercicio anterior de la balanza, aprendiste a medir peso. Ahora, Rho va a leer una medida en un instrumento. Observa la regla y dime cuántos centímetros marca la flecha.", "difficulty": 1, "explanation_md": "La flecha apunta exactamente a 7 cm. ¡Bien hecho! Rho está feliz de que leas correctamente.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 7, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/e93bfc0e5829af3da23f754066e647083290f8dda803913c8913333b6e9bda75.mp3", "hash": "028309814270794d922092a1a62900b2c152df2b66f2029a545ad10e8e11243d", "bytes": 64224, "voice": "Li", "file_id": "lesson-audio/e93bfc0e5829af3da23f754066e647083290f8dda803913c8913333b6e9bda75.mp3", "duration_ms": 10640}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/cec8bf1452995afa7cfbc070e771ee59575abe96969055828c4fa6e5fba6a093.mp3", "hash": "f138ae9fbb9fcd1bcd08f5b7be912cbec0deb613382ee9bed30eb0a322d1cb19", "bytes": 31104, "voice": "Li", "file_id": "lesson-audio/cec8bf1452995afa7cfbc070e771ee59575abe96969055828c4fa6e5fba6a093.mp3", "duration_ms": 5120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "measure-read", "title": "Verificar o exercício measure_read", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''measure_read'' de forma isolada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 0, "type": "measure_read", "hints": ["Conte os centímetros desde o zero até onde a flecha aponta."], "title": "Leia a medida", "payload": {"max": 10, "min": 0, "unit": "cm", "ticks": 10, "instrument": "ruler", "pointer_value": 7}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! No exercício anterior da balança, você aprendeu a medir peso. Agora, Rho vai ler uma medida em um instrumento. Observe a régua e me diga quantos centímetros a flecha marca.", "difficulty": 1, "explanation_md": "A flecha aponta exatamente para 7 cm. Muito bem! Rho está feliz que você leu corretamente.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 7, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f251d780358bc1becb84c931e4513bf3fa59a4496b2a8da1f77d92212227723.mp3", "hash": "a83afa6dcbcfd532ee96ee8422a26a09f4d410cf3da65da07900ff4d0313ce2d", "bytes": 70416, "voice": "Ryan", "file_id": "lesson-audio/8f251d780358bc1becb84c931e4513bf3fa59a4496b2a8da1f77d92212227723.mp3", "duration_ms": 11680}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/be1ee668fe68ec81bd8a38042943ddf998e419b17a847a28ea8e6f5bc169000f.mp3", "hash": "74d087e50754bb8c84020e9c7d6c4c4efb71c451c91a2ef00b5d47d6649e2409", "bytes": 40608, "voice": "Ryan", "file_id": "lesson-audio/be1ee668fe68ec81bd8a38042943ddf998e419b17a847a28ea8e6f5bc169000f.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-input", "title": "Check the number_input exercise", "locale": "en-US", "subject": "mixed", "objectives": ["Confirm that each family input type is generated and renders correctly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "hints": ["The number Zara wants to write is the one between 4 and 6."], "title": "Write the number", "payload": {"unit": "número", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Remember, in the last lesson we learned to count coins. Zara wants to pay 5 pesos for a candy. What number should she press on the number keypad to write 5?", "difficulty": 1, "explanation_md": "Correct! Zara pressed **5** on the number keypad. That''s how you write the number 5, which is the pesos she needs to pay.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 5, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/abb0c0e83028879d9d5e95076068350994e8b0eda4513a1361dafa0ded3046e7.mp3", "hash": "10e4251618bf31371ae1a509d70b5cf10c2532fb3d58af497ac05149dc249bdf", "bytes": 53136, "voice": "Jennifer", "file_id": "lesson-audio/abb0c0e83028879d9d5e95076068350994e8b0eda4513a1361dafa0ded3046e7.mp3", "duration_ms": 8800}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/888fdbc5d6049c299517de67407232f41c4c7f075d4c988af8e5e97491593bd8.mp3", "hash": "8e93cecdca3e04da50bfb253015ca8ff6fcf85d5789e4adc62e9ed32ea86c6ad", "bytes": 41616, "voice": "Jennifer", "file_id": "lesson-audio/888fdbc5d6049c299517de67407232f41c4c7f075d4c988af8e5e97491593bd8.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "number-input", "title": "Verificar o exercício number_input", "locale": "pt-BR", "subject": "mixed", "objectives": ["Confirmar que cada tipo da família input é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "hints": ["O número que Zara quer escrever é o que está entre o 4 e o 6."], "title": "Escreva o número", "payload": {"unit": "número", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Lembre-se de que na lição passada aprendemos a contar moedas. Zara quer pagar 5 pesos por um doce. Qual número ela deve pressionar no teclado numérico para escrever 5?", "difficulty": 1, "explanation_md": "Correto! Zara pressionou o **5** no teclado numérico. Assim se escreve o número 5, que são os pesos que ela precisa pagar.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 5, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/abb3f5b63d8987895c32192a7ad7b347c63e0a5c0f4009a2fa5289288cb5e180.mp3", "hash": "472797d1fd763921d0068666669cac052af92aa7ffa7c342453394d793b722cb", "bytes": 67104, "voice": "Ryan", "file_id": "lesson-audio/abb3f5b63d8987895c32192a7ad7b347c63e0a5c0f4009a2fa5289288cb5e180.mp3", "duration_ms": 11120}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/a0f5b1fa6079aad7c2769d2cb978779ea3d76396747f64c85bddf19068879dff.mp3", "hash": "2814d370f19252189b7767bb857ece407b9de6a1e0bc4ffa21dcda2f64bce336", "bytes": 77184, "voice": "Ryan", "file_id": "lesson-audio/a0f5b1fa6079aad7c2769d2cb978779ea3d76396747f64c85bddf19068879dff.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Counting Objects with Liruf", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''count_objects'' exercise in isolation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-objects", "xp": 5, "type": "count_objects", "hints": ["Look carefully at all the objects in the scene. How many circles do you see?", "Point to each circle with your finger as you count out loud."], "title": "Count the objects", "payload": {"scene": [{"icon": "circle", "tint": "primary", "count": 2}, {"icon": "circle", "tint": "accent", "count": 1}], "ask_icon": "circle"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Remember yesterday we counted apples with Liruf? Today we''re going to count circles. Liruf is sorting toys and needs help counting his red and blue circles. First, point to each circle as you count: one, two, three. How many circles are there in total?", "difficulty": 1, "explanation_md": "Correct! There are 3 circles in the scene. You counted correctly.", "audio_segment_id": "s1-count-objects.prompt"}], "schema_version": 1}', '{"s1-count-objects": {"value": 3}}', '{"units": {"s1-count-objects.prompt": {"url": "http://localhost:4006/files/lesson-audio/8bc51e954b2a29ab99d5df498f2269c1c6402270706eac4bd242e29e23db59ed.mp3", "hash": "34908430f37823b3390c474b88be995925142995eecec7b8adbc3e64f2fe36bd", "bytes": 89568, "voice": "Jennifer", "file_id": "lesson-audio/8bc51e954b2a29ab99d5df498f2269c1c6402270706eac4bd242e29e23db59ed.mp3", "duration_ms": 14880}, "s1-count-objects.explanation": {"url": "http://localhost:4006/files/lesson-audio/9d15ef69216c27e09244391783158c34c3990c4df7198b7fc79855ceffcfdfe1.mp3", "hash": "8776fb170baca3835215f107923078f5ef060842a0861e4fae5824177affc36e", "bytes": 22896, "voice": "Jennifer", "file_id": "lesson-audio/9d15ef69216c27e09244391783158c34c3990c4df7198b7fc79855ceffcfdfe1.mp3", "duration_ms": 3760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "build-sentence", "title": "Building sentences with tiles", "locale": "en-US", "subject": "mixed", "objectives": ["Test the build_sentence exercise in isolation", "Confirm that each type of the arrange family is generated and renders correctly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sentence", "xp": 10, "type": "build_sentence", "hints": ["Hint 1: The sentence starts with ''Dina''.", "Hint 2: After ''Dina'' comes ''decide''."], "title": "Order the words", "payload": {"slots": 6, "tokens": [{"id": "t1", "text_md": "Dina"}, {"id": "t2", "text_md": "decides"}, {"id": "t3", "text_md": "to save"}, {"id": "t4", "text_md": "her"}, {"id": "t5", "text_md": "5"}, {"id": "t6", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As you saw yesterday, Dina saved 3 pesos. Today she has 5 pesos. Should she buy a pencil or save? Help her decide by ordering the words to form her thought.", "difficulty": 1, "explanation_md": "The correct sentence is ''Dina decides to save her 5 pesos''. Saving is keeping money to use later. Great job!", "audio_segment_id": "s1-build-sentence.prompt"}], "schema_version": 1}', '{"s1-build-sentence": {"order": ["t1", "t2", "t3", "t4", "t5", "t6"]}}', '{"units": {"s1-build-sentence.prompt": {"url": "http://localhost:4006/files/lesson-audio/49fdfaf7d3c204d1bb7108cb40e82c0b568522a5431eeea38c7ddcbbacbfa0ee.mp3", "hash": "e06dfd5513a8464d0d084bf6557572d829dbca4c59ca88cacf2ff85069e9b19f", "bytes": 63648, "voice": "Jennifer", "file_id": "lesson-audio/49fdfaf7d3c204d1bb7108cb40e82c0b568522a5431eeea38c7ddcbbacbfa0ee.mp3", "duration_ms": 10560}, "s1-build-sentence.explanation": {"url": "http://localhost:4006/files/lesson-audio/8ce0b4a2a93f12888def6a2898db8e6e27e2cbf68bf1a0d5eeeb787b70f602ec.mp3", "hash": "596049ba579459b8956cef479d197c5b0c6b32c80d7bf8de6c9241bb34180fcf", "bytes": 50256, "voice": "Jennifer", "file_id": "lesson-audio/8ce0b4a2a93f12888def6a2898db8e6e27e2cbf68bf1a0d5eeeb787b70f602ec.mp3", "duration_ms": 8320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "fair-trade", "title": "Fair Trade: Is It Fair?", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''fair_trade'' exercise in isolation.", "Evaluate whether a trade is fair using reference prices."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Compare the value of each item. How much does the toy cost? How much do the treats cost?"], "title": "Fair Trade: Is It Fair?", "payload": {"offer_a": {"qty": 1, "icon": "toy", "label": "Toy"}, "offer_b": {"qty": 1, "icon": "snack", "label": "Treats"}, "rate_md": "1 toy (80 MXN) for 1 bag of treats (15 MXN)"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina wants to trade her toy (worth 80 MXN) for a bag of treats (worth 15 MXN). Is the trade fair?", "difficulty": 1, "explanation_md": "The toy is worth 80 MXN and the treats are worth 15 MXN. 80 is greater than 15, so Dina would be giving much more than she receives. The trade is not fair.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "a_wins"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/d033b4b8f3b9e8c19fbd1ca2c9d59129654a78007236fe18aa8a1f6f55b6dd5c.mp3", "hash": "c10bf849e6726af10f784b6ffa44e8833a75860c33828d7ba69a64228c7312e3", "bytes": 44496, "voice": "Jennifer", "file_id": "lesson-audio/d033b4b8f3b9e8c19fbd1ca2c9d59129654a78007236fe18aa8a1f6f55b6dd5c.mp3", "duration_ms": 7360}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/ae4c01aa00f523815dec6151419e3d20dac8e29a03d9511f7a7e17cb59aaec55.mp3", "hash": "d0251b7f7a7daf8808b741d7b02c2740bdc39cb559afcba8ca8fde9073c16cda", "bytes": 65664, "voice": "Jennifer", "file_id": "lesson-audio/ae4c01aa00f523815dec6151419e3d20dac8e29a03d9511f7a7e17cb59aaec55.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "Suspicious signs in an ad", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''red_flags'' exercise in isolation.", "Identify suspicious signs in a fake ad."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Think about promises that seem too good to be true.", "Notice the details that ask for personal information."], "title": "What signs do you see?", "payload": {"flags": [{"id": "flag-1", "text_md": "Promise of something free without clear conditions"}, {"id": "flag-2", "text_md": "Requests sensitive personal information"}, {"id": "flag-3", "text_md": "Urgency: ''only today'' to pressure quick decisions"}, {"id": "flag-4", "text_md": "No company details or real contact information"}], "artifact_md": "Win a **FREE** tablet! Just answer 3 questions. Send your name, address, and phone number to claim. Offer valid only today!", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "As we learned yesterday about trustworthy ads, today we''ll look at warning signs. Zara found an ad online that promises a **free** tablet just for filling out a survey. She suspects it''s a scam. Dina, Liruf, and Rho are also looking at the ad and want to help. Together, identify the **warning signs**. For example, Zara says: ''Promising something for free without clear conditions is suspicious.'' What other signs do you see?", "difficulty": 1, "explanation_md": "Warning signs are clues that something might be a fraud. In this ad, exaggerated promises and requests for personal data are red flags.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag-1", "flag-2", "flag-3", "flag-4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/876281938670a9f3f2c769d0e08acf7b0314938fc951108a19a679ac8351dd8c.mp3", "hash": "f33699cd421e23e12571f7ee0a64f231261501bda93eb8002548eae4e5d4b70d", "bytes": 161136, "voice": "Jennifer", "file_id": "lesson-audio/876281938670a9f3f2c769d0e08acf7b0314938fc951108a19a679ac8351dd8c.mp3", "duration_ms": 26800}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/81dcf8e1bb242471cb7d25be5578bfbf6532db6b09433f214a29d74d23b4d27b.mp3", "hash": "b53af99e61a63ed9228ba719c52797b43d828b7d3765ce70a7410eaf6cbbef7b", "bytes": 49824, "voice": "Jennifer", "file_id": "lesson-audio/81dcf8e1bb242471cb7d25be5578bfbf6532db6b09433f214a29d74d23b4d27b.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "dialogue-choice", "title": "Diálogo con Rho: Elige tu respuesta", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''dialogue_choice'' de forma aislada (flujo de diálogo)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue-choice", "xp": 0, "type": "dialogue_choice", "hints": ["Piensa en lo que aprendiste antes sobre intercambios: ¿es justo cambiar 5 manzanas por 3 naranjas? Recuerda que 1 manzana = 1 moneda, 1 naranja = 2 monedas.", "Si dudas, puedes pedir tiempo para pensar, pero a veces hay que decidir rápido."], "title": "Elige tu respuesta", "payload": {"turns": [{"id": "turn-1", "npc_md": "¡Hola Rho! Tengo 5 manzanas y quiero cambiarlas por 3 de tus naranjas. ¿Qué te parece?", "replies": [{"id": "reply-1a", "text_md": "Claro, acepto el intercambio."}, {"id": "reply-1b", "text_md": "No, prefiero quedarme con mis naranjas."}, {"id": "reply-1c", "text_md": "Déjame pensarlo un momento."}]}, {"id": "turn-2", "npc_md": "Está bien, pero si no aceptas ahora, tal vez no tenga más manzanas después. ¿Qué dices?", "replies": [{"id": "reply-2a", "text_md": "Está bien, hagamos el cambio."}, {"id": "reply-2b", "text_md": "No, gracias, mejor no."}, {"id": "reply-2c", "text_md": "Necesito consultarlo con alguien más."}]}], "persona": {"name": "Rho", "role_md": "Un explorador curioso que siempre pregunta antes de actuar.", "character": "rho"}, "opening_md": "Rho se encuentra con un amigo en el mercado. El amigo le ofrece un intercambio. Rho recuerda que en la clase anterior aprendió a comparar cantidades usando valores. ¿Será un buen trato?"}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho necesita tu ayuda para decidir qué responder. Lee cada opción y elige la que creas mejor. Recuerda que en la lección anterior aprendiste que los intercambios justos tienen valor total igual. Por ejemplo, si 1 manzana vale 1 moneda y 1 naranja vale 2 monedas, entonces 5 manzanas (5 monedas) no son equivalentes a 3 naranjas (6 monedas). ¿Qué harías tú?", "difficulty": 1, "explanation_md": "En este ejercicio practicas cómo elegir una respuesta en un diálogo. Cada elección puede cambiar la historia. Fíjate en las consecuencias de cada opción.", "audio_segment_id": "s1-dialogue-choice.prompt"}], "schema_version": 1}', '{"s1-dialogue-choice": {"turns": [{"turn_id": "turn-1", "qualities": {"decisión": 1}, "reactions": {"reply-1a": "aceptó", "reply-1b": "rechazó", "reply-1c": "dudó"}}, {"turn_id": "turn-2", "qualities": {"decisión": 1}, "reactions": {"reply-2a": "aceptó", "reply-2b": "rechazó", "reply-2c": "dudó"}}]}}', '{"units": {"s1-dialogue-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/67b2c62899a453fae2fb225808c9ce5353fd8f544a8cb11918b4e60ef87ea094.mp3", "hash": "f16feb531918da9050e7e0426b6e38ce9485c2eb93f88129e29aa607e88d7247", "bytes": 144288, "voice": "Li", "file_id": "lesson-audio/67b2c62899a453fae2fb225808c9ce5353fd8f544a8cb11918b4e60ef87ea094.mp3", "duration_ms": 24000}, "s1-dialogue-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/67913f66912417cf00e06d7187d752d6df00bfb5cd9d9948764264f0e1bad8f5.mp3", "hash": "0a65c6fbde6ac92f6da74a81fd2f7957e8fdd67e74a09fb906ead30a073bb1be", "bytes": 45936, "voice": "Li", "file_id": "lesson-audio/67913f66912417cf00e06d7187d752d6df00bfb5cd9d9948764264f0e1bad8f5.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "dialogue-choice", "title": "Dialogue with Rho: Choose Your Response", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''dialogue_choice'' exercise in isolation (dialogue flow)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue-choice", "xp": 0, "type": "dialogue_choice", "hints": ["Think about what you learned before about trades: is it fair to trade 5 apples for 3 oranges? Remember, 1 apple = 1 coin, 1 orange = 2 coins.", "If you''re unsure, you can ask for time to think, but sometimes you have to decide quickly."], "title": "Choose Your Response", "payload": {"turns": [{"id": "turn-1", "npc_md": "Hi Rho! I have 5 apples and I want to trade them for 3 of your oranges. What do you think?", "replies": [{"id": "reply-1a", "text_md": "Sure, I accept the trade."}, {"id": "reply-1b", "text_md": "No, I''d rather keep my oranges."}, {"id": "reply-1c", "text_md": "Let me think about it for a moment."}]}, {"id": "turn-2", "npc_md": "Okay, but if you don''t accept now, I might not have any more apples later. What do you say?", "replies": [{"id": "reply-2a", "text_md": "Okay, let''s make the trade."}, {"id": "reply-2b", "text_md": "No thanks, better not."}, {"id": "reply-2c", "text_md": "I need to check with someone else."}]}], "persona": {"name": "Rho", "role_md": "A curious explorer who always asks before acting.", "character": "rho"}, "opening_md": "Rho meets a friend at the market. The friend offers a trade. Rho remembers from the previous class how to compare amounts using values. Will it be a good deal?"}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho needs your help to decide what to say. Read each option and choose the one you think is best. Remember, in the previous lesson you learned that fair trades have equal total value. For example, if 1 apple is worth 1 coin and 1 orange is worth 2 coins, then 5 apples (5 coins) are not equivalent to 3 oranges (6 coins). What would you do?", "difficulty": 1, "explanation_md": "In this exercise, you practice how to choose a response in a dialogue. Each choice can change the story. Pay attention to the consequences of each option.", "audio_segment_id": "s1-dialogue-choice.prompt"}], "schema_version": 1}', '{"s1-dialogue-choice": {"turns": [{"turn_id": "turn-1", "qualities": {"decisión": 1}, "reactions": {"reply-1a": "aceptó", "reply-1b": "rechazó", "reply-1c": "dudó"}}, {"turn_id": "turn-2", "qualities": {"decisión": 1}, "reactions": {"reply-2a": "aceptó", "reply-2b": "rechazó", "reply-2c": "dudó"}}]}}', '{"units": {"s1-dialogue-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/6e02792c835feb81402eaa6deb0b7f116a876d6decd967e1f4673563304ed3fa.mp3", "hash": "a19d3afb61b1627f4f31cd512ff3ea348e841f99369f63268a28a1c56f63806f", "bytes": 133344, "voice": "Jennifer", "file_id": "lesson-audio/6e02792c835feb81402eaa6deb0b7f116a876d6decd967e1f4673563304ed3fa.mp3", "duration_ms": 22160}, "s1-dialogue-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/a093fcc3466e0682a2c8d48439e62b559768f3ea560d4a536942f2ad5b8b8899.mp3", "hash": "b06cbe2c7da6b24c643b58e3897fc0df063b946e1f61e7e778a2b74524ebcfd4", "bytes": 54144, "voice": "Jennifer", "file_id": "lesson-audio/a093fcc3466e0682a2c8d48439e62b559768f3ea560d4a536942f2ad5b8b8899.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "machine-io", "title": "La máquina de funciones de Zara", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio machine_io de forma aislada.", "Confirmar que cada tipo de la familia maker se genera y renderiza correctamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Pista 1: La máquina siempre añade la misma cantidad de dulces.", "Pista 2: De 1 a 6 se añaden 5; de 2 a 7 también 5. Entonces, 3 + 5 = 8."], "title": "Práctica: machine_io", "payload": {"options": [{"id": "opt-a", "text_md": "6"}, {"id": "opt-b", "text_md": "7"}, {"id": "opt-c", "text_md": "8"}, {"id": "opt-d", "text_md": "9"}], "examples": [{"in": 1, "out": 6}, {"in": 2, "out": 7}], "probe_in": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara está construyendo una máquina para repartir dulces de forma justa en su fiesta. Primero, prueba con dulces de verdad: si pone 1 dulce en un plato, añade 5 más para que haya 6. Si pone 2, añade 5 y salen 7. Recuerda cómo Zara repartió dulces la vez pasada: siempre añadía la misma cantidad. ¿Cuántos dulces salen si pone 3?", "difficulty": 1, "explanation_md": "¡Correcto! La regla es: salida = entrada + 5. Por eso, con entrada 3, la salida es 8.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "opt-c"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/8902a9844eb01c1736f24dfe04b817d98433f9fd5eef38e796c639d37d83aba8.mp3", "hash": "62fddf0c3e537f6dfeaf25ccb5fca12edbb7b3e776251c1192183128dad9e8e1", "bytes": 145296, "voice": "Li", "file_id": "lesson-audio/8902a9844eb01c1736f24dfe04b817d98433f9fd5eef38e796c639d37d83aba8.mp3", "duration_ms": 24160}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d10a76e2287a02ab189e81768076c143428ae909de4e00bdaa5b8e92f122df0.mp3", "hash": "023c09fb3e9a794de58d246eba1cb82ed1d77653c65eac3d0dc5765f33ddf297", "bytes": 57024, "voice": "Li", "file_id": "lesson-audio/0d10a76e2287a02ab189e81768076c143428ae909de4e00bdaa5b8e92f122df0.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "machine-io", "title": "A máquina de funções de Zara", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício machine_io de forma isolada.", "Confirmar que cada tipo da família maker é gerado e renderizado corretamente."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Dica 1: A máquina sempre adiciona a mesma quantidade de doces.", "Dica 2: De 1 para 6 adiciona-se 5; de 2 para 7 também 5. Então, 3 + 5 = 8."], "title": "Prática: machine_io", "payload": {"options": [{"id": "opt-a", "text_md": "6"}, {"id": "opt-b", "text_md": "7"}, {"id": "opt-c", "text_md": "8"}, {"id": "opt-d", "text_md": "9"}], "examples": [{"in": 1, "out": 6}, {"in": 2, "out": 7}], "probe_in": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara está construindo uma máquina para distribuir doces de forma justa na sua festa. Primeiro, ela testa com doces de verdade: se coloca 1 doce em um prato, adiciona 5 mais para que fique 6. Se coloca 2, adiciona 5 e dá 7. Lembra como Zara distribuiu doces da última vez? Ela sempre adicionava a mesma quantidade. Quantos doces saem se ela colocar 3?", "difficulty": 1, "explanation_md": "Correto! A regra é: saída = entrada + 5. Por isso, com entrada 3, a saída é 8.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "opt-c"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/f55d84d29d99cacbc4d9580df20f7e1863a0e3bf2f71e1873ba2f76180d53750.mp3", "hash": "7198f48dae42c461632206bedd38cf72fdf679f3425a3f30f3d1efd15c5379fa", "bytes": 145296, "voice": "Ryan", "file_id": "lesson-audio/f55d84d29d99cacbc4d9580df20f7e1863a0e3bf2f71e1873ba2f76180d53750.mp3", "duration_ms": 24160}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/1c0595cb90b53a36e0de61b1e60758da4f8f046be270c8266588c15519b16666.mp3", "hash": "763c0f4cfa340a4d05b123e9e079dd4033d168b73a90c280ddd9e844c4c74152", "bytes": 50688, "voice": "Ryan", "file_id": "lesson-audio/1c0595cb90b53a36e0de61b1e60758da4f8f046be270c8266588c15519b16666.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "yes-no-cases", "title": "¿Comprar o ahorrar?", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si comprar un juguete o ahorrar las monedas, aplicando una regla de gasto responsable."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": [], "title": "¿Comprar o ahorrar?", "payload": {"cases": [{"id": "caso1", "text_md": "**Sí**, comprar el carrito (8 monedas) y ahorrar las 2 que sobran."}, {"id": "caso2", "text_md": "**No**, comprar el carrito y también un helado de 3 monedas, gastando 11 monedas."}, {"id": "caso3", "text_md": "**Sí**, no comprar nada y ahorrar las 10 monedas para la pelota."}], "rule_md": "Solo gastar si te sobra suficiente para ahorrar al menos la mitad de lo que tienes."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho tiene 10 monedas. Quiere comprar un carrito de juguete que cuesta 8 monedas, pero también quiere ahorrar para una pelota que cuesta 12 monedas. Ayuda a Rho a decidir si cada opción es una buena elección según la regla: **Solo gastar si te sobra suficiente para ahorrar al menos la mitad de lo que tienes**.", "difficulty": 1, "explanation_md": "¡Muy bien! Rho aprendió a pensar antes de gastar. Si gastas mucho, no te queda para ahorrar.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["caso1", "caso3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/8555751a8c18be2f4b9708f722d6314a1a2562b521994fdbff7d9b75e767748f.mp3", "hash": "0ac97c0cabd78383dfbf1a57275986a5f6caa63da1aab59ea55be986ce216c2f", "bytes": 112176, "voice": "Li", "file_id": "lesson-audio/8555751a8c18be2f4b9708f722d6314a1a2562b521994fdbff7d9b75e767748f.mp3", "duration_ms": 18640}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/02535ec6a1f1003bd66930510f52a0f38f6f7f92d9c80e965ce1759f3cd20fcc.mp3", "hash": "dcb25df97d33014aa5783dd763247ac5a7ffb0c05214e049695e82e7d0cd63de", "bytes": 34848, "voice": "Li", "file_id": "lesson-audio/02535ec6a1f1003bd66930510f52a0f38f6f7f92d9c80e965ce1759f3cd20fcc.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
